(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("theocritus-idylls-e", [{"sp": "HDR", "t": "Εἰδύλλια καὶ Ἐπιγράμματα"}, {"sp": "SEC", "t": "Αʹ — Θύρσις ἢ ᾠδή", "st": "1"}, {"sp": "Θύρσις", "t": "Ἁδύ τι τὸ ψιθύρισμα καὶ ἁ πίτυς αἰπόλε τήνα,<br>ἃ ποτὶ ταῖς παγαῖσι μελίσδεται, ἁδὺ δὲ καὶ τὺ<br>συρίσδες· μετὰ Πᾶνα τὸ δεύτερον ἆθλον ἀποισῇ.<br>αἴκα τῆνος ἕλῃ κεραὸν τράγον, αἶγα τὺ λαψῇ.<br>αἴκα δ’ αἶγα λάβῃ τῆνος γέρας, ἐς τὲ καταρρεῖ<br>ἁ χίμαρος· χιμάρω δὲ καλὸν κρέας, ἕστέ κ’ ἀμέλξῃς.", "st": "1"}, {"sp": "Αἴπολος", "t": "Ἅδιον ὦ ποιμὴν τὸ τεὸν μέλος ἢ τὸ καταχὲς<br>τῆν’ ἀπὸ τᾶς πέτρας καταλείβεται ὑψόθεν ὕδωρ.<br>αἴκα ταὶ Μοῖσαι τὰν οἰίδα δῶρον ἄγωνται,<br>ἄρνα τὺ σακίταν λαψῇ γέρας· αἰ δέ κ’ ἀρέσκῃ<br>τήναις ἄρνα λαβεῖν, τὺ δὲ τὰν ὄιν ὕστερον ἀξῇ.", "st": "1"}, {"sp": "Θύρσις", "t": "λῇς ποτὶ τᾶν Νυμφᾶν, λῇς αἰπόλε τεῖδε καθίξας,<br>ὡς τὸ κάταντες τοῦτο γεώλοφον αἵ τε μυρῖκαι,<br>συρίσδεν; τὰς δ’ αἶγας ἐγὼν ἐν τῷδε νομευσῶ.", "st": "1"}, {"sp": "Αἴπολος", "t": "οὐ θέμις ὦ ποιμὴν τὸ μεσαμβρινόν, οὐ θέμις ἄμμιν<br>συρίσδεν. τὸν Πᾶνα δεδοίκαμες· ἦ γὰρ ἀπ’ ἄγρας<br>τανίκα κεκμακὼς ἀμπαύεται· ἔστι δὲ πικρός,<br>καί οἱ ἀεὶ δριμεῖα χολὰ ποτὶ ῥινὶ κάθηται.<br>ἀλλὰ τὺ γὰρ δὴ Θύρσι τὰ Δάφνιδος ἄλγε’ ἀείδες<br>καὶ τᾶς βουκολικᾶς ἐπὶ τὸ πλέον ἵκεο μοίσας,<br>δεῦρ’ ὑπὸ τὰν πτελέαν ἑσδώμεθα, τῶ τε Πριήπω<br>καὶ τᾶν Κραναιᾶν κατεναντίον, ᾇπερ ὁ θῶκος<br>τῆνος ὁ ποιμενικὸς καὶ ταὶ δρύες. αἰ δέ κ’ ἀείσῃς<br>ὡς ὅκα τὸν Λιβύαθε ποτὶ Χρόμιν ᾆσας ἐρίσδων,<br>αἶγα δέ τοι δωσῶ διδυματόκον ἐς τρὶς ἀμέλξαι,<br>ἃ δύ’ ἔχοισ’ ἐρίφως ποταμέλγεται ἐς δύο πέλλας,<br>καὶ βαθὺ κισσύβιον κεκλυσμένον ἁδέι κηρῷ,<br>ἀμφῶες, νεοτευχές, ἔτι γλυφάνοιο ποτόσδον.<br>τῶ περὶ μὲν χείλη μαρύεται ὑψόθι κισσός,<br>κισσὸς ἑλιχρύσῳ κεκονιμένος· ἁ δὲ κατ’ αὐτὸν<br>καρπῷ ἕλιξ εἱλεῖται ἀγαλλομένα κροκόεντι.<br>ἔντοσθεν δὲ γυνά, τὶ θεῶν δαίδαλμα τέτυκται,<br>ἀσκητὰ πέπλῳ τε καὶ ἄμπυκι. πὰρ δέ οἱ ἄνδρες<br>καλὸν ἐθειράζοντες ἀμοιβαδὶς ἄλλοθεν ἄλλος<br>νεικείουσ’ ἐπέεσσι. τὰ δ’ οὐ φρενὸς ἅπτεται αὐτᾶς·<br>ἀλλ’ ὁκὰ μὲν τῆνον ποτιδέρκεται ἄνδρα γελᾶσα,<br>ἄλλοκα δ’ αὖ ποτὶ τὸν ῥιπτεῖ νόον. οἱ δ’ ὑπ’ ἔρωτος<br>δηθὰ κυλοιδιόωντες ἐτώσια μοχθίζοντι.<br>τοῖς δὲ μετὰ γριπεύς τε γέρων πέτρα τε τέτυκται<br>λεπράς, ἐφ’ ᾇ σπεύδων μέγα δίκτυον ἐς βόλον ἕλκει<br>ὁ πρέσβυς, κάμνοντι τὸ καρτερὸν ἀνδρὶ ἐοικώς.<br>φαίης κεν γυίων νιν ὅσον σθένος ἐλλοπιεύειν·<br>ὧδέ οἱ ᾠδήκαντι κατ’ αὐχένα πάντοθεν ἶνες<br>καὶ πολιῷ περ ἐόντι, τὸ δὲ σθένος ἄξιον ἅβας.<br>τυτθὸν δ’ ὅσσον ἄπωθεν ἁλιτρύτοιο γέροντος<br>Πυρναίαις σταφυλαῖσι καλὸν βέβριθεν ἀλωά,<br>τὰν ὀλίγος τις κῶρος ἐφ’ αἱμασιαῖσι φυλάσσει<br>ἥμενος· ἀμφὶ δέ νιν δύ’ ἀλώπεκες ἁ μὲν ἀν’ ὄρχως<br>φοιτῇ σινομένα τὰν τρώξιμον, ἁ δ’ ἐπὶ πήρᾳ<br>πάντα δόλον κεύθοισα τὸ παιδίον οὐ πρὶν ἀνησεῖν<br>φατὶ πρὶν ἢ ἀκράτιστον ἐπὶ ξηροῖσι καθίξῃ.<br>αὐτὰρ ὅγ’ ἀνθερίκοισι καλὰν πλέκει ἀκριδοθήραν<br>σχοίνῳ ἐφαρμόσδων· μέλεται δέ οἱ οὔτέ τι πήρας<br>οὔτε φυτῶν τοσσῆνον, ὅσον περὶ πλέγματι γαθεῖ.<br>παντᾷ δ’ ἀμφὶ δέπας περιπέπταται ὑγρὸς ἄκανθος·<br>αἰολικόν τι θέαμα, τέρας κέ τυ θυμὸν ἀτύξαι.<br>τῶ μὲν ἐγὼ πορθμεῖ Καλυδωνίῳ αἶγά τ’ ἔδωκα<br>ὦνον καὶ τυρόεντα μέγαν λευκοῖο γάλακτος·<br>οὐδέ τί πω ποτὶ χεῖλος ἐμὸν θίγεν, ἀλλ’ ἔτι κεῖται<br>ἄχραντον. τῷ καί τυ μάλα πρόφρων ἀρεσαίμαν,<br>αἴκά μοι τὺ φίλος τὸν ἐφίμερον ὕμνον ἀείσῃς.<br>κοὔτί τυ κερτομέω. πόταγ’ ὦγαθέ· τὰν γὰρ ἀοιδὰν<br>οὔτί πᾳ εἰς Ἀίδαν γε τὸν ἐκλελάθοντα φυλαξεῖς.", "st": "1"}, {"sp": "Θύρσις", "t": "Ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>Θύρσις ὅδ’ ὡξ Αἴτνας, καὶ Θύρσιδος ἁδέα φωνά.<br>πᾷ ποκ’ ἄρ’ ἦσθ’, ὅκα Δάφνις ἐτάκετο, πᾷ ποκα Νύμφαι;<br>ἢ κατὰ Πηνειῶ καλὰ τέμπεα; ἢ κατὰ Πίνδω;<br>οὐ γὰρ δὴ ποταμοῖο μέγαν ῥόον εἴχετ’ Ἀνάπω,<br>οὐδ’ Αἴτνας σκοπιάν, οὐδ’ Ἄκιδος ἱερὸν ὕδωρ.<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>τῆνον μὰν θῶες, τῆνον λύκοι ὠρύσαντο,<br>τῆνον χὡκ δρυμοῖο λέων ἔκλαυσε θανόντα.<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>πολλαί οἱ πὰρ ποσσὶ βόες, πολλοὶ δέ τε ταῦροι,<br>πολλαὶ δ’ αὖ δαμάλαι καὶ πόρτιες ὠδύραντο.<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>ἦνθ’ Ἑρμῆς πράτιστος ἀπ’ ὤρεος, εἶπε δέ· “Δάφνι,<br>τίς τυ κατατρύχει; τίνος ὦγαθὲ τόσσον ἐρᾶσαι;”<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>ἦνθον τοὶ βοῦται, τοὶ ποιμένες, ᾡπόλοι ἦνθον·<br>πάντες ἀνηρώτευν, τί πάθοι κακόν. ἦνθ’ ὁ Πρίηπος<br>κἤφα· “Δάφνι τάλαν, τί τὺ τάκεαι, ἁ δέ τε κώρα<br>πάσας ἀνὰ κράνας, πάντ’ ἄλσεα ποσσὶ φορεῖται—<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς—<br>ζάτεισ’; ἆ δύσερώς τις ἄγαν καὶ ἀμήχανος ἐσσί.<br>βούτας μὰν ἐλέγευ, νῦν δ’ αἰπόλῳ ἀνδρὶ ἔοικας.<br>ᾡπόλος ὅκκ’ ἐσορῇ τὰς μηκάδας οἷα βατεῦνται,<br>τάκεται ὀφθαλμώς, ὅτι οὐ τράγος αὐτὸς ἔγεντο.<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>καὶ τὺ δ’ ἐπεί κ’ ἐσορῇς τὰς παρθένος οἷα γελᾶντι,<br>τάκεαι ὀφθαλμώς, ὅτι οὐ μετὰ ταῖσι χορεύεις.”<br>τὼς δ’ οὐδὲν ποτελέξαθ’ ὁ βουκόλος, ἀλλὰ τὸν αὐτῶ<br>ἄνυε πικρὸν ἔρωτα, καὶ ἐς τέλος ἄνυε μοίρας·<br>ἄρχετε βουκολικᾶς Μοῖσαι πάλιν ἄρχετ’ ἀοιδᾶς.<br>ἦνθέ γε μὰν ἁδεῖα καὶ ἁ Κύπρις γελάοισα,<br>λάθρια μὲν γελάοισα, βαρὺν δ’ ἀνὰ θυμὸν ἔχοισα,<br>κεἶπε· “τύ θην τὸν Ἔρωτα κατεύχεο Δάφνι λυγιξεῖν·<br>ἦ ῥ’ οὐκ αὐτὸς Ἔρωτος ὑπ’ ἀργαλέω ἐλυγίχθης;”<br>ἄρχετε βουκολικᾶς Μοῖσαι πάλιν ἄρχετ’ ἀοιδᾶς.<br>τὰν δ’ ἄρα χὡ Δάφνις ποταμείβετο· “Κύπρι βαρεῖα,<br>Κύπρι νεμεσσατά, Κύπρι θνατοῖσιν ἀπεχθής·<br>ἤδη γὰρ φράσδῃ πάνθ’ ἅλιον ἄμμι δεδύκειν·<br>Δάφνις κἠν Ἀίδα κακὸν ἔσσεται ἄλγος Ἔρωτι.<br>ἄρχετε βουκολικᾶς Μοῖσαι πάλιν ἄρχετ’ ἀοιδᾶς.<br>†οὗ λέγεται τὰν Κύπριν ὁ βουκόλος—ἕρπε ποτ’ Ἴδαν,<br>ἕρπε ποτ’ Ἀγχίσην. τηνεῖ δρύες, ἅ τε κύπειρος·<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>ὡραῖος χὥδωνις, ἐπεὶ καὶ μῆλα νομεύει.<br>καὶ πτῶκας βάλλει καὶ θηρία πάντα διώκει.<br>ἄρχετε βουκολικᾶς Μοῖσαι φίλαι ἄρχετ’ ἀοιδᾶς.<br>αὖθις ὅπως στασῇ Διομήδεος ἆσσον ἰοῖσα,<br>καὶ λέγε· τὸν βούταν νικῶ Δάφνιν, ἀλλὰ μάχευ μοι.”<br>ἄρχετε βουκολικᾶς Μοῖσαι πάλιν ἄρχετ’ ἀοιδᾶς.<br>ὦ λύκοι, ὦ θῶες, ὦ ἀν’ ὤρεα φωλάδες ἄρκτοι,<br>χαίρεθ’. ὁ βουκόλος ὔμμιν ἐγὼ Δάφνις οὐκέτ’ ἀν’ ὕλαν,<br>οὐκέτ’ ἀνὰ δρυμώς, οὐκ ἄλσεα. χαῖρ’ Ἀρέθοισα,<br>καὶ ποταμοί, τοὶ χεῖτε καλὸν κατὰ Θύμβριδος ὕδωρ.<br>ἄρχετε βουκολικᾶς Μοῖσαι πάλιν ἄρχετ’ ἀοιδᾶς.<br>Δάφνις ἐγὼν ὅδε τῆνος ὁ τὰς βόας ὧδε νομεύων,<br>Δάφνις ὁ τὼς ταύρως καὶ πόρτιας ὧδε ποτίσδων.<br>ἄρχετε βουκολικᾶς Μοῖσαι πάλιν ἄρχετ’ ἀοιδᾶς.<br>ὦ Πὰν Πάν, εἴτ’ ἐσσὶ κατ’ ὤρεα μακρὰ Λυκαίω,<br>εἴτε τύ γ’ ἀμφιπολεῖς μέγα Μαίναλον, ἔνθ’ ἐπὶ νᾶσον<br>τὰν Σικελάν, Ἑλίκας δὲ λίπ’ ἠρίον αἰπύ τε σᾶμα<br>τῆνο Λυκαονίδαο, τὸ καὶ μακάρεσσιν ἀγητόν.<br>λήγετε βουκολικᾶς Μοῖσαι ἴτε λήγετ’ ἀοιδᾶς.<br>ἔνθ’ ὦναξ καὶ τάνδε φέρευ πακτοῖο μελίπνουν<br>ἐκ κηρῶ σύριγγα καλάν, περὶ χεῖλος ἑλικτάν.<br>ἦ γὰρ ἐγὼν ὑπ’ ἔρωτος ἐς Ἅιδαν ἕλκομαι ἤδη.<br>λήγετε βουκολικᾶς Μοῖσαι ἴτε λήγετ’ ἀοιδᾶς.<br>νῦν δ’ ἴα μὲν φορέοιτε βάτοι, φορέοιτε δ’ ἄκανθαι,<br>ἁ δὲ καλὰ νάρκισσος ἐπ’ ἀρκεύθοισι κομάσαι·<br>[πάντα δ’ ἔναλλα γένοιτο, καὶ ἁ πίτυς ὄχνας ἐνείκαι.]<br>Δάφνις ἐπεὶ θνάσκει· καὶ τὼς κύνας ὥλαφος ἕλκοι,<br>κἠξ ὀρέων τοὶ σκῶπες ἀηδόσι γαρύσαιντο.<br>λήγετε βουκολικᾶς Μοῖσαι ἴτε λήγετ’ ἀοιδᾶς.<br>χὡ μὲν τόσσ’ εἰπὼν ἀπεπαύσατο· τὸν δ’ Ἀφροδίτα<br>ἤθελ’ ἀνορθῶσαι· τά γε μὰν λίνα πάντα λελοίπει<br>ἐκ Μοιρᾶν, χὡ Δάφνις ἔβα ῥόον. ἔκλυσε δίνα<br>τὸν Μοίσαις φίλον ἄνδρα, τὸν οὐ Νύμφαισιν ἀπεχθῆ.<br>λήγετε βουκολικᾶς Μοῖσαι ἴτε λήγετ’ ἀοιδᾶς.<br>καὶ τὺ δίδου τὰν αἶγα τό τε σκύφος, ὥς κεν ἀμέλξας<br>σπείσω ταῖς Μοίσαις. ὦ χαίρετε πολλάκι Μοῖσαι,<br>χαίρετ’· ἐγὼ δ’ ὔμμιν καὶ ἐς ὕστερον ἅδιον ᾀσῶ.", "st": "1"}, {"sp": "Αἴπολος", "t": "πλῆρές τοι μέλιτος τὸ καλὸν στόμα Θύρσι γένοιτο,<br>πλῆρές τοι σχαδόνων, καὶ ἀπ’ Αἰγίλω ἰσχάδα τρώγοις<br>ἁδεῖαν, τέττιγος ἐπεὶ τύγα φέρτερον ᾄδεις.<br>ἠνίδε τοι τὸ δέπας· θᾶσαι φίλος, ὡς καλὸν ὄσδει·<br>Ὡρᾶν πεπλύσθαί νιν ἐπὶ κράναισι δοκησεῖς.<br>ὧδ’ ἴθι Κισσαίθα, τὺ δ’ ἄμελγέ νιν. αἱ δὲ χίμαιραι,<br>οὐ μὴ σκιρτασεῖτε, μὴ ὁ τράγος ὔμμιν ἀναστῇ.", "st": "1"}, {"sp": "SEC", "t": "Βʹ — Φαρμακεύτριαι", "st": "2"}, {"sp": "N", "t": "πᾷ μοι ταὶ δάφναι; φέρε Θεστυλί· πᾷ δὲ τὰ φίλτρα;<br>στέψον τὰν κελέβαν φοινικέῳ οἰὸς ἀώτῳ,<br>ὡς τὸν ἐμὸν βαρὺν εὖντα φίλον καταθύσομαι ἄνδρα,<br>ὅς μοι δωδεκαταῖος ἀφ’ ὧ τάλας οὐδέποθ’ ἵκει,<br>οὐδ’ ἔγνω πότερον τεθνάκαμες ἢ ζοοὶ εἰμές.<br>οὐδὲ θύρας ἄραξεν ἀνάρσιος. ἦ ῥά οἱ ἀλλᾷ<br>ᾤχετ’ ἔχων ὅ τ’ Ἔρως ταχινὰς φρένας ἅ τ’ Ἀφροδίτα;<br>βασεῦμαι ποτὶ τὰν Τιμαγήτοιο παλαίστραν<br>αὔριον, ὥς νιν ἴδω, καὶ μέμψομαι οἷά με ποιεῖ.<br>νῦν δέ νιν ἐκ θυέων καταθύσομαι. ἀλλὰ Σελάνα,<br>φαῖνε καλόν· τὶν γὰρ ποταείσομαι ἅσυχα, δαῖμον,<br>τᾷ χθονίᾳ θ’ Ἑκάτᾳ, τὰν καὶ σκύλακες τρομέοντι<br>ἐρχομέναν νεκύων ἀνά τ’ ἠρία καὶ μέλαν αἷμα.", "st": "2"}, {"sp": "N", "t": "χαῖρ’ Ἑκάτα δασπλῆτι, καὶ ἐς τέλος ἄμμιν ὀπάδει.<br>φάρμακα ταῦτ’ ἔρδοισα χερείονα μήτέ τι Κίρκης<br>μήτέ τι Μηδείας μήτε ξανθᾶς Περιμήδας.", "st": "2"}, {"sp": "N", "t": "Ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "ἄλφιτά τοι πρᾶτον πυρὶ τάκεται· ἀλλ’ ἐπίπασσε<br>Θεστυλί. δειλαία, πᾷ τὰς φρένας ἐκπεπότασαι;<br>ἦ ῥά γε τρισμυσαρὰ καὶ τὶν ἐπίχαρμα τέτυγμαι;<br>πάσσ’ ἅμα καὶ λέγε ταῦτα· “τὰ Δέλφιδος ὀστία πάσσω.”", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "Δέλφις ἔμ’ ἀνίασεν· ἐγὼ δ’ ἐπὶ Δέλφιδι δάφναν<br>αἴθω· χὡς αὕτα λακεῖ μέγα καππυρίσασα<br>κἠξαπίνας ἅφθη, κοὐδὲ σποδὸν εἴδομες αὐτᾶς,<br>οὕτω τοι καὶ Δέλφις ἐνὶ φλογὶ σάρκ’ ἀμαθύνοι.", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "ὡς τοῦτον τὸν κηρὸν ἐγὼ σὺν δαίμονι τάκω,<br>ὣς τάκοιθ’ ὑπ’ ἔρωτος ὁ Μύνδιος αὐτίκα Δέλφις.<br>χὡς δινεῖθ’ ὅδε ῥόμβος ὁ χάλκεος ἐξ Ἀφροδίτας,<br>ὣς τῆνος δινοῖτο ποθ’ ἁμετέραισι θύραισιν.", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "νῦν θυσῶ τὰ πίτυρα. τὺ δ’ Ἄρτεμι καὶ τὸν ἐν Ἅιδα<br>κινήσαις ἀδάμαντα καὶ εἴ τί περ ἀσφαλὲς ἄλλο.<br>Θεστυλί, ταὶ κύνες ἄμμιν ἀνὰ πτόλιν ὠρύονται.<br>ἁ θεὸς ἐν τριόδοισι· τὸ χαλκίον ὡς τάχος ἄχει.", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "ἠνίδε σιγῇ μὲν πόντος, σιγῶντι δ’ ἀῆται·<br>ἁ δ’ ἐμὰ οὐ σιγῇ στέρνων ἔντοσθεν ἀνία,<br>ἀλλ’ ἐπὶ τήνῳ πᾶσα καταίθομαι, ὅς με τάλαιναν<br>ἀντὶ γυναικὸς ἔθηκε κακὰν καὶ ἀπάρθενον ἦμεν.", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "ἐς τρὶς ἀποσπένδω καὶ τρὶς τάδε πότνια φωνέω·<br>εἴτε γυνὰ τήνῳ παρακέκλιται εἴτε καὶ ἀνήρ,<br>τόσσον ἔχοι λάθας, ὅσσόν ποκα Θησέα φαντὶ<br>ἐν Δίᾳ λασθῆμεν ἐυπλοκάμω Ἀριάδνας.", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "ἱππομανὲς φυτόν ἐστι παρ’ Ἀρκάσι· τῷ δ’ ἐπὶ πᾶσαι<br>καὶ πῶλοι μαίνονται ἀν’ ὤρεα καὶ θοαὶ ἵπποι.<br>ὣς καὶ Δέλφιν ἴδοιμι, καὶ ἐς τόδε δῶμα περάσαι<br>μαινομένῳ ἴκελος λιπαρᾶς ἔκτοσθε παλαίστρας.", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "τοῦτ’ ἀπὸ τᾶς χλαίνας τὸ κράσπεδον ὤλεσε Δέλφις,<br>ὡγὼ νῦν τίλλοισα κατ’ ἀγρίῳ ἐν πυρὶ βάλλω.<br>αἰαῖ Ἔρως ἀνιηρέ, τί μευ μέλαν ἐκ χροὸς αἷμα<br>ἐμφὺς ὡς λιμνᾶτις ἅπαν ἐκ βδέλλα πέπωκας;", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "σαύραν τοι τρίψασα ποτὸν κακὸν αὔριον οἰσῶ.", "st": "2"}, {"sp": "N", "t": "Θεστυλί, νῦν δὲ λαβοῖσα τὺ τὰ θρόνα ταῦθ’ ὑπόμαξον<br>τᾶς τήνω φλιᾶς καθ’ ὑπέρτερον, ἇς ἔτι καὶ νύξ,<br>καὶ λέγ’ ἐπιφθύζοισα· “τὰ Δέλφιδος ὀστία μάσσω.”", "st": "2"}, {"sp": "N", "t": "ἶυγξ, ἕλκε τὺ τῆνον ἐμὸν ποτὶ δῶμα τὸν ἄνδρα.", "st": "2"}, {"sp": "N", "t": "νῦν δὴ μώνα ἐοῖσα πόθεν τὸν ἔρωτα δακρύσω;<br>ἐκ τίνος ἄρξωμαι; τίς μοι κακὸν ἄγαγε τοῦτο;<br>ἦνθ’ ἁ τῶὐβούλοιο κανηφόρος ἄμμιν Ἀναξὼ<br>ἄλσος ἐς Ἀρτέμιδος, τᾷ δὴ τόκα πολλὰ μὲν ἄλλα<br>θηρία πομπεύεσκε περισταδόν, ἐν δὲ λέαινα.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "καί μ’ ἁ Θευχαρίδα Θρᾷσσα τροφὸς ἁ μακαρῖτις<br>ἀγχίθυρος ναίοισα κατεύξατο καὶ λιτάνευσε<br>τὰν πομπὰν θάσασθαι· ἐγὼ δέ οἱ ἁ μεγάλοιτος<br>ὡμάρτευν βύσσοιο καλὸν σύροισα χιτῶνα,<br>κἀμφιστειλαμένα τὰν ξυστίδα τὰν Κλεαρίστας.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "ἤδη δ’ εὖσα μέσον κατ’ ἀμαξιτόν, ᾇ τὰ Λύκωνος,<br>εἶδον ὁμοῦ Δέλφιν τε καὶ Εὐδάμιππον ἰόντας.<br>τοῖς δ’ ἦν ξανθοτέρα μὲν ἑλιχρύσοιο γενειάς,<br>στήθεα δὲ στίλβοντα πολὺ πλέον ἢ τὺ Σελάνα,<br>ὡς ἀπὸ γυμνασίοιο καλὸν πόνον ἄρτι λιπόντων.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "χὡς ἴδον, ὡς ἐμάνην, ὥς μευ πέρι θυμὸς ἰάφθη<br>δειλαίας· τὸ δὲ κάλλος ἐτάκετο, κοὐδέ τι πομπᾶς<br>τήνας ἐφρασάμαν, οὐδ’ ὡς πάλιν οἴκαδ’ ἀπῆνθον<br>ἔγνων· ἀλλά μέ τις καπυρὰ νόσος ἐξεσάλαξε,<br>κείμαν δ’ ἐν κλιντῆρι δέκ’ ἄματα καὶ δέκα νύκτας.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "καί μευ χρὼς μὲν ὁμοῖος ἐγίνετο πολλάκι θάψῳ,<br>ἔρρευν δ’ ἐκ κεφαλᾶς πᾶσαι τρίχες, αὐτὰ δὲ λοιπὰ<br>ὀστί’ ἔτ’ ἦς καὶ δέρμα. καὶ ἐς τίνος οὐκ ἐπέρασα<br>ἢ ποίας ἔλιπον γραίας δόμον, ἅτις ἐπᾷδεν;<br>ἀλλ’ ἦς οὐδὲν ἐλαφρόν· ὁ δὲ χρόνος ἄνυτο φεύγων.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "χοὕτω τᾷ δούλᾳ τὸν ἀλαθέα μῦθον ἔλεξα·<br>“εἰ δ’ ἄγε Θεστυλί μοι χαλεπᾶς νόσω εὑρέ τι μῆχος.<br>πᾶσαν ἔχει με τάλαιναν ὁ Μύνδιος· ἀλλὰ μολοῖσα<br>τήρησον ποτὶ τὰν Τιμαγήτοιο παλαίστραν·<br>τηνεῖ γὰρ φοιτῇ, τηνεῖ δέ οἱ ἁδὺ καθῆσθαι.”", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "“κἠπεί κά νιν ἐόντα μάθῃς μόνον, ἅσυχα νεῦσον,<br>κεἴφ’ ὅτι Σιμαίθα τυ καλεῖ, καὶ ὑφαγέο τᾷδε.”<br>ὣς ἐφάμαν· ἁ δ’ ἦνθε καὶ ἄγαγε τὸν λιπαρόχρων<br>εἰς ἐμὰ δώματα Δέλφιν· ἐγὼ δέ νιν ὡς ἐνόησα<br>ἄρτι θύρας ὑπὲρ οὐδὸν ἀμειβόμενον ποδὶ κούφῳ—", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα—", "st": "2"}, {"sp": "N", "t": "πᾶσα μὲν ἐψύχθην χιόνος πλέον, ἐν δὲ μετώπῳ<br>ἱδρώς μευ κοχύδεσκεν ἴσον νοτίαισιν ἐέρσαις,<br>οὐδέ τι φωνᾶσαι δυνάμαν, οὐδ’ ὅσσον ἐν ὕπνῳ<br>κνυζεῦνται φωνεῦντα φίλαν ποτὶ ματέρα τέκνα·<br>ἀλλ’ ἐπάγην δαγῦδι καλὸν χρόα πάντοθεν ἴσα.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "καί μ’ ἐσιδὼν ὥστοργος, ἐπὶ χθονὸς ὄμματα πήξας<br>ἕζετ’ ἐπὶ κλιντῆρι καὶ ἑζόμενος φάτο μῦθον·<br>ἦ ῥά με Σιμαίθα τόσον ἔφθασας, ὅσσον ἐγώ θην<br>πρᾶν ποκα τὸν χαρίεντα τρέχων ἔφθασσα Φιλῖνον,<br>ἐς τὸ τεὸν καλέσασα τόδε στέγος ἤ με παρῆμεν.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "ἦνθον γάρ κεν ἐγώ, ναὶ τὸν γλυκὺν ἦνθον Ἔρωτα,<br>ἢ τρίτος ἠὲ τέταρτος ἐὼν φίλος αὐτίκα νυκτός,<br>μᾶλα μὲν ἐν κόλποισι Διωνύσοιο φυλάσσων,<br>κρατὶ δ’ ἔχων λεύκαν, Ἡρακλέος ἱερὸν ἔρνος,<br>πάντοθε πορφυρέαισι περὶ ζώστραισιν ἑλικτάν.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "καί μ’ εἰ μέν κ’ ἐδέχεσθε, τάδ’ ἦς φίλα· καὶ γὰρ ἐλαφρὸς<br>καὶ καλὸς πάντεσσι μετ’ ἠιθέοισι καλεῦμαι·<br>εὗδόν τ’, εἴ κε μόνον τὸ καλὸν στόμα τεῦς ἐφίλασα·<br>εἰ δ’ ἀλλᾷ μ’ ὠθεῖτε καὶ ἁ θύρα εἴχετο μοχλῷ,<br>πάντως κα πελέκεις καὶ λαμπάδες ἦνθον ἐφ’ ὑμέας.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "νῦν δὲ χάριν μὲν ἔφαν τᾷ Κύπριδι πρᾶτον ὀφείλειν,<br>καὶ μετὰ τὰν Κύπριν τύ με δευτέρα ἐκ πυρὸς εἵλευ<br>ὦ γύναι ἐσκαλέσασα τεὸν ποτὶ τοῦτο μέλαθρον<br>αὔτως ἡμίφλεκτον· Ἔρως δ’ ἄρα καὶ Λιπαραίω<br>πολλάκις Ἡφαίστοιο σέλας φλογερώτερον αἴθει.", "st": "2"}, {"sp": "N", "t": "φράζεό μευ τὸν ἔρωθ’ ὅθεν ἵκετο, πότνα Σελάνα.", "st": "2"}, {"sp": "N", "t": "“σὺν δὲ κακαῖς μανίαις καὶ παρθένον ἐκ θαλάμοιο<br>καὶ νύμφαν ἐφόβησ’ ἔτι δέμνια θερμὰ λιποῖσαν<br>ἀνέρος.” ὣς ὁ μὲν εἶπεν· ἐγὼ δέ οἱ ἁ ταχυπειθὴς", "st": "2"}, {"sp": "N", "t": "χειρὸς ἐφαψαμένα μαλακῶν ἔκλιν’ ἐπὶ λέκτρων.<br>καὶ ταχὺ χρὼς ἐπὶ χρωτὶ πεπαίνετο, καὶ τὰ πρόσωπα<br>θερμότερ’ ἦς ἢ πρόσθε, καὶ ἐψιθυρίσδομες ἁδύ·<br>χὥς κά τοι μὴ μακρὰ φίλα θρυλέοιμι Σελάνα,<br>ἐπράχθη τὰ μέγιστα, καὶ ἐς πόθον ἤνθομες ἄμφω.<br>κοὔτέ τι τῆνος ἐμὶν ἐπεμέμψατο μέσφα τό γ’ ἐχθές,<br>οὔτ’ ἐγὼ αὖ τήνῳ. ἀλλ’ ἦνθέ μοι ἅ τε Φιλίστας<br>μάτηρ τᾶς ἀλαᾶς αὐλητρίδος ἅ τε Μελιξοῦς<br>σάμερον, ἁνίκα πέρ τε ποτ’ ὠρανὸν ἔτρεχον ἵπποι<br>Ἀῶ τὰν ῥοδόπαχυν ἀπ’ Ὠκεανοῖο φέροισαι.<br>κεἶπέ μοι ἄλλά τε πολλὰ καὶ ὡς ἄρα Δέλφις ἐρᾶται,<br>κεἴτέ νιν αὖτε γυναικὸς ἔχει πόθος εἴτε καὶ ἀνδρός,<br>οὐκ ἔφατ’ ἀτρεκὲς ἴδμεν, ἀτὰρ τόσον· αἰὲν Ἔρωτος<br>ἀκράτω ἐπεχεῖτο καὶ ἐς τέλος ᾤχετο φεύγων,<br>καὶ φάτο οἱ στεφάνοισι τὰ δώματα τῆνα πυκάσδειν.", "st": "2"}, {"sp": "N", "t": "ταῦτά μοι ἁ ξείνα μυθήσατο· ἔστι δ’ ἀλαθής·<br>ἦ γάρ μοι καὶ τρὶς καὶ τετράκις ἄλλοκ’ ἐφοίτη,<br>καὶ παρ’ ἐμὶν ἐτίθει τὰν Δωρίδα πολλάκις ὄλπαν·<br>νῦν δέ τε δωδεκαταῖος ἀφ’ ὧτέ νιν οὐδὲ ποτεῖδον.<br>ἦ ῥ’ οὐκ ἄλλό τι τερπνὸν ἔχει, ἁμῶν δὲ λέλασται;<br>νῦν μὲν τοῖς φίλτροις καταθύσομαι· αἰ δ’ ἔτι κἠμὲ<br>λυπῇ, τὰν Ἀίδαο πύλαν ναὶ Μοίρας ἀραξεῖ.<br>τοῖά οἱ ἐν κίστᾳ κακὰ φάρμακα φαμὶ φυλάσσειν,<br>Ἀσσυρίω δέσποινα παρὰ ξείνοιο μαθοῖσα.", "st": "2"}, {"sp": "N", "t": "ἀλλὰ τὺ μὲν χαίροισα ποτ’ Ὠκεανὸν τρέπε πώλους,<br>πότνι’· ἐγὼ δ’ οἰσῶ τὸν ἐμὸν πόνον ὥσπερ ὑπέσταν.<br>χαῖρε Σελαναία λιπαρόχροε, χαίρετε δ’ ἄλλοι<br>ἀστέρες, εὐκήλοιο κατ’ ἄντυγα Νυκτὸς ὀπαδοί.", "st": "2"}, {"sp": "SEC", "t": "Γʹ — Κῶμος", "st": "3"}, {"sp": "N", "t": "Κωμάσδω ποτὶ τὰν Ἀμαρυλλίδα, ταὶ δέ μοι αἶγες<br>βόσκονται κατ’ ὄρος, καὶ ὁ Τίτυρος αὐτὰς ἐλαύνει.<br>Τίτυρ’ ἐμὶν τὸ καλὸν πεφιλημένε, βόσκε τὰς αἶγας,<br>καὶ ποτὶ τὰν κράναν ἄγε Τίτυρε, καὶ τὸν ἐνόρχαν<br>τὸν Λιβυκὸν κνάκωνα φυλάσσεο, μή τι κορύψῃ.", "st": "3"}, {"sp": "N", "t": "Ὦ χαρίεσσ’ Ἀμαρυλλί, τί μ’ οὐκέτι τοῦτο κατ’ ἄντρον<br>παρκύπτοισα καλεῖς τὸν ἐρωτύλον; ἦ ῥά με μισεῖς;<br>ἦ ῥά γέ τοι σιμὸς καταφαίνομαι ἐγγύθεν ἦμεν,<br>νύμφα, καὶ προγένειος; ἀπάγξασθαί με ποησεῖς.", "st": "3"}, {"sp": "N", "t": "ἠνίδε τοι δέκα μᾶλα φέρω· τηνῶθε καθεῖλον,<br>ὧ μ’ ἐκέλευ καθελεῖν τύ· καὶ αὔριον ἄλλά τοι οἰσῶ.", "st": "3"}, {"sp": "N", "t": "θᾶσαι μὰν θυμαλγὲς ἐμὸν ἄχος· αἴθε γενοίμαν<br>ἁ βομβεῦσα μέλισσα καὶ ἐς τεὸν ἄντρον ἱκοίμαν<br>τὸν κισσὸν διαδὺς καὶ τὰν πτέριν, ᾇ τὺ πυκάσδῃ.", "st": "3"}, {"sp": "N", "t": "νῦν ἔγνων τὸν Ἔρωτα· βαρὺς θεός· ἦ ῥα λεαίνας<br>μαζὸν ἐθήλαζε, δρυμῷ τέ νιν ἔτραφε μάτηρ,<br>ὅς με κατασμύχων καὶ ἐς ὀστίον ἄχρις ἰάπτει.", "st": "3"}, {"sp": "N", "t": "ὦ τὸ καλὸν ποθορεῦσα, τὸ πᾶν λίθος· ὦ κυάνοφρυ<br>νύμφα, πρόσπτυξαί με τὸν αἰπόλον, ὥς τυ φιλήσω.<br>ἔστι καὶ ἐν κενεοῖσι φιλήμασιν ἁδέα τέρψις.", "st": "3"}, {"sp": "N", "t": "τὸν στέφανον τῖλαί με κατ’ αὐτίκα λεπτὰ ποησεῖς,<br>τόν τοι ἐγὼν Ἀμαρυλλὶ φίλα κισσοῖο φυλάσσω<br>ἀμπλέξας καλύκεσσι καὶ εὐόδμοισι σελίνοις.—<br>Ὤμοι ἐγώ, τί πάθω; τί ὁ δύσσοος; οὐχ ὑπακούεις;—", "st": "3"}, {"sp": "N", "t": "τὰν βαίταν ἀποδὺς ἐς κύματα τηνῶ ἁλεῦμαι,<br>ὧπερ τὼς θύννως σκοπιάζεται Ὄλπις ὁ γριπεύς·<br>καἴκα δἠποθάνω, τό γε μὰν τεὸν ἁδὺ τέτυκται.", "st": "3"}, {"sp": "N", "t": "ἔγνων πρᾶν, ὅκα μευ μεμναμένω, εἰ φιλέεις με,<br>οὐδὲ τὸ τηλέφιλον ποτεμάξατο, τὸ πλατάγημα,<br>ἀλλ’ αὔτως ἁπαλῷ ποτὶ πάχεος ἐξεμαράνθη.", "st": "3"}, {"sp": "N", "t": "εἶπε καὶ ἀγροιῶτις ἀλαθέα κοσκινόμαντις,<br>ἁ πρᾶν ποιολογεῦσα Παραιβάτις, οὕνεκ’ ἐγὼ μὲν<br>τὶν ὅλος ἔγκειμαι, τὺ δέ μευ λόγον οὐδένα ποιῇ.", "st": "3"}, {"sp": "N", "t": "ἦ μάν τοι λευκὰν διδυματόκον αἶγα φυλάσσω,<br>τάν με καὶ ἁ Μέρμνωνος ἐριθακὶς ἁ μελανόχρως<br>αἰτεῖ, καὶ δωσῶ οἱ, ἐπεὶ τύ μοι ἐνδιαθρύπτῃ.", "st": "3"}, {"sp": "N", "t": "Ἅλλεται ὀφθαλμός μευ ὁ δεξιός· ἦ ῥά γ’ ἰδησῶ<br>αὐτάν; ᾀσεῦμαι ποτὶ τὰν πίτυν ὧδ’ ἀποκλινθείς,<br>καί κέ μ’ ἴσως ποτίδοι, ἐπεὶ οὐκ ἀδαμαντίνα ἐστίν.", "st": "3"}, {"sp": "N", "t": "Ἱππομένης ὅκα δὴ τὰν παρθένον ἤθελε γᾶμαι,<br>μᾶλ’ ἐν χερσὶν ἑλὼν δρόμον ἄνυεν· ἁ δ’ Ἀταλάντα<br>ὡς ἴδεν, ὡς ἐμάνη, ὡς ἐς βαθὺν ἅλατ’ ἔρωτα.<br>τὰν ἀγέλαν χὡ μάντις ἀπ’ Ὄθρυος ἆγε Μελάμπους<br>ἐς Πύλον· ἁ δὲ Βίαντος ἐν ἀγκοίναισιν ἐκλίνθη,<br>μάτηρ ἁ χαρίεσσα περίφρονος Ἀλφεσιβοίης.", "st": "3"}, {"sp": "N", "t": "τὰν δὲ καλὰν Κυθέρειαν ἐν ὤρεσι μᾶλα νομεύων<br>οὐχ οὑτῶς ὥδωνις ἐπὶ πλέον ἄγαγε λύσσας,<br>ὥστ’ οὐδὲ φθίμενόν νιν ἄτερ μαζοῖο τίθητι;<br>ζαλωτὸς μὲν ἐμὶν ὁ τὸν ἄτροπον ὕπνον ἰαύων<br>Ἐνδυμίων, ζαλῶ δὲ φίλα γύναι Ἰασίωνα,<br>ὃς τοσσῆν’ ἐκύρησεν, ὅσ’ οὐ πευσεῖσθε βέβαλοι.", "st": "3"}, {"sp": "N", "t": "Ἀλγέω τὰν κεφαλάν, τὶν δ’ οὐ μέλει. οὐκέτ’ ἀείδω,<br>κεισεῦμαι δὲ πεσών, καὶ τοὶ λύκοι ὧδέ μ’ ἔδονται.", "st": "3"}, {"sp": "N", "t": "ὡς μέλι τοι γλυκὺ τοῦτο κατὰ βρόχθοιο γένοιτο.", "st": "3"}, {"sp": "SEC", "t": "Δʹ — Νομεῖς Βάττος καὶ Κορύδων", "st": "4"}, {"sp": "Βάττος", "t": "εἰπέ μοι ὦ Κορύδων, τίνος αἱ βόες; ἦ ῥα Φιλώνδα;", "st": "4"}, {"sp": "Κορύδων", "t": "οὔκ, ἀλλ’ Αἴγωνος· βόσκειν δέ μοι αὐτὰς ἔδωκεν.", "st": "4"}, {"sp": "Βάττος", "t": "ἦ πᾴ ψε κρύβδαν τὰ ποθέσπερα πάσας ἀμέλγεις;", "st": "4"}, {"sp": "Κορύδων", "t": "ἀλλ’ ὁ γέρων ὑφίητι τὰ μοσχία κἠμὲ φυλάσσει.", "st": "4"}, {"sp": "Βάττος", "t": "αὐτὸς δ’ ἐς τίν’ ἄφαντος ὁ βουκόλος ᾤχετο χώραν;", "st": "4"}, {"sp": "Κορύδων", "t": "οὐκ ἄκουσας; ἄγων νιν ἐπ’ Ἀλφεὸν ᾤχετο Μίλων.", "st": "4"}, {"sp": "Βάττος", "t": "καὶ πόκα τῆνος ἔλαιον ἐν ὀφθαλμοῖσιν ὀπώπει;", "st": "4"}, {"sp": "Κορύδων", "t": "φαντί νιν Ἡρακλῆι βίην καὶ κάρτος ἐρίσδειν.", "st": "4"}, {"sp": "Βάττος", "t": "κἤμ’ ἔφαθ’ ἁ μάτηρ Πολυδεύκεος εἶμεν ἀμείνω.", "st": "4"}, {"sp": "Κορύδων", "t": "κᾤχετ’ ἔχων σκαπάναν τε καὶ εἴκατι τουτόθε μῆλα.", "st": "4"}, {"sp": "Βάττος", "t": "πείσαι τοι Μίλων καὶ τὼς λύκος αὐτίκα λυσσῆν.", "st": "4"}, {"sp": "Κορύδων", "t": "ταὶ δαμάλαι δ’ αὐτὸν μυκώμεναι αἵδε ποθεῦντι.", "st": "4"}, {"sp": "Βάττος", "t": "δειλαῖαί γ’ αὗται· τὸν βουκόλον ὡς κακὸν εὗρον.", "st": "4"}, {"sp": "Κορύδων", "t": "ἦ μὰν δειλαῖαί γε, καὶ οὐκέτι λῶντι νέμεσθαι.", "st": "4"}, {"sp": "Βάττος", "t": "τήνας μὲν δή τοι τᾶς πόρτιος αὐτὰ λέλειπται<br>τὠστία. μὴ πρῶκας σιτίζεται ὥσπερ ὁ τέττιξ;", "st": "4"}, {"sp": "Κορύδων", "t": "οὐ Δᾶν, ἀλλ’ ὁκὰ μέν νιν ἐπ’ Αἰσάροιο νομεύω<br>καὶ μαλακῶ χόρτοιο καλὰν κώμυθα δίδωμι,<br>ἄλλοκα δὲ σκαίρει τὸ βαθύσκιον ἀμφὶ Λάτυμνον.", "st": "4"}, {"sp": "Βάττος", "t": "λεπτὸς μὰν χὡ ταῦρος ὁ πυρρίχος. εἴθε λάχοιεν<br>τοὶ τῶ Λαμπριάδα, τοὶ δαμόται, ὅκκα θύωντι<br>τᾷ Ἥρᾳ, τοιόνδε· κακοχράσμων γὰρ ὁ δᾶμος.", "st": "4"}, {"sp": "Κορύδων", "t": "καὶ μὰν ἐς Στομάλιμνον ἐλαύνεται ἔς τε τὰ Φύσκω,<br>καὶ ποτὶ τὸν Νήαιθον, ὅπᾳ καλὰ πάντα φύοντι,<br>αἰγίπυρος καὶ κνύζα καὶ εὐώδης μελίτεια.", "st": "4"}, {"sp": "Βάττος", "t": "φεῦ φεῦ βασεῦνται καὶ ταὶ βόες ὦ τάλαν Αἴγων<br>εἰς Ἀίδαν, ὅκα καὶ τὺ κακᾶς ἠράσσαο νίκας,<br>χἁ σῦριγξ εὐρῶτι παλύνεται, ἅν ποκ’ ἐπάξα.", "st": "4"}, {"sp": "Κορύδων", "t": "οὐ τήνα γ’, οὐ Νύμφας, ἐπεὶ ποτὶ Πῖσαν ἀφέρπων<br>δῶρον ἐμοί νιν ἔλειπεν· ἐγὼ δέ τις εἰμὶ μελικτάς,<br>κεὖ μὲν τὰ Γλαύκας ἀγκρούομαι, εὖ δὲ τὰ Πύρρω.<br>αἰνέω τάν τε Κρότωνα—καλὰ πόλις, ἅ τε Ζάκυνθος—<br>καὶ τὸ ποταῷον, τὸ Λακίνιον ᾇπερ ὁ πύκτας<br>Αἴγων ὀγδώκοντα μόνος κατεδαίσατο μάζας.<br>τηνεῖ καὶ τὸν ταῦρον ἀπ’ ὤρεος ἆγε πιάξας<br>τᾶς ὁπλᾶς κἤδωκ’ Ἀμαρυλλίδι, ταὶ δὲ γυναῖκες<br>μακρὸν ἀνάυσαν, χὡ βουκόλος ἐξεγέλασσεν.", "st": "4"}, {"sp": "Βάττος", "t": "ὦ χαρίεσσ’ Ἀμαρυλλί, μόνας σέθεν οὐδὲ θανοίσας<br>λασεύμεσθ’· ὅσον αἶγες ἐμὶν φίλαι, ὅσσον ἀπέσβης.<br>αἰαῖ τῶ σκληρῶ μάλα δαίμονος, ὅς με λελόγχει.", "st": "4"}, {"sp": "Κορύδων", "t": "θαρσεῖν χρὴ φίλε Βάττε· τάχ’ αὔριον ἔσσετ’ ἄμεινον.<br>ἐλπίδες ἐν ζωοῖσιν, ἀνέλπιστοι δὲ θανόντες.<br>χὡ Ζεὺς ἄλλοκα μὲν πέλει αἴθριος, ἄλλοκα δ’ ὕει.", "st": "4"}, {"sp": "Βάττος", "t": "θαρσέω. βάλλε κάτωθε τὰ μοσχία· τᾶς γὰρ ἐλαίας<br>τὸν θαλλὸν τρώγοντι τὰ δύσσοα. σίτθ’ ὁ λέπαργος.", "st": "4"}, {"sp": "Κορύδων", "t": "σίτθ’ ἁ Κυμαίθα ποτὶ τὸν λόφον. οὐκ ἐσακούεις;<br>ἡξῶ ναὶ τὸν Πᾶνα κακὸν τέλος αὐτίκα δωσῶν,<br>εἰ μὴ ἄπει τουτῶθεν. ἴδ’ αὖ πάλιν ἅδε ποθέρπει.<br>εἴθ’ ἦν μοι ῥοικὸν τὸ λαγωβόλον, ὥς τυ πάταξα.", "st": "4"}, {"sp": "Βάττος", "t": "θᾶσαί μ’ ὦ Κορύδων πὸτ τῶ Διός· ἁ γὰρ ἄκανθα<br>ἁρμοῖ μ’ ὧδ’ ἐπάταξ’ ὑπὸ τὸ σφυρόν. ὡς δὲ βαθεῖαι<br>τἀτρακτυλλίδες ἐντί. κακῶς ἁ πόρτις ὄλοιτο·<br>ἐς ταύταν ἐτύπην χασμεύμενος. ἦ ῥά γε λεύσσεις;", "st": "4"}, {"sp": "Κορύδων", "t": "ναὶ ναί, τοῖς ὀνύχεσσιν ἔχω τέ νιν· ἅδε καὶ αὐτά.", "st": "4"}, {"sp": "Βάττος", "t": "ὁσσίχον ἐστὶ τὸ τύμμα καὶ ἁλίκον ἄνδρα δαμάζει.", "st": "4"}, {"sp": "Κορύδων", "t": "εἰς ὄρος ὅκχ’ ἕρπῃς, μὴ νήλιπος ἔρχεο Βάττε.<br>ἐν γὰρ ὄρει ῥάμνοί τε καὶ ἀσπάλαθοι κομέονται.", "st": "4"}, {"sp": "Βάττος", "t": "εἴπ’ ἄγε μ’ ὦ Κορύδων, τὸ γερόντιον ἦ ῥ’ ἔτι μύλλει<br>τήναν τὰν κυάνοφρυν ἐρωτίδα, τᾶς ποκ’ ἐκνίσθη;", "st": "4"}, {"sp": "Κορύδων", "t": "ἀκμάν γ’ ὦ δειλαῖε· πρόαν γε μὲν αὐτὸς ἐπενθὼν<br>καὶ ποτὶ τᾷ μάνδρᾳ κατελάμβανον ἆμος ἐνήργει.", "st": "4"}, {"sp": "Βάττος", "t": "εὖ γ’ ὤνθρωπε φιλοῖφα. τό τοι γένος ἢ Σατυρίσκοις<br>ἐγγύθεν ἢ Πάνεσσι κακοκνάμοισιν ἐρίσδεις.", "st": "4"}, {"sp": "SEC", "t": "Εʹ — Βουκολιασταὶ Κομάτας καὶ Λάκων", "st": "5"}, {"sp": "Κομάτας", "t": "αἶγες ἐμαί, τῆνον τὸν ποιμένα τόνδε Σιβύρτα<br>φεύγετε τὸν Λάκωνα· τό μευ νάκος ἐχθὲς ἔκλεψεν.", "st": "5"}, {"sp": "Λάκων", "t": "οὐκ ἀπὸ τᾶς κράνας; σίττ’ ἀμνίδες. οὐκ ἐσορῆτε<br>τόν μευ τὰν σύριγγα πρόαν κλέψαντα Κομάταν;", "st": "5"}, {"sp": "Κομάτας", "t": "τὰν ποίαν σύριγγα; τὺ γάρ ποκα δῶλε Σιβύρτα<br>ἐκτάσα σύριγγα; τί δ’ οὐκέτι σὺν Κορύδωνι<br>ἀρκεῖ τοι καλάμας αὐλὸν ποππύσδεν ἔχοντι;", "st": "5"}, {"sp": "Λάκων", "t": "τάν μοι ἔδωκε Λύκων ὠλεύθερε. τὶν δὲ τὸ ποῖον<br>Λάκων ἀγκλέψας πόκ’ ἔβα νάκος; εἰπὲ Κομάτα·<br>οὐδὲ γὰρ Εὐμάρᾳ τῷ δεσπότᾳ ἦς τι ἐνεύδειν.", "st": "5"}, {"sp": "Κομάτας", "t": "τὸ Κροκύλος μοι ἔδωκε, τὸ ποικίλον, ἁνίκ’ ἔθυσε<br>ταῖς Νύμφαις τὰν αἶγα· τὺ δ’ ὦ κακὲ καὶ τόκ’ ἐτάκευ<br>βασκαίνων, καὶ νῦν με τὰ λοίσθια γυμνὸν ἔθηκας.", "st": "5"}, {"sp": "Λάκων", "t": "οὐκ αὐτὸν τὸν Πᾶνα τὸν ἄκτιον, οὐ τέ γε Λάκων<br>τὰν βαίταν ἀπέδυσ’ ὁ Καλαιθίδος, ἢ κατὰ τήνας<br>τᾶς πέτρας ὤνθρωπε μανεὶς ἐς Κρᾶθιν ἁλοίμαν.", "st": "5"}, {"sp": "Κομάτας", "t": "οὐ μὰν οὐκ αὐτὰς τὰς λιμνάδας ὠγαθὲ Νύμφας,<br>αἵτέ μοι ἵλαοί τε καὶ εὐμενέες τελέθοιεν,<br>οὔ τευ τὰν σύριγγα λαθὼν ἔκλεψε Κομάτας.", "st": "5"}, {"sp": "Λάκων", "t": "αἴ τοι πιστεύσαιμι, τὰ Δάφνιδος ἄλγε’ ἀροίμαν.<br>ἀλλ’ ὦν αἴκα λῇς ἔριφον θέμεν—ἔστι μὲν οὐδὲν<br>ἱερόν—ἀλλά γε τοι διαείσομαι, ἕστέ κ’ ἀπείπῃς.", "st": "5"}, {"sp": "Κομάτας", "t": "ὗς ποτ’ Ἀθαναίαν ἔριν ἤρισεν. ἠνίδε κεῖται<br>ὥριφος· ἀλλά γε καὶ τὺ τὸν εὔβοτον ἀμνὸν.—ἔρισδε.", "st": "5"}, {"sp": "Λάκων", "t": "καὶ πῶς ὦ κίναδος τὺ τάδ’ ἔσσεται ἐξ ἴσω ἁμίν;<br>τίς τρίχας ἀντ’ ἐρίων ἐποκίξατο; τίς δὲ παρεύσας<br>αἰγὸς πρατοτόκοιο κακὰν κύνα δήλετ’ ἀμέλγειν;", "st": "5"}, {"sp": "Κομάτας", "t": "ὅστις νικασεῖν τὸν πλατίον ὡς τὺ πεποίθεις,<br>σφὰξ βομβέων τέττιγος ἐναντίον. ἀλλὰ γὰρ οὔ τοι<br>ὥριφος ἰσοπαλής, τυῖδ’ ὁ τράγος οὗτος. ἔρισδε.", "st": "5"}, {"sp": "Λάκων", "t": "μὴ σπεῦδ’· οὐ γάρ τοι πυρὶ θάλπεαι. ἅδιον ᾀσῇ<br>τεῖδ’ ὑπὸ τὰν κότινον καὶ τἄλσεα ταῦτα καθίξας.<br>ψυχρὸν ὕδωρ τουτεῖ καταλείβεται· ὧδε πεφύκει<br>ποία χἁ στιβὰς ἅδε, καὶ ἀκρίδες ὧδε λαλεῦντι.", "st": "5"}, {"sp": "Κομάτας", "t": "ἀλλ’ οὔ τι σπεύδω· μέγα δ’ ἄχθομαι, εἰ τύ με τολμῇς<br>ὄμμασι τοῖς ὀρθοῖσι ποτιβλέπεν, ὅν ποκ’ ἐόντα<br>παῖδ’ ἔτ’ ἐγὼν ἐδίδασκον. ἴδ’ ἁ χάρις ἐς τί ποθ’ ἕρπει.<br>θρέψαι καὶ λυκιδεῖς, θρέψαι κύνας, ὥς τυ φάγωντι.", "st": "5"}, {"sp": "Λάκων", "t": "καὶ πόκ’ ἐγὼ παρὰ τεῦς τι μαθὼν καλὸν ἢ καὶ ἀκούσας<br>μέμναμ’; ὦ φθονερὸν τὺ καὶ ἀπρεπὲς ἀνδρίον αὔτως.<br>…<br>ἀλλὰ γὰρ ἕρφ’ ὧδ’, ἕρπε, καὶ ὕστατα βουκολιαξῇ.", "st": "5"}, {"sp": "Κομάτας", "t": "οὐχ ἑρψῶ τηνεῖ· τουτεῖ δρύες, ὧδε κύπειρος,<br>ὧδε καλὸν βομβεῦντι ποτὶ σμήνεσσι μέλισσαι·<br>ἔνθ’ ὕδατος ψυχρῶ κρᾶναι δύο· ταὶ δ’ ἐπὶ δένδρει<br>ὄρνιχες λαλαγεῦντι· καὶ ἁ σκιὰ οὐδὲν ὁμοία<br>τᾷ παρὰ τίν· βάλλει δὲ καὶ ἁ πίτυς ὑψόθε κώνοις.", "st": "5"}, {"sp": "Λάκων", "t": "ἦ μὰν ἀρνακίδας τε καὶ εἴρια τεῖδε πατησεῖς,<br>αἴκ’ ἔνθῃς, ὕπνω μαλακώτερα· ταὶ δὲ τραγεῖαι<br>ταὶ παρὰ τὶν ὄσδοντι κακώτερον ἢ τύ περ ὄσδεις.<br>στασῶ δὲ κρατῆρα μέγαν λευκοῖο γάλακτος<br>ταῖς Νύμφαις, στασῶ δὲ καὶ ἁδέος ἄλλον ἐλαίω.", "st": "5"}, {"sp": "Κομάτας", "t": "αἰ δέ κε καὶ τὺ μόλῃς, ἁπαλὰν πτέριν ὧδε πατησεῖς<br>καὶ γλάχων’ ἀνθεῦσαν· ὑπεσσεῖται δὲ χιμαιρᾶν<br>δέρματα τῶν παρὰ τὶν μαλακώτερα τετράκις ἀρνῶν.<br>στασῶ δ’ ὀκτὼ μὲν γαυλὼς τῷ Πανὶ γάλακτος,<br>ὀκτὼ δὲ σκαφίδας μέλιτος πλέα κηρί’ ἐχοίσας.", "st": "5"}, {"sp": "Λάκων", "t": "αὐτόθε μοι ποτέρισδε καὶ αὐτόθε βουκολιάσδευ·<br>τὰν σαυτῶ πατέων ἔχε τὰς δρύας. ἀλλὰ τίς ἄμμε<br>τίς κρινεῖ; αἴθ’ ἔνθοι πόθ’ ὁ βουκόλος ὧδ’ ὁ Λυκώπας.", "st": "5"}, {"sp": "Κομάτας", "t": "οὐδὲν ἐγὼ τήνω ποτιδεύομαι· ἀλλὰ τὸν ἄνδρα,<br>αἰ λῇς, τὸν δρυτόμον βωστρήσομες, ὃς τὰς ἐρείκας<br>τήνας τὰς παρὰ τὶν ξυλοχίζεται· ἔστι δὲ Μόρσων.", "st": "5"}, {"sp": "Λάκων", "t": "βωστρέωμες.", "st": "5"}, {"sp": "Κομάτας", "t": "τὺ κάλει νιν.", "st": "5"}, {"sp": "Λάκων", "t": "ἴθ’ ὦ ξένε μικκὸν ἄκουσον<br>τεῖδ’ ἐνθών· ἄμμες γὰρ ἐρίσδομες, ὅστις ἀρείων<br>βουκολιαστάς ἐστι. τὺ δ’ ὦ φίλε μήτ’ ἐμὲ Μόρσων<br>ἐν χάριτι κρίνῃς, μήτ’ ὦν τύγα τοῦτον ὀνάσῃς.", "st": "5"}, {"sp": "Κομάτας", "t": "ναὶ ποτὶ τᾶν Νυμφᾶν Μόρσων φίλε μήτε Κομάτᾳ<br>τὸ πλέον ἰθύνῃς, μήτ’ ὦν τύγα τῷδε χαρίξῃ.<br>ἅδέ τοι ἁ ποίμνα τῶ Θουρίω ἐστὶ Σιβύρτα,<br>Εὐμάρα δὲ τὰς αἶγας ὁρῇς φίλε τῶ Συβαρίτα.", "st": "5"}, {"sp": "Λάκων", "t": "μή τύ τις ἠρώτη πὸτ τῶ Διός, αἴτε Σιβύρτα<br>αἴτ’ ἐμόν ἐστι κάκιστε τὸ ποίμνιον; ὡς λάλος ἐσσί.", "st": "5"}, {"sp": "Κομάτας", "t": "βέντισθ’ οὗτος, ἐγὼ μὲν ἀλαθέα πάντ’ ἀγορεύω<br>κοὐδὲν καυχέομαι· τὺ δ’ ἄγαν φιλοκέρτομος ἐσσί.", "st": "5"}, {"sp": "Λάκων", "t": "εἶα λέγ’ εἴ τι λέγεις, καὶ τὸν ξένον ἐς πόλιν αὖθις<br>ζῶντ’ ἄφες· ὦ Παιάν, ἦ στωμύλος ἦσθα Κομάτα.", "st": "5"}, {"sp": "Κομάτας", "t": "ταὶ Μοῖσαί με φιλεῦντι πολὺ πλέον ἢ τὸν ἀοιδὸν<br>Δάφνιν· ἐγὼ δ’ αὐταῖς χιμάρως δύο πρᾶν ποκ’ ἔθυσα.", "st": "5"}, {"sp": "Λάκων", "t": "καὶ γὰρ ἔμ’ ὡπόλλων φιλέει μέγα, καὶ καλὸν αὐτῷ<br>κριὸν ἐγὼ βόσκω. τὰ δὲ Κάρνεα καὶ δὴ ἐφέρπει.", "st": "5"}, {"sp": "Κομάτας", "t": "πλὰν δύο τὰς λοιπὰς διδυματόκος αἶγας ἀμέλγω,<br>καί μ’ ἁ παῖς ποθορεῦσα “τάλαν” λέγει “αὐτὸς ἀμέλγεις;”", "st": "5"}, {"sp": "Λάκων", "t": "φεῦ φεῦ Λάκων τοι ταλάρως σχεδὸν εἴκατι πληροῖ<br>τυρῶ καὶ τὸν ἄναβον ἐν ἄνθεσι παῖδα μολύνει.", "st": "5"}, {"sp": "Κομάτας", "t": "βάλλει καὶ μάλοισι τὸν αἰπόλον ἁ Κλεαρίστα<br>τὰς αἶγας παρελᾶντα καὶ ἁδύ τι ποππυλιάσδει.", "st": "5"}, {"sp": "Λάκων", "t": "κἠμὲ γὰρ ὁ Κρατίδας τὸν ποιμένα λεῖος ὑπαντῶν<br>ἐκμαίνει· λιπαρὰ δὲ παρ’ αὐχένα σείετ’ ἔθειρα.", "st": "5"}, {"sp": "Κομάτας", "t": "ἀλλ’ οὐ σύμβλητ’ ἐστὶ κυνόσβατος οὐδ’ ἀνεμώνα<br>πρὸς ῥόδα, τῶν ἄνδηρα παρ’ αἱμασιαῖσι πεφύκει.", "st": "5"}, {"sp": "Λάκων", "t": "οὐδὲ γὰρ οὐδ’ ἀκύλοις ὁμομαλίδες· αἱ μὲν ἔχοντι<br>λυπρὸν ἀπὸ πρίνοιο λεπύριον, αἱ δὲ μελιχραί.", "st": "5"}, {"sp": "Κομάτας", "t": "κἠγὼ μὲν δωσῶ τᾷ παρθένῳ αὐτίκα φάσσαν<br>ἐκ τᾶς ἀρκεύθω καθελών· τηνεῖ γὰρ ἐφίσδει.", "st": "5"}, {"sp": "Λάκων", "t": "ἀλλ’ ἐγὼ ἐς χλαῖναν μαλακὸν πόκον, ὁππόκα πέξω<br>τὰν οἶν τὰν πέλλαν, Κρατίδᾳ δωρήσομαι αὐτός.", "st": "5"}, {"sp": "Κομάτας", "t": "σίττ’ ἀπὸ τᾶς κοτίνω ταὶ μηκάδες· ὧδε νέμεσθε,<br>ὡς τὸ κάταντες τοῦτο γεώλοφον αἵ τε μυρῖκαι.", "st": "5"}, {"sp": "Λάκων", "t": "οὐκ ἀπὸ τᾶς δρυὸς οὗτος ὁ Κώναρος ἅ τε Κιναίθα;<br>τουτεῖ βοσκησεῖσθε ποτ’ ἀντολάς, ὡς ὁ Φάλαρος.", "st": "5"}, {"sp": "Κομάτας", "t": "ἔστι δέ μοι γαυλὸς κυπαρίσσινος, ἔστι δὲ κρατήρ,<br>ἔργον Πραξιτέλευς· τᾷ παιδὶ δὲ ταῦτα φυλάσσω.", "st": "5"}, {"sp": "Λάκων", "t": "χἁμῖν ἐστι κύων φιλοποίμνιος, ὃς λύκος ἄγχει,<br>ὃν τῷ παιδὶ δίδωμι τὰ θηρία πάντα διώκειν.", "st": "5"}, {"sp": "Κομάτας", "t": "ἀκρίδες, αἳ τὸν φραγμὸν ὑπερπαδῆτε τὸν ἁμόν,<br>μή μευ λωβασεῖσθε τὰς ἀμπέλος· ἐντὶ γὰρ ἧβαι.", "st": "5"}, {"sp": "Λάκων", "t": "τοὶ τέττιγες, ὁρῆτε τὸν αἰπόλον ὡς ἐρεθίζω·<br>οὑτῶς χὑμές θην ἐρεθίζετε τὼς καλαμευτάς.", "st": "5"}, {"sp": "Κομάτας", "t": "μισέω τὰς δασυκέρκος ἀλώπεκας, αἳ τὰ Μίκωνος<br>αἰεὶ φοιτῶσαι τὰ ποθέσπερα ῥαγίζοντι.", "st": "5"}, {"sp": "Λάκων", "t": "καὶ γὰρ ἐγὼ μισέω τὼς κανθάρος, οἳ τὰ Φιλώνδα<br>σῦκα κατατρώγοντες ὑπανέμιοι φορέονται.", "st": "5"}, {"sp": "Κομάτας", "t": "ἦ οὐ μέμνᾳ, ὅκ’ ἐγώ τυ κατήλασα, καὶ τὺ σεσαρὼς<br>εὖ ποτεκιγκλίζευ καὶ τᾶς δρυὸς εἴχεο τήνας;", "st": "5"}, {"sp": "Λάκων", "t": "τοῦτο μὲν οὐ μέμναμ’· ὅκα μάν ποκα τεῖδέ τυ δήσας<br>Εὐμάρας ἐκάθηρε καλῶς μάλα, τοῦτό γ’ ἴσαμι.", "st": "5"}, {"sp": "Κομάτας", "t": "ἦ δή τις Μόρσων πικραίνεται· ἢ οὐχὶ παρῄσθευ;<br>σκίλλας ἰὼν γραίας ἀπὸ σάματος αὐτίκα τίλλειν.", "st": "5"}, {"sp": "Λάκων", "t": "κἠγὼ μὰν κνίζω Μόρσων τινά· καὶ τὺ δὲ λεύσσεις.<br>ἐνθὼν τὰν κυκλάμινον ὄρυσσέ νυν ἐς τὸν Ἄλεντα.", "st": "5"}, {"sp": "Κομάτας", "t": "Ἱμέρα ἀνθ’ ὕδατος ῥείτω γάλα, καὶ τὺ δὲ Κράθι<br>οἴνῳ πορφύροις, τὰ δέ τ’ οἴσυα καρπὸν ἐνείκαι.", "st": "5"}, {"sp": "Λάκων", "t": "ῥείτω χἁ Συβαρῖτις ἐμὶν μέλι, καὶ τὸ πότορθρον<br>ἁ παῖς ἀνθ’ ὕδατος τᾷ κάλπιδι κηρία βάψαι.", "st": "5"}, {"sp": "Κομάτας", "t": "ταὶ μὲν ἐμαὶ κύτισόν τε καὶ αἴγιλον αἶγες ἔδοντι,<br>καὶ σχῖνον πατέοντι καὶ ἐν κομάροισι κέχυνται.", "st": "5"}, {"sp": "Λάκων", "t": "ταῖσι δ’ ἐμαῖς ὀίεσσι πάρεστι μὲν ἁ μελίτεια<br>φέρβεσθαι, πολλὸς δὲ καὶ ὡς ῥόδα κίσθος ἐπανθεῖ.", "st": "5"}, {"sp": "Κομάτας", "t": "οὐκ ἔραμ’ Ἀλκίππας, ὅτι με πρᾶν οὐκ ἐφίλησε<br>τῶν ὤτων καθελοῖσ’, ὅκά οἱ τὰν φάσσαν ἔδωκα.", "st": "5"}, {"sp": "Λάκων", "t": "ἀλλ’ ἐγὼ Εὐμήδευς ἔραμαι μέγα· καὶ γὰρ ὅκ’ αὐτῷ<br>τὰν σύριγγ’ ὤρεξα, καλόν τί με κάρτ’ ἐφίλησεν.", "st": "5"}, {"sp": "Κομάτας", "t": "οὐ θεμιτὸν Λάκων ποτ’ ἀηδόνα κίσσας ἐρίσδειν,<br>οὐδ’ ἔποπας κύκνοισι· τὺ δ’ ὦ τάλαν ἐσσὶ φιλεχθής.", "st": "5"}, {"sp": "Μόρσων", "t": "παύσασθαι κέλομαι τὸν ποιμένα. τὶν δὲ Κομάτα<br>δωρεῖται Μόρσων τὰν ἀμνίδα· καὶ τὺ δὲ θύσας<br>ταῖς Νύμφαις Μόρσωνι καλὸν κρέας αὐτίκα πέμψον.", "st": "5"}, {"sp": "Κομάτας", "t": "πεμψῶ ναὶ τὸν Πᾶνα. φριμάσσεο πᾶσα τραγίσκων<br>νῦν ἀγέλα· κἠγὼ γὰρ ἴδ’ ὡς μέγα τοῦτο καχαξῶ<br>κὰτ τῶ Λάκωνος τῶ ποιμένος, ὅττι πόκ’ ἤδη<br>ἀνυσάμαν τὰν ἀμνόν· ἐς ὠρανὸν ὔμμιν ἁλεῦμαι.<br>αἶγες ἐμαὶ θαρσεῖτε κερούτιδες· αὔριον ὔμμε<br>πάσας ἐγὼ λουσῶ Συβαρίτιδος ἔνδοθι λίμνας.<br>οὗτος ὁ Λευκίτας ὁ κορυπτίλος, εἴ τιν’ ὀχευσεῖς<br>τᾶν αἰγῶν, φλασσῶ τυ πρὶν ἤ γ’ ἐμὲ καλλιερῆσαι<br>ταῖς Νύμφαις τὰν ἀμνόν. ὁ δ’ αὖ πάλιν. ἀλλὰ γενοίμαν,<br>αἰ μή τυ φλάσσαιμι, Μελάνθιος ἀντὶ Κομάτα.", "st": "5"}, {"sp": "SEC", "t": "Ϛʹ — Βουκολιασταὶ Δάφνις καὶ Δαμοίτας", "st": "6"}, {"sp": "N", "t": "Δαμοίτας χὡ Δάφνις ὁ βουκόλος εἰς ἕνα χῶρον<br>τὰν ἀγέλαν πόκ’ Ἄρατε συνάγαγον· ἦς δ’ ὁ μὲν αὐτῶν<br>πυρρός, ὁ δ’ ἡμιγένειος· ἐπὶ κράναν δέ τιν’ ἄμφω<br>ἑσδόμενοι θέρεος μέσῳ ἄματι τοιάδ’ ἄειδον.<br>πρᾶτος δ’ ἄρξατο Δάφνις, ἐπεὶ καὶ πρᾶτος ἔρισδε.", "st": "6"}, {"sp": "N", "t": "βάλλει τοι Πολύφαμε τὸ ποίμνιον ἁ Γαλάτεια<br>μάλοισιν, δυσέρωτα τὸν αἰπόλον ἄνδρα καλεῦσα·<br>καὶ τύ νιν οὐ ποθόρησθα τάλαν τάλαν, ἀλλὰ κάθησαι<br>ἁδέα συρίσδων. πάλιν ἅδ’ ἴδε τὰν κύνα βάλλει,<br>ἅ τοι τᾶν ὀίων ἕπεται σκοπός· ἁ δὲ βαΰσδει<br>εἰς ἅλα δερκομένα, τὰ δέ νιν καλὰ κύματα φαίνει<br>ἅσυχα καχλάζοντα ἐπ’ αἰγιαλοῖο θέοισαν.<br>φράζεο μὴ τᾶς παιδὸς ἐπὶ κνάμαισιν ὀρούσῃ<br>ἐξ ἁλὸς ἐρχομένας, κατὰ δὲ χρόα καλὸν ἀμύξῃ.<br>ἁ δὲ καὶ αὐτόθε τοι διαθρύπτεται, ὡς ἀπ’ ἀκάνθας<br>ταὶ καπυραὶ χαῖται, τὸ καλὸν θέρος ἁνίκα φρύγει·<br>καὶ φεύγει φιλέοντα καὶ οὐ φιλέοντα διώκει,<br>καὶ τὸν ἀπὸ γραμμᾶς κινεῖ λίθον· ἦ γὰρ ἔρωτι<br>πολλάκις ὦ Πολύφαμε τὰ μὴ καλὰ καλὰ πέφανται.", "st": "6"}, {"sp": "N", "t": "τῷ δ’ ἐπὶ Δαμοίτας ἀνεβάλλετο καὶ τάδ’ ἄειδεν.", "st": "6"}, {"sp": "N", "t": "εἶδον ναὶ τὸν Πᾶνα, τὸ ποίμνιον ἁνίκ’ ἔβαλλε,<br>κοὔ μ’ ἔλαθ’, οὔ, τὸν ἐμὸν ἕνα τὸν γλυκύν, ὧ ποθόρημαι<br>ἐς τέλος· αὐτὰρ ὁ μάντις ὁ Τήλεμος ἔχθρ’ ἀγορεύων<br>ἐχθρὰ φέροι ποτὶ οἶκον, ὅπως τεκέεσσι φυλάσσοι.<br>ἀλλὰ καὶ αὐτὸς ἐγὼ κνίζων πάλιν οὐ ποθόρημι,<br>ἀλλ’ ἄλλαν τινὰ φαμὶ γυναῖκ’ ἔχεν· ἁ δ’ ἀίοισα<br>ζαλοῖ μ’ ὦ Παιὰν καὶ τάκεται, ἐκ δὲ θαλάσσας<br>οἰστρεῖ παπταίνοισα ποτ’ ἄντρά τε καὶ ποτὶ ποίμνας.<br>σίξα δ’ ὑλακτεῖν νιν καὶ τᾷ κυνί· καὶ γὰρ ὅκ’ ἤρων<br>αὐτᾶς, ἐκνυζεῖτο ποτ’ ἰσχία ῥύγχος ἔχοισα.<br>ταῦτα δ’ ἴσως ἐσορεῦσα ποεῦντά με πολλάκι πεμψεῖ<br>ἄγγελον. αὐτὰρ ἐγὼ κλᾳξῶ θύρας, ἔστέ κ’ ὀμόσσῃ<br>αὐτά μοι στορεσεῖν καλὰ δέμνια τᾶσδ’ ἐπὶ νάσω.<br>καὶ γάρ θην οὐδ’ εἶδος ἔχω κακόν, ὥς με λέγοντι.<br>ἦ γὰρ πρᾶν ἐς πόντον ἐσέβλεπον, ἦς δὲ γαλάνα,<br>καὶ καλὰ μὲν τὰ γένεια, καλὰ δέ μευ ἁ μία κώρα,<br>ὡς παρ’ ἐμὶν κέκριται, κατεφαίνετο, τῶν δέ τ’ ὀδόντων<br>λευκοτέραν αὐγὰν Παρίας ὑπέφαινε λίθοιο.<br>ὡς μὴ βασκανθῶ δέ, τρὶς εἰς ἐμὸν ἔπτυσα κόλπον·<br>ταῦτα γὰρ ἁ γραία με Κοτυταρὶς ἐξεδίδαξε.<br>[ἃ πρᾶν ἀμάντεσσι παρ’ Ἱπποκίωνι ποταύλει.]", "st": "6"}, {"sp": "N", "t": "τόσσ’ εἰπὼν τὸν Δάφνιν ὁ Δαμοίτας ἐφίλησε,<br>χὡ μὲν τῷ σύριγγ’, ὁ δὲ τῷ καλὸν αὐλὸν ἔδωκεν.<br>αὔλει Δαμοίτας, σύρισδε δὲ Δάφνις ὁ βούτας,<br>ὠρχεῦντ’ ἐν μαλακᾷ ταὶ πόρτιες αὐτίκα ποίᾳ.<br>νίκη μὰν οὐδάλλος, ἀνήσσατοι δ’ ἐγένοντο.", "st": "6"}, {"sp": "SEC", "t": "Ζʹ — Θαλύσια", "st": "7"}, {"sp": "N", "t": "Ἦς χρόνος ἁνίκ’ ἐγώ τε καὶ Εὔκριτος ἐς τὸν Ἅλεντα<br>εἵρπομες ἐκ πόλιος, σὺν καὶ τρίτος ἁμὶν Ἀμύντας·<br>τᾷ Δηοῖ γὰρ ἔτευχε θαλύσια καὶ Φρασίδαμος<br>κἀντιγένης, δύο τέκνα Λυκωπέος, εἴ τί περ ἐσθλὸν<br>χᾳῶν τῶν ἐπάνωθεν, ἀπὸ Κλυτίας τε καὶ αὐτῶ<br>Χάλκωνος, Βούριναν ὃς ἐκ ποδὸς ἄνυσε κράναν<br>εὖ ἐνερεισάμενος πέτρᾳ γόνυ· ταὶ δὲ παρ’ αὐτὰν<br>αἴγειροι πτελέαι τε ἐύσκιον ἄλσος ὕφαινον,<br>χλωροῖσιν πετάλοισι κατηρεφέες κομόωσαι.<br>κοὔπω τὰν μεσάταν ὁδὸν ἄνυμες, οὐδὲ τὸ σᾶμα<br>ἁμὶν τὸ Βρασίλα κατεφαίνετο, καὶ τὸν ὁδίταν<br>ἐσθλὸν σὺν Μοίσαισι Κυδωνικὸν εὕρομες ἄνδρα,<br>οὔνομα μὲν Λυκίδαν, ἦς δ’ αἰπόλος, οὐδέ κέ τίς νιν<br>ἠγνοίησεν ἰδών, ἐπεὶ αἰπόλῳ ἔξοχ’ ἐῴκει.<br>ἐκ μὲν γὰρ λασίοιο δασύτριχος εἶχε τράγοιο<br>κνακὸν δέρμ’ ὤμοισι νέας ταμίσοιο ποτόσδον,<br>ἀμφὶ δέ οἱ στήθεσσι γέρων ἐσφίγγετο πέπλος<br>ζωστῆρι πλακερῷ, ῥοικὰν δ’ ἔχεν ἀγριελαίω<br>δεξιτερᾷ κορύναν. καί μ’ ἀτρέμας εἶπε σεσαρὼς<br>ὄμματι μειδιόωντι, γέλως δέ οἱ εἴχετο χείλευς·", "st": "7"}, {"sp": "N", "t": "“Σιμιχίδα, πᾷ δὴ τὸ μεσαμέριον πόδας ἕλκεις,<br>ἁνίκα δὴ καὶ σαῦρος ἐν αἱμασιαῖσι καθεύδει,<br>οὐδ’ ἐπιτυμβίδιαι κορυδαλλίδες ἠλαίνοντι;<br>ἦ μετὰ δαῖτα κλητὸς ἐπείγεαι; ἤ τινος ἀστῶν<br>λανὸν ἔπι θρώσκεις; ὥς τοι ποσὶ νισσομένοιο<br>πᾶσα λίθος πταίοισα ποτ’ ἀρβυλίδεσσιν ἀείδει.”", "st": "7"}, {"sp": "N", "t": "τὸν δ’ ἐγὼ ἀμείφθην· “Λυκίδα φίλε, φαντί τυ πάντες<br>συριγκτὰν ἔμεναι μέγ’ ὑπείροχον ἔν τε νομεῦσιν<br>ἔν τ’ ἀμητήρεσσι. τὸ δὴ μάλα θυμὸν ἰαίνει<br>ἁμέτερον· καί τοι κατ’ ἐμὸν νόον ἰσοφαρίζειν<br>ἔλπομαι. ἁ δ’ ὁδὸς ἅδε θαλυσιάς· ἦ γὰρ ἑταῖροι<br>ἀνέρες εὐπέπλῳ Δαμάτερι δαῖτα τελεῦντι<br>ὄλβω ἀπαρχόμενοι· μάλα γάρ σφισι πίονι μέτρῳ<br>ἁ δαίμων εὔκριθον ἀνεπλήρωσεν ἀλωάν.<br>ἀλλ’ ἄγε δή—ξυνὰ γὰρ ὁδός, ξυνὰ δὲ καὶ ἀώς—<br>βουκολιασδώμεσθα· τάχ’ ὥτερος ἄλλον ὀνασεῖ.<br>καὶ γὰρ ἐγὼ Μοισᾶν καπυρὸν στόμα, κἠμὲ λέγοντι<br>πάντες ἀοιδὸν ἄριστον· ἐγὼ δέ τις οὐ ταχυπειθής,<br>οὐ Δᾶν· οὐ γάρ πω κατ’ ἐμὸν νόον οὔτε τὸν ἐσθλὸν<br>Σικελίδαν νίκημι τὸν ἐκ Σάμω οὔτε Φιλητᾶν<br>ἀείδων, βάτραχος δὲ ποτ’ ἀκρίδας ὥς τις ἐρίσδω.”", "st": "7"}, {"sp": "N", "t": "ὣς ἐφάμαν ἐπίταδες· ὁ δ’ αἰπόλος ἁδὺ γελάσσας,<br>“τάν τοι” ἔφα “κορύναν δωρύττομαι, οὕνεκεν ἐσσὶ<br>πᾶν ἐπ’ ἀλαθείᾳ πεπλασμένον ἐκ Διὸς ἔρνος.<br>ὥς μοι καὶ τέκτων μέγ’ ἀπέχθεται, ὅστις ἐρευνῇ<br>ἶσον ὄρευς κορυφᾷ τελέσαι δόμον εὐρυμέδοντος,<br>καὶ Μοισᾶν ὄρνιχες, ὅσοι ποτὶ Χῖον ἀοιδὸν<br>ἀντία κοκκύζοντες ἐτώσια μοχθίζοντι.<br>ἀλλ’ ἄγε βουκολικᾶς ταχέως ἀρχώμεθ’ ἀοιδᾶς,<br>Σιμιχίδα· κἠγὼ μέν—ὅρη φίλος, εἴ τοι ἀρέσκει<br>τοῦθ’ ὅ τι πρᾶν ἐν ὄρει τὸ μελύδριον ἐξεπόνασα.”", "st": "7"}, {"sp": "Λυκίδας", "t": "ἔσσεται Ἀγεάνακτι καλὸς πλόος ἐς Μυτιλήναν,<br>χὥταν ἐφ’ ἑσπερίοις ἐρίφοις νότος ὑγρὰ διώκῃ<br>κύματα, χὡρίων ὅτ’ ἐπ’ ὠκεανῷ πόδας ἴσχῃ,<br>αἴκεν τὸν Λυκίδαν ὀπτεύμενον ἐξ Ἀφροδίτας<br>ῥύσηται· θερμὸς γὰρ ἔρως αὐτῶ με καταίθει.<br>χἁλκυόνες στορεσεῦντι τὰ κύματα τάν τε θάλασσαν<br>τόν τε νότον τόν τ’ εὖρον, ὃς ἔσχατα φυκία κινεῖ·<br>ἁλκυόνες, γλαυκαῖς Νηρηίσι ταί τε μάλιστα<br>ὀρνίχων ἐφίληθεν, ὅσαις τέ περ ἐξ ἁλὸς ἄγρα.<br>Ἀγεάνακτι πλόον διζημένῳ ἐς Μυτιλήναν<br>ὥρια πάντα γένοιτο, καὶ εὔπλοον ὅρμον ἵκοιτο.<br>κἠγὼ τῆνο κατ’ ἆμαρ ἀνήτινον ἢ ῥοδόεντα<br>ἢ καὶ λευκοΐων στέφανον περὶ κρατὶ φυλάσσων<br>τὸν Πτελεατικὸν οἶνον ἀπὸ κρατῆρος ἀφυξῶ<br>πὰρ πυρὶ κεκλιμένος, κύαμον δέ τις ἐν πυρὶ φρυξεῖ.<br>χἁ στιβὰς ἐσσεῖται πεπυκασμένα ἕστ’ ἐπὶ πᾶχυν<br>κνύζᾳ τ’ ἀσφοδέλῳ τε πολυγνάμπτῳ τε σελίνῳ.<br>καὶ πίομαι μαλακῶς μεμνημένος Ἀγεάνακτος<br>αὐταῖσιν κυλίκεσσι καὶ ἐς τρύγα χεῖλος ἐρείδων.<br>αὐλησεῦντι δέ μοι δύο ποιμένες, εἷς μὲν Ἀχαρνεύς,<br>εἷς δὲ Λυκωπίτας· ὁ δὲ Τίτυρος ἐγγύθεν ᾀσεῖ,<br>ὥς ποκα τᾶς Ξενέας ἠράσσατο Δάφνις ὁ βούτας,<br>χὡς ὄρος ἀμφ’ ἐπονεῖτο, καὶ ὡς δρύες αὐτὸν ἐθρήνευν,<br>Ἱμέρα αἵτε φύοντι παρ’ ὄχθῃσιν ποταμοῖο,<br>εὖτε χιὼν ὥς τις κατετάκετο μακρὸν ὑφ’ Αἷμον<br>ἢ Ἄθω ἢ Ῥοδόπαν ἢ Καύκασον ἐσχατόωντα.<br>ᾀσεῖ δ’ ὥς ποκ’ ἔδεκτο τὸν αἰπόλον εὐρέα λάρναξ<br>ζωὸν ἐόντα κακαῖσιν ἀτασθαλίαισιν ἄνακτος,<br>ὥς τέ νιν αἱ σιμαὶ λειμωνόθε φέρβον ἰοῖσαι<br>κέδρον ἐς ἁδεῖαν μαλακοῖς ἄνθεσσι μέλισσαι,<br>οὕνεκά οἱ γλυκὺ Μοῖσα κατὰ στόματος χέε νέκταρ.<br>ὦ μακαριστὲ Κομάτα, τύ θην τάδε τερπνὰ πεπόνθεις,<br>καὶ τὺ κατεκλᾴσθης ἐς λάρνακα, καὶ τὺ μελισσᾶν<br>κηρία φερβόμενος ἔτος ὥριον ἐξεπόνασας.<br>αἴθ’ ἐπ’ ἐμεῦ ζωοῖς ἐναρίθμιος ὤφελες εἶμεν,<br>ὥς τοι ἐγὼν ἐνόμευον ἀν’ ὤρεα τὰς καλὰς αἶγας<br>φωνᾶς εἰσαΐων, τὺ δ’ ὑπὸ δρυσὶν ἢ ὑπὸ πεύκαις<br>ἁδὺ μελισδόμενος κατεκέκλισο θεῖε Κομάτα.", "st": "7"}, {"sp": "N", "t": "χὡ μὲν τόσσ’ εἰπὼν ἀπεπαύσατο· τὸν δὲ μετ’ αὖθις", "st": "7"}, {"sp": "N", "t": "κἠγὼ τοῖ’ ἐφάμαν· “Λυκίδα φίλε, πολλὰ μὲν ἄλλα<br>Νύμφαι κἠμὲ δίδαξαν ἀν’ ὤρεα βουκολέοντα<br>ἐσθλά, τά που καὶ Ζηνὸς ἐπὶ θρόνον ἄγαγε φάμα·<br>ἀλλὰ τόγ’ ἐκ πάντων μέγ’ ὑπείροχον, ᾧ τυ γεραίρειν<br>ἀρξεῦμ’· ἀλλ’ ὑπάκουσον, ἐπεὶ φίλος ἔπλεο Μοίσαις.”", "st": "7"}, {"sp": "Σιμιχίδας", "t": "Σιμιχίδᾳ μὲν Ἔρωτες ἐπέπταρον· ἦ γὰρ ὁ δειλὸς<br>τόσσον ἐρᾷ Μυρτοῦς, ὅσον εἴαρος αἶγες ἐρᾶντι.<br>ὥρατος δ’ ὁ τὰ πάντα φιλαίτατος ἀνέρι τήνῳ<br>παιδὸς ὑπὸ σπλάγχνοισιν ἔχει πόθον. οἶδεν Ἄριστις,<br>ἐσθλὸς ἀνήρ, μέγ’ ἄριστος, ὃν οὐδέ κεν αὐτὸς ἀείδειν<br>Φοῖβος σὺν φόρμιγγι παρὰ τριπόδεσσι μεγαίροι,<br>ὡς ἐκ παιδὸς Ἄρατος ὑπ’ ὀστέον αἴθετ’ ἔρωτι.<br>τόν μοι Πάν, Ὁμόλας ἐρατὸν πέδον ὅστε λέλογχας,<br>ἄκλητον κείνοιο φίλας ἐς χεῖρας ἐρείσαις,<br>εἴτ’ ἐστ’ ἆρα Φιλῖνος ὁ μαλθακὸς εἴτέ τις ἄλλος.<br>κἢν μὲν ταῦτ’ ἔρδῃς ὦ Πὰν φίλε, μή τί τυ παῖδες<br>Ἀρκαδικοὶ σκίλλαισιν ὑπὸ πλευράς τε καὶ ὤμους<br>τανίκα μαστίσδοιεν, ὅτε κρέα τυτθὰ παρείη·<br>εἰ δ’ ἄλλως νεύσαις, κατὰ μὲν χρόα πάντ’ ὀνύχεσσι<br>δακνόμενος κνάσαιο καὶ ἐν κνίδαισι καθεύδοις,<br>εἴης δ’ Ἠδωνῶν μὲν ἐν ὤρεσι χείματι μέσσῳ<br>Ἕβρον πὰρ ποταμὸν τετραμμένος ἐγγύθεν ἄρκτω,<br>ἐν δὲ θέρει πυμάτοισι παρ’ Αἰθιόπεσσι νομεύοις<br>πέτρᾳ ὕπο Βλεμύων, ὅθεν οὐκέτι Νεῖλος ὁρατός.<br>ὔμμες δ’ Ὑετίδος καὶ Βυβλίδος ἁδὺ λιπόντες<br>νᾶμα καὶ Οἰκεῦντα, ξανθᾶς ἕδος αἰπὺ Διώνας,<br>ὦ μάλοισιν Ἔρωτες ἐρευθομένοισιν ὁμοῖοι,<br>βάλλετέ μοι τόξοισι τὸν ἱμερόεντα Φιλῖνον,<br>βάλλετ’, ἐπεὶ τὸν ξεῖνον ὁ δύσμορος οὐκ ἐλεεῖ μευ.<br>καὶ δὴ μὰν ἀπίοιο πεπαίτερος, αἱ δὲ γυναῖκες<br>“αἰαῖ” φαντὶ “Φιλῖνε, τό τοι καλὸν ἄνθος ἀπορρεῖ.”<br>μηκέτι τοι φρουρέωμες ἐπὶ προθύροισιν Ἄρατε,<br>μηδὲ πόδας τρίβωμες· ὁ δ’ ὄρθριος ἄλλον ἀλέκτωρ<br>κοκκύζων νάρκαισιν ἀνιαραῖσι διδοίη,<br>εἷς δ’ ἀπὸ τᾶσδε φέριστε Μόλων ἄγχοιτο παλαίστρας,<br>ἄμμιν δ’ ἁσυχία τε μέλοι γραία τε παρείη,<br>ἅτις ἐπιφθύζοισα τὰ μὴ καλὰ νόσφιν ἐρύκοι.", "st": "7"}, {"sp": "N", "t": "τόσσ’ ἐφάμαν· ὁ δέ μοι τὸ λαγωβόλον, ἁδὺ γελάσσας<br>ὡς πάρος, ἐκ Μοισᾶν ξεινήιον ὤπασεν εἶμεν.<br>χὡ μὲν ἀποκλίνας ἐπ’ ἀριστερὰ τὰν ἐπὶ Πύξας<br>εἷρφ’ ὁδόν, αὐτὰρ ἐγώ τε καὶ Εὔκριτος ἐς Φρασιδάμω<br>στραφθέντες χὡ καλὸς Ἀμύντιχος ἔν τε βαθείαις<br>ἁδείας σχοίνοιο χαμευνίσιν ἐκλίνθημες<br>ἔν τε νεοτμάτοισι γεγαθότες οἰναρέοισι.<br>πολλαὶ δ’ ἁμὶν ὕπερθε κατὰ κρατὸς δονέοντο<br>αἴγειροι πτελέαι τε· τὸ δ’ ἐγγύθεν ἱερὸν ὕδωρ<br>Νυμφᾶν ἐξ ἄντροιο κατειβόμενον κελάρυζε.<br>τοὶ δὲ ποτὶ σκιαραῖς ὀροδαμνίσιν αἰθαλίωνες<br>τέττιγες λαλαγεῦντες ἔχον πόνον· ἁ δ’ ὀλολυγὼν<br>τηλόθεν ἐν πυκιναῖσι βάτων τρύζεσκεν ἀκάνθαις.<br>ἄειδον κόρυδοι καὶ ἀκανθίδες, ἔστενε τρυγών,<br>πωτῶντο ξουθαὶ περὶ πίδακας ἀμφὶ μέλισσαι.<br>πάντ’ ὦσδεν θέρεος μάλα πίονος, ὦσδε δ’ ὀπώρας.<br>ὄχναι μὲν πὰρ ποσσί, παρὰ πλευραῖσι δὲ μᾶλα<br>δαψιλέως ἁμῖν ἐκυλίνδετο· τοὶ δ’ ἐκέχυντο<br>ὄρπακες βραβίλοισι καταβρίθοντες ἔραζε·<br>τετράενες δὲ πίθων ἀπελύετο κρατὸς ἄλειφαρ.", "st": "7"}, {"sp": "N", "t": "Νύμφαι Κασταλίδες Παρνάσιον αἶπος ἔχοισαι,<br>ἆρά γέ πᾳ τοιόνδε Φόλω κατὰ λάινον ἄντρον<br>κρατῆρ’ Ἡρακλῆι γέρων ἐστήσατο Χείρων;<br>ἆρά γέ πᾳ τῆνον τὸν ποιμένα τὸν ποτ’ Ἀνάπῳ,<br>τὸν κρατερὸν Πολύφαμον, ὃς ὤρεσι νᾶας ἔβαλλε,<br>τοῖον νέκταρ ἔπεισε κατ’ αὐλία ποσσὶ χορεῦσαι,<br>οἷον δὴ τόκα πῶμα διεκρανάσατε Νύμφαι<br>βωμῷ πὰρ Δάματρος ἀλῳάδος; ἇς ἐπὶ σωρῷ", "st": "7"}, {"sp": "N", "t": "αὖθις ἐγὼ πάξαιμι μέγα πτύον, ἁ δὲ γελάσσαι<br>δράγματα καὶ μάκωνας ἐν ἀμφοτέραισιν ἔχοισα.", "st": "7"}, {"sp": "SEC", "t": "Ηʹ — Βουκολιασταὶ Δάφνις καὶ Μενάλκας", "st": "8"}, {"sp": "N", "t": "Δάφνιδι τῷ χαρίεντι συνήντετο βουκολέοντι<br>μῆλα νέμων, ὡς φαντί, κατ’ ὤρεα μακρὰ Μενάλκας.<br>ἄμφω τώγ’ ἤστην πυρροτρίχω, ἄμφω ἀνάβω,<br>ἄμφω συρίσδεν δεδαημένω, ἄμφω ἀείδεν.<br>πρᾶτος δ’ ὦν ποτὶ Δάφνιν ἰδὼν ἀγόρευε Μενάλκας·", "st": "8"}, {"sp": "N", "t": "“μυκητᾶν ἐπίουρε βοῶν Δάφνι, λῇς μοι ἀεῖσαι;<br>φαμί τυ νικασεῖν, ὅσσον θέλω αὐτὸς ἀείδων.”", "st": "8"}, {"sp": "N", "t": "τὸν δ’ ἄρα χὡ Δάφνις τοιῷδ’ ἀπαμείβετο μύθῳ·<br>“ποιμὴν εἰροπόκων ὀίων συριγκτὰ Μενάλκα,<br>οὔποτε νικασεῖς μ’, οὐδ’ εἴ τι πάθοις τύγ’ ἀείδων.”", "st": "8"}, {"sp": "Μενάλκας", "t": "χρῄσδεις ὦν ἐσιδεῖν; χρῄσδεις καταθεῖναι ἄεθλον;", "st": "8"}, {"sp": "Δάφνις", "t": "χρῄσδω τοῦτ’ ἐσιδεῖν, χρῄσδω καταθεῖναι ἄεθλον.", "st": "8"}, {"sp": "Μενάλκας", "t": "καὶ τίνα θησεύμεσθ’, ὅτις ἁμῖν ἄρκιος εἴη;", "st": "8"}, {"sp": "Δάφνις", "t": "μόσχον ἐγὼ θησῶ· τὺ δὲ θὲς ἰσομάτορα ἀμνόν.", "st": "8"}, {"sp": "Μενάλκας", "t": "οὐ θησῶ ποκα ἀμνόν, ἐπεὶ χαλεπὸς ὁ πατήρ μευ<br>χἁ μάτηρ, τὰ δὲ μῆλα ποθέσπερα πάντ’ ἀριθμεῦντι.", "st": "8"}, {"sp": "Δάφνις", "t": "ἀλλὰ τί μὰν θησεῖς; τί δὲ τὸ πλέον ἑξεῖ ὁ νικῶν;", "st": "8"}, {"sp": "Μενάλκας", "t": "σύριγγ’ ἃν ἐπόησα καλὰν ἐγὼ ἐννεάφωνον,<br>λευκὸν κηρὸν ἔχοισαν, ἴσον κάτω, ἶσον ἄνωθεν,<br>ταύταν κατθείην, τὰ δὲ τῶ πατρὸς οὐ καταθησῶ.", "st": "8"}, {"sp": "Δάφνις", "t": "ἦ μάν τοι κἠγὼ σύριγγ’ ἔχω ἐννεάφωνον.<br>λευκὸν κηρὸν ἔχοισαν, ἴσον κάτω, ἶσον ἄνωθεν.<br>πρώαν νιν συνέπαξ’· ἔτι καὶ τὸν δάκτυλον ἀλγέω<br>τοῦτον, ἐπεὶ κάλαμός με διασχισθεὶς διέτμαξεν.", "st": "8"}, {"sp": "Μενάλκας", "t": "ἀλλὰ τίς ἄμμε κρινεῖ; τίς ἐπάκοος ἔσσεται ἁμέων;", "st": "8"}, {"sp": "Δάφνις", "t": "τῆνον πῶς ἐνταῦθα τὸν αἰπόλον ἢν καλέσωμες;<br>ᾧ ποτὶ ταῖς ἐρίφοις ὁ κύων ὁ φάλαρος ὑλακτεῖ.", "st": "8"}, {"sp": "N", "t": "χοἱ μὲν παῖδες ἄυσαν, ὁ δ’ αἰπόλος ἦνθ’ ἐπακοῦσαι.<br>χοἱ μὲν παῖδες ἄειδον, ὁ δ’ αἰπόλος ἤθελε κρίνειν.<br>πρᾶτος δ’ ὦν ἄειδε λαχὼν ἰυκτὰ Μενάλκας,<br>εἶτα δ’ ἀμοιβαίαν ὑπελάμβανε Δάφνις ἀοιδάν.<br>[βουκολικάν· οὕτω δὲ Μενάλκας ἄρξατο πρᾶτος.]", "st": "8"}, {"sp": "Μενάλκας", "t": "Ἄγκεα καὶ ποταμοί, θεῖον γένος, αἴ τι Μενάλκας<br>πήποχ’ ὁ συριγκτὰς προσφιλὲς ᾆσε μέλος,<br>βόσκοιτ’ ἐκ ψυχᾶς τὰς ἀμνάδας· ἢν δέ ποκ’ ἔνθῃ<br>Δάφνις ἔχων δαμάλας, μηδὲν ἔλασσον ἔχοι.", "st": "8"}, {"sp": "Δάφνις", "t": "κρᾶναι καὶ βοτάναι, γλυκερὸν φυτόν, αἴπερ ὁμοῖον<br>μουσίσδει Δάφνις ταῖσιν ἀηδονίσι,<br>τοῦτο τὸ βουκόλιον πιαίνετε· κἤν τι Μενάλκας<br>τεῖδ’ ἀγάγῃ, χαίρων ἄφθονα πάντα νέμοι.", "st": "8"}, {"sp": "Μενάλκας", "t": "ἔνθ’ ὄις, ἔνθ’ αἶγες διδυματόκοι, ἔνθα μέλισσαι<br>σμήνεα πληροῦσιν, καὶ δρύες ὑψίτεραι,<br>ἔνθ’ ὁ καλὸς Μίλων βαίνει ποσίν· αἰ δ’ ἂν ἀφέρπῃ,<br>χὡ ποιμὴν ξηρὸς τηνόθι χαἱ βοτάναι.", "st": "8"}, {"sp": "Δάφνις", "t": "παντᾷ ἔαρ, παντᾷ δὲ νομοί, παντᾷ δὲ γάλακτος<br>οὔθατα πλήθουσιν, καὶ τὰ νέα τρέφεται,<br>ἐνθ’ ἁ καλὰ παῖς ἐπινίσσεται· αἰ δ’ ἂν ἀφέρπῃ,<br>χὡ τὰς βῶς βόσκων χαἱ βόες αὐότεραι.", "st": "8"}, {"sp": "Μενάλκας", "t": "ὦ τράγε, τᾶν λευκᾶν αἰγῶν ἄνερ, ὧ βάθος ὕλας<br>μυρίον, (ὦ σιμαὶ δεῦτ’ ἐφ’ ὕδωρ ἔριφοι·)<br>ἐν τήνῳ γὰρ τῆνος· ἴθ’ ὦ κόλε καὶ λέγε· Μίλων,<br>ὁ Πρωτεὺς φώκας καὶ θεὸς ὢν ἔνεμε.", "st": "8"}, {"sp": "Δάφνις", "t": "μή μοι γᾶν Πέλοπος, μή μοι χρύσεια τάλαντα<br>εἴη ἔχειν, μηδὲ πρόσθε θέειν ἀνέμων·<br>ἀλλ’ ὑπὸ τᾷ πέτρᾳ τᾷδ’ ᾄσομαι, ἀγκὰς ἔχων τυ,<br>σύννομα μῆλ’ ἐσορῶν, τὰν Σικελὰν ἐς ἅλα.", "st": "8"}, {"sp": "Δάφνις", "t": "δένδρεσι μὲν χειμὼν φοβερὸν κακόν, ὕδασι δ’ αὐχμός,<br>ὄρνισιν δ’ ὕσπλαγξ, ἀγροτέροις δὲ λίνα,<br>ἀνδρὶ δὲ παρθενικᾶς ἁπαλᾶς πόθος. ὦ πάτερ ὦ Ζεῦ,<br>οὐ μόνος ἠράσθην· καὶ τὺ γυναικοφίλας.", "st": "8"}, {"sp": "N", "t": "ταῦτα μὲν ὦν δι’ ἀμοιβαίων οἱ παῖδες ἄεισαν·<br>τὰν πυμάταν δ’ ᾠδὰν οὑτῶς ἐξᾶρχε Μενάλκας.", "st": "8"}, {"sp": "N", "t": "Φείδευ τᾶν ἐρίφων, φείδευ λύκε τᾶν τοκάδων μευ,<br>μηδ’ ἀδίκει μ’, ὅτι μικκὸς ἐὼν πολλαῖσιν ὁμαρτέω.<br>ὦ Λάμπουρε κύον, οὕτω βαθὺς ὕπνος ἔχει τυ;<br>οὐ χρὴ κοιμᾶσθαι βαθέως σὺν παιδὶ νέμοντα.<br>ταὶ δ’ ὄιες, μηδ’ ὔμμες ὀκνεῖθ’ ἁπαλᾶς κορέσασθαι<br>ποίας· οὔτι καμεῖσθ’, ὅκκ’ αὖ πάλιν ἅδε φύηται.<br>σίττα νέμεσθε νέμεσθε, τὰ δ’ οὔθατα πλήσατε πᾶσαι,<br>ὡς τὸ μὲν ὥρνες ἔχωντι, τὸ δ’ ἐς ταλάρως ἀποθῶμαι.", "st": "8"}, {"sp": "N", "t": "δεύτερος αὖ Δάφνις λιγυρῶς ἀνεβάλλετ’ ἀείδειν·", "st": "8"}, {"sp": "N", "t": "κἠμὲ γὰρ ἐκ τὤντρω σύνοφρυς κόρα ἐχθὲς ἰδοῖσα<br>τὰς δαμάλας παρελᾶντα καλὸν καλὸν ἦμεν ἔφασκεν·<br>οὐ μὰν οὐδὲ λόγον ἐκρίθην ἄπο, τὤμπικρον αὐτᾷ,<br>ἀλλὰ κάτω βλέψας τὰν ἁμετέραν ὁδὸν εἷρπον.<br>ἁδεῖ’ ἁ φωνὰ τᾶς πόρτιος, ἁδὺ τὸ πνεῦμα·<br>[ἁδὺ δὲ χὡ μόσχος γαρύεται, ἁδὺ δὲ χἁ βῶς·]<br>ἁδὺ δὲ τῶ θέρεος παρ’ ὕδωρ ῥέον αἰθριοκοιτεῖν.<br>τᾷ δρυῒ ταὶ βάλανοι κόσμος, τᾷ μαλίδι μᾶλα,<br>τᾷ βοῒ δ’ ἁ μόσχος, τῷ βουκόλῳ αἱ βόες αὐταί.", "st": "8"}, {"sp": "N", "t": "Ὣς οἱ παῖδες ἄεισαν, ὁ δ’ αἰπόλος ὧδ’ ἀγόρευεν·<br>ἁδύ τι τὸ στόμα τευ καὶ ἐφίμερος ὦ Δάφνι φωνά.<br>κρέσσον μελπομένω τευ ἀκουέμεν ἢ μέλι λείχειν.<br>λάζεο τὰς σύριγγας· ἐνίκασας γὰρ ἀείδων.<br>αἰ δέ τι λῇς με καὶ αὐτὸν ἅμ’ αἰπολέοντα διδάξαι,<br>τήναν τὰν μιτύλαν δωσῶ τὰ δίδακτρά τοι αἶγα,<br>ἅτις ὑπὲρ κεφαλᾶς αἰεὶ τὸν ἀμολγέα πληροῖ.", "st": "8"}, {"sp": "N", "t": "Ὡς μὲν ὁ παῖς ἐχάρη καὶ ἀνάλατο καὶ πλατάγησε<br>νικάσας, οὑτῶς ἐπὶ ματέρι νεβρὸς ἅλοιτο.<br>ὡς δὲ κατεσμύχθη καὶ ἀνετράπετο φρένα λύπᾳ<br>ὥτερος, οὕτω καὶ νύμφα γαμεθεῖσ’ ἀκάχοιτο.", "st": "8"}, {"sp": "N", "t": "κἠκ τούτω πρᾶτος παρὰ ποιμέσι Δάφνις ἔγεντο,<br>καὶ Νύμφαν ἄκρηβος ἐὼν ἔτι Ναΐδα γᾶμεν.", "st": "8"}, {"sp": "SEC", "t": "Θʹ — Βουκολιασταὶ Δάφνις καὶ Μενάλκας", "st": "9"}, {"sp": "N", "t": "[Βουκολιάζεο Δάφνι, τὺ δ’ ᾠδᾶς ἄρχεο πρᾶτος,<br>ᾠδᾶς ἄρχεο Δάφνι, συναψάσθω δὲ Μενάλκας,<br>μόσχως βουσὶν ὑφέντες, ὑπὸ στείραισι δὲ ταύρως.<br>χοἱ μὲν ἁμᾷ βόσκοιντο καὶ ἐν φύλλοισι πλανῷντο<br>μηδὲν ἀτιμαγελεῦντες· ἐμὶν δὲ τὺ βουκολιάζευ<br>ἐκτόθεν, ἄλλωθεν δὲ ποτικρίνοιτο Μενάλκας.]", "st": "9"}, {"sp": "Δάφνις", "t": "Ἁδὺ μὲν ἁ μόσχος γαρύεται, ἁδὺ δὲ χἁ βοῦς,<br>ἁδὺ δὲ χἁ σῦριγξ χὡ βουκόλος, ἁδὺ δὲ κἠγών.<br>ἔστι δέ μοι παρ’ ὕδωρ ψυχρὸν στιβάς, ἐν δὲ νένασται<br>λευκᾶν ἐκ δαμαλᾶν καλὰ δέρματα, τάς μοι ἁπάσας<br>λὶψ κόμαρον τρωγοίσας ἀπὸ σκοπιᾶς ἐτίναξε.<br>τῶ δὲ θέρευς φρύγοντος ἐγὼ τόσσον μελεδαίνω,<br>ὅσσον ἐρῶντε πατρὸς μύθων καὶ ματρὸς ἀκούειν.", "st": "9"}, {"sp": "N", "t": "οὑτῶς Δάφνις ἄεισεν ἐμίν, οὑτῶς δὲ Μενάλκας.", "st": "9"}, {"sp": "Μενάλκας", "t": "Αἴτνα μᾶτερ ἐμά, κἠγὼ καλὸν ἄντρον ἐνοικέω<br>κοίλαις ἐν πέτραισιν· ἔχω δέ τοι ὅσσ’ ἐν ὀνείρῳ<br>φαίνονται, πολλὰς μὲν ὄις, πολλὰς δὲ χιμαίρας,<br>ὧν μοι πρὸς κεφαλᾷ καὶ πρὸς ποσὶ κώεα κεῖται.<br>ἐν πυρὶ δὲ δρυίνῳ χόρια ζεῖ, ἐν πυρὶ δ’ αὖαι<br>φαγοὶ χειμαίνοντος· ἔχω δέ τοι οὐδ’ ὅσον ὤραν<br>χείματος ἢ νωδὸς καρύων ἀμύλοιο παρόντος.", "st": "9"}, {"sp": "N", "t": "τοῖς μὲν ἐπεπλατάγησα καὶ αὐτίκα δῶρον ἔδωκα,<br>Δάφνιδι μὲν κορύναν, τάν μοι πατρὸς ἔτρεφεν ἀγρός,<br>αὐτοφυῆ, τὰν οὐδ’ ἂν ἴσως μωμάσατο τέκτων,<br>τήνῳ δὲ στρόμβω καλὸν ὄστρακον, ὧ κρέας αὐτὸς<br>σιτήθην πέτραισιν ἐν Ἰκαρίαισι δοκεύσας,<br>πέντε ταμὼν πέντ’ οὖσιν· ὁ δ’ ἐγκαναχήσατο κόχλῳ.", "st": "9"}, {"sp": "N", "t": "Βουκολικαὶ Μοῖσαι μάλα χαίρετε, φαίνετε δ’ ᾠδάς,<br>τάς ποκ’ ἐγὼ τήνοισι παρὼν ἄεισα νομεῦσι,<br>μηκέτ’ ἐπὶ γλώσσας ἄκρας ὀλοφυγγόνα φύσω.", "st": "9"}, {"sp": "N", "t": "τέττιξ μὲν τέττιγι φίλος, μύρμακι δὲ μύρμαξ,<br>ἴρηκες δ’ ἴρηξιν, ἐμὶν δέ τε μοῖσα καὶ ᾠδά.<br>τᾶς μοι πᾶς εἴη πλεῖος δόμος. οὔτε γὰρ ὕπνος<br>οὔτ’ ἔαρ ἐξαπίνας γλυκερώτερον, οὔτε μελίσσαις<br>ἄνθεα· τόσσον ἐμὶν Μοῖσαι φίλαι. οὓς μὲν ὁρεῦντι<br>γαθεῦσαι, τοὺς δ’ οὔτι ποτῷ δαλήσατο Κίρκη.", "st": "9"}, {"sp": "SEC", "t": "Ιʹ — Ἐργατίναι ἢ Θερισταί", "st": "10"}, {"sp": "Μίλων", "t": "Ἐργατίνα βουκαῖε, τί νῦν ᾦζυρὲ πεπόνθεις;<br>οὔθ’ ἑὸν ὄγμον ἄγειν ὀρθὸν δύνᾳ, ὡς τὸ πρὶν ἆγες,<br>οὔθ’ ἅμα λᾳοτομεῖς τῷ πλατίον, ἀλλ’ ἀπολείπῃ<br>ὥσπερ ὄις ποίμνας, ἇς τὸν πόδα κάκτος ἔτυψε.<br>ποῖός τις δείλαν τυ καὶ ἐκ μέσω ἄματος ἐσσῇ,<br>ὃς νῦν ἀρχόμενος τᾶς αὔλακος οὐκ ἀποτρώγεις;", "st": "10"}, {"sp": "Βάττος", "t": "Μίλων ὀψαμάτα, πέτρας ἀπόκομμ’ ἀτεράμνω,<br>οὐδαμά τοι συνέβα ποθέσαι τινὰ τῶν ἀπεόντων;", "st": "10"}, {"sp": "Μίλων", "t": "οὐδαμά. τίς δὲ πόθος τῶν ἔκτοθεν ἐργάτᾳ ἀνδρί;", "st": "10"}, {"sp": "Βάττος", "t": "οὐδαμά νυν συνέβα τοι ἀγρυπνῆσαι δι’ ἔρωτα;", "st": "10"}, {"sp": "Μίλων", "t": "μηδέ γε συμβαίη· χαλεπὸν χορίω κύνα γεῦσαι.", "st": "10"}, {"sp": "Βάττος", "t": "ἀλλ’ ἐγὼ ὦ Μίλων ἔραμαι σχεδὸν ἑνδεκαταῖος.", "st": "10"}, {"sp": "Μίλων", "t": "ἐκ πίθω ἀντλεῖς δῆλον· ἐγὼ δ’ ἔχω οὐδ’ ἅλις ὄξος.", "st": "10"}, {"sp": "Βάττος", "t": "τοιγάρτοι πρὸ θυρᾶν μοι ἀπὸ σπόρω ἄσκαλα πάντα.", "st": "10"}, {"sp": "Μίλων", "t": "τίς δέ τυ τᾶν παίδων λυμαίνεται;", "st": "10"}, {"sp": "Βάττος", "t": "ἁ Πολυβώτα,<br>ἃ πρᾶν ἀμάντεσσι παρ’ Ἱπποκίωνι ποταύλει.", "st": "10"}, {"sp": "Μίλων", "t": "εὗρε θεὸς τὸν ἀλιτρόν· ἔχεις πάλαι ὧν ἐπεθύμεις.<br>μάντίς τοι τὰν νύκτα χροϊξεῖθ’ ἁ καλαμαία.", "st": "10"}, {"sp": "Βάττος", "t": "μωμᾶσθαί μ’ ἄρχῃ τύ· τυφλὸς δ’ οὐκ αὐτὸς ὁ Πλοῦτος,<br>ἀλλὰ καὶ ὡφρόντιστος Ἔρως. μὴ δὴ μέγα μυθεῦ.", "st": "10"}, {"sp": "Μίλων", "t": "οὐ μέγα μυθεῦμαι· τὺ μόνον κατάβαλλε τὸ λᾷον,<br>καί τι κόρας φιλικὸν μέλος ἀμβάλευ. ἅδιον οὑτῶς<br>ἐργαξῇ· καὶ μὰν πρότερόν ποκα μουσικὸς ἦσθα.", "st": "10"}, {"sp": "Βάττος", "t": "Μοῖσαι Πιερίδες, συναείσατε τὰν ῥαδινάν μοι<br>παῖδ’· ὧν γάρ χ’ ἅψησθε θεαί, καλὰ πάντα ποεῖτε.<br>Βομβύκα χαρίεσσα, Σύραν καλέοντί τυ πάντες,<br>ἰσχνὰν ἁλιόκαυστον, ἐγὼ δὲ μόνος μελίχλωρον.<br>καὶ τὸ ἴον μέλαν ἐστὶ καὶ ἁ γραπτὰ ὑάκινθος,<br>ἀλλ’ ἔμπας ἐν τοῖς στεφάνοις τὰ πρᾶτα λέγονται.<br>ἁ αἲξ τὰν κύτισον, ὁ λύκος τὰν αἶγα διώκει,<br>ἁ γέρανος τὤροτρον, ἐγὼ δ’ ἐπὶ τὶν μεμάνημαι.<br>αἴθέ μοι ἦς, ὅσσα Κροῖσόν ποκα φαντὶ πεπᾶσθαι,<br>χρύσεοι ἀμφότεροί κ’ ἀνεκείμεθα τᾷ Ἀφροδίτᾳ,<br>τὼς αὐλὼς μὲν ἔχοισα καὶ ἢ ῥόδον ἢ μᾶλον τύ,<br>σχῆμα δ’ ἐγὼ καὶ καινὰς ἐπ’ ἀμφοτέροισιν ἀμύκλας.<br>Βομβύκα χαρίεσσ’, οἱ μὲν πόδες ἀστράγαλοί τευς,<br>ἁ φωνὰ δὲ τρύχνος· τὸν μὰν τρόπον οὐκ ἔχω εἰπεῖν.", "st": "10"}, {"sp": "Μίλων", "t": "Ἦ καλὰς ἄμμι ποέων ἐλελήθει βοῦκος ἀοιδάς.<br>ὡς εὖ τὰν ἰδέαν τᾶς ἁρμονίας ἐμέτρησεν.<br>ὤμοι τῶ πώγωνος, ὃν ἀλιθίως ἀνέφυσα.<br>θᾶσαι δὴ καὶ ταῦτα τὰ τῶ θείω Λιτυέρσα.", "st": "10"}, {"sp": "Μίλων", "t": "Δάματερ πολύκαρπε πολύσταχυ, τοῦτο τὸ λᾷον<br>εὔεργόν τ’ εἴη καὶ κάρπιμον ὅττι μάλιστα.<br>Σφίγγετ’ ἀμαλλοδέται τὰ δράγματα, μὴ παριών τις<br>εἴποι· “σύκινοι ἄνδρες, ἀπώλετο χοὗτος ὁ μισθός.”<br>Ἐς βορέην ἄνεμον τᾶς κόρθυος ἁ τομὰ ὔμμιν<br>ἢ ζέφυρον βλεπέτω· πιαίνεται ὁ στάχυς οὑτῶς.<br>σῖτον ἀλοιῶντας φεύγειν τὸ μεσαμβρινὸν ὕπνον·<br>ἐκ καλάμας ἄχυρον τελέθει τημόσδε μάλιστα.<br>ἄρχεσθαι δ’ ἀμῶντας ἐγειρομένω κορυδαλλῶ,<br>καὶ λήγειν εὕδοντος, ἐλινῦσαι δὲ τὸ καῦμα.<br>εὐκτὸς ὁ τῶ βατράχω παῖδες βίος· οὐ μελεδαίνει<br>τὸν προπιεῖν ἐγχεῦντα· πάρεστι γὰρ ἄφθονον αὐτῷ.<br>κάλλιον ὦπιμελητὰ φιλάργυρε τὸν φακὸν ἕψειν·<br>μή τι τάμῃς τὰν χεῖρα καταπρίων τὸ κύμινον.<br>ταῦτα χρὴ μοχθεῦντας ἐν ἁλίῳ ἄνδρας ἀείδειν,<br>τὸν δὲ τεὸν βουκαῖε πρέπει λιμηρὸν ἔρωτα<br>μυθίσδεν τᾷ ματρὶ κατ’ εὐνὰν ὀρθρευοίσᾳ.", "st": "10"}, {"sp": "SEC", "t": "ΙΑʹ — Κύκλωψ", "st": "11"}, {"sp": "N", "t": "οὐδὲν πὸτ τὸν ἔρωτα πεφύκει φάρμακον ἄλλο<br>Νικία οὔτ’ ἔγχριστον, ἐμὶν δοκεῖ, οὔτ’ ἐπίπαστον,<br>ἢ ταὶ Πιερίδες· κοῦφον δέ τι τοῦτο καὶ ἁδὺ<br>γίνετ’ ἐπ’ ἀνθρώποις, εὑρεῖν δ’ οὐ ῥᾴδιόν ἐστι.<br>γινώσκειν δ’ οἶμαί τυ καλῶς ἰατρὸν ἐόντα<br>καὶ ταῖς ἐννέα δὴ πεφιλάμενον ἔξοχα Μοίσαις.", "st": "11"}, {"sp": "N", "t": "οὕτω γοῦν ῥάιστα διᾶγ’ ὁ Κύκλωψ ὁ παρ’ ἁμῖν,<br>ὡρχαῖος Πολύφαμος, ὅκ’ ἤρατο τᾶς Γαλατείας,<br>ἄρτι γενειάσδων περὶ τὸ στόμα τὼς κροτάφως τε.<br>ἤρατο δ’ οὐ μάλοις οὐδὲ ῥόδῳ οὐδὲ κικίννοις,<br>ἀλλ’ ὀρθαῖς μανίαις, ἁγεῖτο δὲ πάντα πάρεργα.<br>πολλάκι ταὶ ὄιες ποτὶ ταὐλίον αὐταὶ ἀπῆνθον<br>χλωρᾶς ἐκ βοτάνας· ὁ δὲ τὰν Γαλάτειαν ἀείδων<br>αὐτόθ’ ἐπ’ ἀιόνος κατετάκετο φυκιοέσσας<br>ἐξ ἀοῦς, ἔχθιστον ἔχων ὑποκάρδιον ἕλκος<br>Κύπριδος ἐκ μεγάλας, τό οἱ ἥπατι πᾶξε βέλεμνον.", "st": "11"}, {"sp": "N", "t": "ἀλλὰ τὸ φάρμακον εὗρε, καθεζόμενος δ’ ἐπὶ πέτρας<br>ὑψηλᾶς ἐς πόντον ὁρῶν ἄειδε τοιαῦτα.", "st": "11"}, {"sp": "N", "t": "Ὦ λευκὰ Γαλάτεια, τί τὸν φιλέοντ’ ἀποβάλλῃ;<br>λευκοτέρα πακτᾶς ποτιδεῖν, ἁπαλωτέρα ἀρνός,<br>μόσχω γαυροτέρα, σφριγανωτέρα ὄμφακος ὠμᾶς.<br>φοιτῇς δ’ αὖθ’ οὑτῶς, ὅκκα γλυκὺς ὕπνος ἔχῃ με,<br>οἴχῃ δ’ εὐθὺς ἰοῖσ’, ὅκκα γλυκὺς ὕπνος ἀνῇ με,<br>φεύγεις δ’ ὥσπερ ὄις πολιὸν λύκον ἀθρήσασα.", "st": "11"}, {"sp": "N", "t": "ἠράσθην μὲν ἔγωγα τεοῦς κόρα, ἁνίκα πρᾶτον<br>ἦνθες ἐμᾷ σὺν ματρὶ θέλοισ’ ὑακίνθινα φύλλα<br>ἐξ ὄρεος δρέψασθαι, ἐγὼ δ’ ὁδὸν ἁγεμόνευον.<br>παύσασθαι δ’ ἐσιδών τυ καὶ ὕστερον οὐδέ τί πᾳ νῦν<br>ἐκ τήνω δύναμαι· τὶν δ’ οὐ μέλει, οὐ μὰ Δί’ οὐδέν.", "st": "11"}, {"sp": "N", "t": "γινώσκω χαρίεσσα κόρα, τίνος ὥνεκα φεύγεις·<br>ὥνεκά μοι λασία μὲν ὀφρῦς ἐπὶ παντὶ μετώπῳ<br>ἐξ ὠτὸς τέταται ποτὶ θὥτερον ὦς μία μακρά,<br>εἷς δ’ ὀφθαλμὸς ἔπεστι, πλατεῖα δὲ ῥὶς ἐπὶ χείλει.<br>ἀλλ’ οὗτος τοιοῦτος ἐὼν βοτὰ χίλια βόσκω,<br>κἠκ τούτων τὸ κράτιστον ἀμελγόμενος γάλα πίνω·<br>τυρὸς δ’ οὐ λείπει μ’ οὔτ’ ἐν θέρει οὔτ’ ἐν ὀπώρᾳ,<br>οὐ χειμῶνος ἄκρω· ταρσοὶ δ’ ὑπεραχθέες αἰεί.", "st": "11"}, {"sp": "N", "t": "συρίσδεν δ’ ὡς οὔτις ἐπίσταμαι ὧδε Κυκλώπων,<br>τὶν τὸ φίλον γλυκύμαλον ἁμᾷ κἠμαυτὸν ἀείδων<br>πολλάκι νυκτὸς ἀωρί. τρέφω δέ τοι ἕνδεκα νεβρὼς<br>πάσας μηνοφόρως καὶ σκύμνως τέσσαρας ἄρκτων.", "st": "11"}, {"sp": "N", "t": "ἀλλ’ ἀφίκευσο ποθ’ ἁμέ, καὶ ἑξεῖς οὐδὲν ἔλασσον,<br>τὰν γλαυκὰν δὲ θάλασσαν ἔα ποτὶ χέρσον ὀρεχθεῖν.<br>ἅδιον ἐν τὤντρῳ παρ’ ἐμὶν τὰν νύκτα διαξεῖς.<br>ἐντὶ δάφναι τηνεῖ, ἐντὶ ῥαδιναὶ κυπάρισσοι,<br>ἔστι μέλας κισσός, ἔστ’ ἄμπελος ἁ γλυκύκαρπος,<br>ἔστι ψυχρὸν ὕδωρ, τό μοι ἁ πολυδένδρεος Αἴτνα<br>λευκᾶς ἐκ χιόνος ποτὸν ἀμβρόσιον προΐητι.<br>τίς κα τῶνδε θάλασσαν ἔχειν καὶ κύμαθ’ ἕλοιτο;", "st": "11"}, {"sp": "N", "t": "αἰ δέ τοι αὐτὸς ἐγὼ δοκέω λασιώτερος ἦμεν,<br>ἐντὶ δρυὸς ξύλα μοι καὶ ὑπὸ σποδῷ ἀκάματον πῦρ.<br>καιόμενος δ’ ὑπὸ τεῦς καὶ τὰν ψυχὰν ἀνεχοίμαν<br>καὶ τὸν ἕν’ ὀφθαλμόν, τῶ μοι γλυκερώτερον οὐδέν.", "st": "11"}, {"sp": "N", "t": "ὤμοι, ὅ τ’ οὐκ ἔτεκέν μ’ ἁ μάτηρ βραγχί’ ἔχοντα,<br>ὡς κατέδυν ποτὶ τὶν καὶ τὰν χέρα τευς ἐφίλασα,<br>αἰ μὴ τὸ στόμα λῇς, ἔφερον δέ τοι ἢ κρίνα λευκὰ<br>ἢ μάκων’ ἁπαλὰν ἐρυθρὰ πλαταγώνι’ ἔχοισαν.<br>ἀλλὰ τὰ μὲν θέρεος, τὰ δὲ γίνεται ἐν χειμῶνι,<br>ὥστ’ οὐκ ἄν τοι ταῦτα φέρειν ἅμα πάντ’ ἐδυνάθην.", "st": "11"}, {"sp": "N", "t": "νῦν μὰν ὦ κόριον, νῦν αὐτόγα νεῖν κε μάθοιμι,<br>αἴκά τις σὺν ναῒ πλέων ξένος ὧδ’ ἀφίκηται,<br>ὡς εἰδῶ, τί ποθ’ ἁδὺ κατοικεῖν τὸν βυθὸν ὔμμιν.", "st": "11"}, {"sp": "N", "t": "ἐξένθοις Γαλάτεια καὶ ἐξενθοῖσα λάθοιο<br>ὥσπερ ἐγὼ νῦν ὧδε καθήμενος οἴκαδ’ ἀπενθεῖν.<br>ποιμαίνειν δ’ ἐθέλοις σὺν ἐμὶν ἅμα καὶ γάλ’ ἀμέλγειν<br>καὶ τυρὸν πᾶξαι τάμισον δριμεῖαν ἐνεῖσα.", "st": "11"}, {"sp": "N", "t": "ἁ μάτηρ ἀδικεῖ με μόνα, καὶ μέμφομαι αὐτᾷ·<br>οὐδὲν πήποχ’ ὅλως ποτὶ τὶν φίλον εἶπεν ὑπέρ μευ,<br>καὶ ταῦτ’ ἆμαρ ἐπ’ ἆμαρ ὁρεῦσά με λεπτὸν ἐόντα.<br>φασῶ τὰν κεφαλὰν καὶ τὼς πόδας ἀμφοτέρως μευ<br>σφύζειν, ὡς ἀνιαθῇ, ἐπεὶ κἠγὼν ἀνιῶμαι.", "st": "11"}, {"sp": "N", "t": "ὦ Κύκλωψ Κύκλωψ, πᾷ τὰς φρένας ἐκπεπότασαι;<br>αἴκ’ ἐνθὼν θαλάρως τε πλέκοις καὶ θαλλὸν ἀμάσας<br>ταῖς ἄρνεσσι φέροις, τάχα κα πολὺ μᾶλλον ἔχοις νῶν.", "st": "11"}, {"sp": "N", "t": "τὰν παρεοῖσαν ἄμελγε. τί τὸν φεύγοντα διώκεις;<br>εὑρησεῖς Γαλάτειαν ἴσως καὶ καλλίον’ ἄλλαν.<br>πολλαὶ συμπαίσδέν με κόραι τὰν νύκτα κέλονται,<br>κιχλίζοντι δὲ πᾶσαι, ἐπεί κ’ αὐταῖς ὑπακούσω<br>δῆλον ὅ τ’ ἐν τᾷ γᾷ κἠγώ τις φαίνομαι ἦμεν.", "st": "11"}, {"sp": "N", "t": "οὕτω τοι Πολύφαμος ἐποίμαινεν τὸν ἔρωτα<br>μουσίσδων, ῥᾷον δὲ διᾶγ’ ἢ εἰ χρυσὸν ἔδωκεν.", "st": "11"}, {"sp": "SEC", "t": "ΙΒʹ — Ἀίτης", "st": "12"}, {"sp": "N", "t": "Ἤλυθες ὦ φίλε κοῦρε τρίτῃ σὺν νυκτὶ καὶ ἀοῖ;<br>ἤλυθες· οἱ δὲ ποθεῦντες ἐν ἤματι γηράσκουσιν.<br>ὅσσον ἔαρ χειμῶνος, ὅσον μᾶλον βραβίλοιο<br>ἅδιον, ὅσσον ὄις σφετέρας λασιωτέρα ἀρνός,<br>ὅσσον παρθενικὴ προφέρει τριγάμοιο γυναικός,<br>ὅσσον ἐλαφροτέρη μόσχου νεβρός, ὅσσον ἀηδὼν<br>συμπάντων λιγύφωνος ἀοιδοτάτη πετεηνῶν,<br>τόσσον ἔμ’ εὔφρανας τὺ φανείς, σκιερὰν δ’ ὑπὸ φαγὸν<br>ἀελίου φρύγοντος ὁδοιπόρος ἔδραμον ὥς τις.", "st": "12"}, {"sp": "N", "t": "εἴθ’ ὁμαλοὶ πνεύσειαν ἐπ’ ἀμφοτέροισιν Ἔρωτες<br>νῶιν, ἐπεσσομένοις δὲ γενοίμεθα πᾶσιν ἀοιδά.", "st": "12"}, {"sp": "N", "t": "θείω δή τινε τώδε μετὰ προτέροισι γενέσθην<br>φῶθ’, ὁ μὲν εἴσπνηλος, φαίη χ’ ὡμυκλαϊάσδων,<br>τὸν δ’ ἕτερον πάλιν ὥς κεν ὁ Θεσσαλὸς εἴποι ἀίταν.", "st": "12"}, {"sp": "N", "t": "ἀλλήλους δ’ ἐφίλησαν ἴσῳ ζυγῷ. ἦ ῥα τότ’ ἦσαν<br>χρύσειοι πάλιν ἄνδρες, ὃ κἀντεφίλησ’ ὁ φιληθείς.", "st": "12"}, {"sp": "N", "t": "εἰ γὰρ τοῦτο πάτερ Κρονίδα πέλοι, εἰ γὰρ ἀγήρῳ<br>ἀθάνατοι, γενεαῖς δὲ διηκοσίαισιν ἔπειτα<br>ἀγγείλειεν ἐμοί τις ἀνέξοδον εἰς Ἀχέροντα·", "st": "12"}, {"sp": "N", "t": "“ἡ σὴ νῦν φιλότης καὶ τοῦ χαρίεντος ἀίτεω<br>πᾶσι διὰ στόματος, μετὰ δ’ ἠιθέοισι μάλιστα.”", "st": "12"}, {"sp": "N", "t": "ἀλλ’ ἤτοι τούτων μὲν ὑπέρτεροι Οὐρανίωνες<br>ἔσσονθ’ ὡς ἐθέλοντι. ἐγὼ δέ σε τὸν καλὸν αἰνέων<br>ψεύδεα ῥινὸς ὕπερθεν ἀραιᾶς οὐκ ἀναφύσω.<br>ἢν γὰρ καί τι δάκῃς, τὸ μὲν ἀβλαβὲς εὐθὺς ἔθηκας,<br>διπλάσιον δ’ ὤνασας, ἔχων δ’ ἐπίμετρον ἀπῆνθον.", "st": "12"}, {"sp": "N", "t": "Νισαῖοι Μεγαρῆες ἀριστεύοντες ἐρετμοῖς,<br>ὄλβιοι οἰκείοιτε, τὸν Ἀττικὸν ὡς περίαλλα<br>ξεῖνον ἐτιμήσασθε Διοκλέα τὸν φιλόπαιδα.<br>αἰεί οἱ περὶ τύμβον ἀολλέες εἴαρι πράτῳ<br>κοῦροι ἐριδμαίνοντι φιλήματος ἄκρα φέρεσθαι.<br>ὃς δέ κε προσμάξῃ γλυκερώτερα χείλεσι χείλη,<br>βριθόμενος στεφάνοισιν ἑὰν ἐς μητέρ’ ἀπῆνθεν.<br>ὄλβιος, ὅστις παισὶ φιλήματα κεῖνα διαιτᾷ.<br>ἦ που τὸν χαροπὸν Γανυμήδεα πόλλ’ ἐπιβωτᾷ<br>Λυδίῃ ἶσον ἔχειν πέτρῃ στόμα, χρυσὸν ὁποίῃ<br>πεύθονται μὴ φαῦλος ἐτήτυμω ἀργυραμοιβοί.", "st": "12"}, {"sp": "SEC", "t": "ΙΓʹ — Ὕλας", "st": "13"}, {"sp": "N", "t": "οὐχ ἁμῖν τὸν Ἔρωτα μόνοις ἔτεχ’, ὡς ἐδοκεῦμες,<br>Νικία, ᾧ τινι τοῦτο θεῶν ποκα τέκνον ἔγεντο.<br>οὐχ ἁμῖν τὰ καλὰ πράτοις καλὰ φαίνεται εἶμεν,<br>οἳ θνατοὶ πελόμεσθα, τὸ δ’ αὔριον οὐκ ἐσορῶμες·<br>ἀλλὰ καὶ ὡμφιτρύωνος ὁ χαλκεοκάρδιος υἱός,<br>ὃς τὸν λῖν ὑπέμεινε τὸν ἄγριον, ἤρατο παιδός,<br>τῶ χαρίεντος Ὕλα, τῶ τὰν πλοκαμῖδα φορεῦντος,<br>καί νιν πάντ’ ἐδίδαξε πατὴρ ὡσεὶ φίλον υἱέα,<br>ὅσσα μαθὼν ἀγαθὸς καὶ ἀοίδιμος αὐτὸς ἔγεντο·<br>χωρὶς δ’ οὐδέποκ’ ἦς, οὔτ’ εἰ μέσον ἆμαρ ὄροιτο,<br>οὔτ’ ἄρ’ ὅχ’ ἁ λεύκιππος ἀνατρέχοι ἐς Διὸς Ἀώς,<br>οὐδ’ ὁπόκ’ ὀρτάλιχοι μινυροὶ ποτὶ κοῖτον ὁρῷεν,<br>σεισαμένας πτερὰ ματρὸς ἐπ’ αἰθαλόεντι πετεύρῳ,<br>ὡς αὐτῷ κατὰ θυμὸν ὁ παῖς πεποναμένος εἴη,<br>αὐτῷ δ’ εὖ ἕλκων ἐς ἀλαθινὸν ἄνδρ’ ἀποβαίη.", "st": "13"}, {"sp": "N", "t": "ἀλλ’ ὅτε τὸ χρύσειον ἔπλει μετὰ κῶας Ἰήσων<br>Αἰσονίδας, οἱ δ’ αὐτῷ ἀριστῆες συνέποντο<br>πασᾶν ἐκ πολίων προλελεγμένοι, ὧν ὄφελός τι,<br>ἵκετο χὡ ταλαεργὸς ἀνὴρ ἐς ἀφνειὸν Ἰωλκόν,<br>Ἀλκμήνης υἱὸς Μιδεάτιδος ἡρωίνης,<br>σὺν δ’ αὐτῷ κατέβαινεν Ὕλας εὔεδρον ἐς Ἀργώ,<br>ἅτις κυανεᾶν οὐχ ἥψατο συνδρομάδων ναῦς,<br>ἀλλὰ διεξάιξε—βαθὺν δ’ εἰσέδραμε Φᾶσιν—<br>αἰετὸς ἐς μέγα λαῖτμα· ἀφ’ οὗ τότε χοιράδες ἔσταν.", "st": "13"}, {"sp": "N", "t": "ἆμος δ’ ἀντέλλοντι Πελειάδες, ἐσχατιαὶ δὲ<br>ἄρνα νέον βόσκοντι, τετραμμένου εἴαρος ἤδη,<br>τᾶμος ναυτιλίας μιμνάσκετο θεῖος ἄωτος<br>ἡρώων, κοίλαν δὲ καθιδρυνθέντες ἐς Ἀργὼ<br>Ἑλλάσποντον ἵκοντο νότῳ τρίτον ἆμαρ ἀέντι,<br>εἴσω δ’ ὅρμον ἔθεντο Προποντίδος, ἔνθα Κιανῶν<br>αὔλακας εὐρύνοντι βόες τρίβοντες ἄροτρα.<br>ἐκβάντες δ’ ἐπὶ θῖνα κατὰ ζυγὰ δαῖτα πένοντο<br>δειελινοί, πολλοὶ δὲ μίαν στορέσαντο χαμεύναν.<br>λειμὼν γάρ σφιν ἔκειτο, μέγα στιβάδεσσιν ὄνειαρ,<br>ἔνθεν βούτομον ὀξὺ βαθύν τ’ ἐτάμοντο κύπειρον.<br>κᾤχεθ’ Ὕλας ὁ ξανθὸς ὕδωρ ἐπιδόρπιον οἰσῶν<br>αὐτῷ θ’ Ἡρακλῆι καὶ ἀστεμφεῖ Τελαμῶνι,<br>οἳ μίαν ἄμφω ἑταῖροι ἀεὶ δαίνυντο τράπεζαν,<br>χάλκεον ἄγγος ἔχων. τάχα δὲ κράναν ἐνόησεν<br>ἡμένῳ ἐν χώρῳ· περὶ δὲ θρύα πολλὰ πεφύκει,<br>κυάνεόν τε χελιδόνιον χλωρόν τ’ ἀδίαντον<br>καὶ θάλλοντα σέλινα καὶ εἰλιτενὴς ἄγρωστις.<br>ὕδατι δ’ ἐν μέσσῳ Νύμφαι χορὸν ἀρτίζοντο,<br>Νύμφαι ἀκοίμητοι, δειναὶ θεαὶ ἀγροιώταις,<br>Εὐνείκα καὶ Μαλὶς ἔαρ θ’ ὁρόωσα Νύχεια,<br>ἤτοι ὁ κοῦρος ἐπεῖχε ποτῷ πολυχανδέα κρωσσὸν<br>βάψαι ἐπειγόμενος, ταὶ δ’ ἐν χερὶ πᾶσαι ἔφυσαν·<br>πασάων γὰρ ἔρως ἁπαλὰς φρένας ἐξεσόβησεν<br>Ἀργείῳ ἐπὶ παιδί· κατήριπε δ’ ἐς μέλαν ὕδωρ<br>ἀθρόος, ὡς ὅτε πυρσὸς ἀπ’ οὐρανοῦ ἤριπεν ἀστὴρ<br>ἀθρόος, ἐν πόντῳ, ναύταις δέ τις εἶπεν ἑταίροις·<br>“κουφότερ’ ὦ παῖδες ποιεῖσθ’ ὅπλα· πνευστικὸς οὖρος.”", "st": "13"}, {"sp": "N", "t": "νύμφαι μὲν σφετέροις ἐπὶ γούνασι κοῦρον ἔχοισαι<br>δακρυόεντ’ ἀγανοῖσι παρεψύχοντ’ ἐπέεσσιν.<br>Ἀμφιτρυωνιάδας δὲ ταρασσόμενος περὶ παιδὶ<br>ᾤχετο, μαιωτιστὶ λαβὼν εὐκαμπέα τόξα<br>καὶ ῥόπαλον, τό οἱ αἰὲν ἐχάνδανε δεξιτερὴ χείρ.<br>τρὶς μὲν Ὕλαν ἄυσεν, ὅσον βαρὺς ἤρυγε λαιμός·<br>τρὶς δ’ ἄρ’ ὁ παῖς ὑπάκουσεν, ἀραιὰ δ’ ἵκετο φωνὰ<br>ἐξ ὕδατος, παρεὼν δὲ μάλα σχεδὸν εἴδετο πόρρω.<br>ὡς δ’ ὁπότ’ ἠυγένειος ἀπόπροθι λῖς ἐσακούσας†,<br>νεβροῦ φθεγξαμένας τις ἐν οὔρεσιν ὠμοφάγος λῖς<br>ἐξ εὐνᾶς ἔσπευσεν ἑτοιμοτάταν ἐπὶ δαῖτα·<br>Ἡρακλέης τοιοῦτος ἐν ἀτρίπτοισιν ἀκάνθαις<br>παῖδα ποθῶν δεδόνητο, πολὺν δ’ ἐπελάμβανε χῶρον.", "st": "13"}, {"sp": "N", "t": "σχέτλιοι οἱ φιλέοντες· ἀλώμενος ὅσσ’ ἐμόγησεν<br>οὔρεα καὶ δρυμούς, τὰ δ’ Ἰήσονος ὕστερα πάντ’ ἦς.<br>ναῦς γέμεν ἄρμεν’ ἔχοισα μετάρσια τῶν παρεόντων,<br>ἱστία δ’ ἡμίθεοι μεσονύκτιον ἐξεκάθαιρον<br>Ἡρακλῆα μένοντες. ὁ δ’ ᾇ πόδες ἆγον ἐχώρει<br>μαινόμενος· χαλεπὸς γὰρ ἔσω θεὸς ἧπαρ ἄμυσσεν.", "st": "13"}, {"sp": "N", "t": "οὕτω μὲν κάλλιστος Ὕλας μακάρων ἀμιθρεῖται·<br>Ἡρακλέην δ’ ἥρωες ἐκερτόμεον λιποναύταν,<br>οὕνεκεν ἠρώησε τριακοντάζυγον Ἀργώ,<br>πεζᾷ δ’ ἐς Κόλχους τε καὶ ἄξενον ἵκετο Φᾶσιν.", "st": "13"}, {"sp": "SEC", "t": "ΙΔʹ — Κυνίσκας Ἔρως ἢ Θυώνιχος", "st": "14"}, {"sp": "Αἰσχίνης", "t": "χαίρειν πολλὰ τὸν ἄνδρα Θυώνιχον.", "st": "14"}, {"sp": "Θυώνιχος", "t": "ἀλλὰ τὺ ταὐτά,<br>Αἰσχίνα.", "st": "14"}, {"sp": "Αἰσχίνης", "t": "ὡς χρόνιος.", "st": "14"}, {"sp": "Θυώνιχος", "t": "χρόνιος; τί δέ τοι τὸ μέλημα;", "st": "14"}, {"sp": "Αἰσχίνης", "t": "πράσσομες οὐχ ὡς λῷστα Θυώνιχε.", "st": "14"}, {"sp": "Θυώνιχος", "t": "ταῦτ’ ἄρα λεπτός,<br>χὡ μύσταξ πολὺς οὗτος, ἀυσταλέοι δὲ κίκιννοι.<br>τοιοῦτος πρώαν τις ἀφίκετο Πυθαγορικτάς,<br>ὠχρὸς κἀνυπόδητος· Ἀθηναῖος δ’ ἔφατ’ ἦμεν.<br>ἤρατο μὰν καὶ τῆνος, ἐμὶν δοκεῖ, ὀπτῶ ἀλεύρω.", "st": "14"}, {"sp": "Αἰσχίνης", "t": "παίσδεις ὦγάθ’ ἔχων· ἐμὲ δ’ ἁ χαρίεσσα Κυνίσκα<br>ὑβρίσδει· λασῶ δὲ μανείς ποκα, θρὶξ ἀνὰ μέσσον.", "st": "14"}, {"sp": "Θυώνιχος", "t": "τοιοῦτος μὲν ἀεὶ τὺ φίλ’ Αἰσχίνα, ἁσυχᾷ ὀξύς,<br>πάντ’ ἐθέλων κατὰ καιρόν· ὅμως δ’ εἶπον, τί τὸ καινόν.", "st": "14"}, {"sp": "Αἰσχίνης", "t": "ὡργεῖος κἠγὼ καὶ ὁ Θεσσαλὸς ἱπποδιώκτας<br>Ἆπις καὶ Κλεύνικος ἐπίνομες ὁ στρατιώτας<br>ἐν χώρῳ παρ’ ἐμίν. δύο μὲν κατέκοψα νεοσσὼς<br>θηλάζοντά τε χοῖρον, ἀνῷξα δὲ βίβλινον αὐτοῖς<br>εὐώδη, τετόρων ἐτέων, σχεδὸν ὡς ἀπὸ λανῶ.<br>βολβὸς κτεὶς κοχλίας ἐξῃρέθη. ἦς πότος ἁδύς.<br>ἤδη δὲ προϊόντος, ἔδοξ’ ἐπιχεῖσθαι ἄκρατον<br>ὧτινος ἤθελ’ ἕκαστος· ἔδει μόνον ὧτινος εἰπεῖν.<br>ἄμμες μὲν φωνεῦντες ἐπίνομες, ὡς ἐδέδοκτο·<br>ἁ δ’ οὐδὲν παρεόντος ἐμεῦ. τίν’ ἔχειν με δοκεῖς νοῦν;<br>“οὐ φθεγξῇ; λύκον εἶδες·” ἔπαιξέ τις. “ὡς σοφός” εἶπε,<br>κἠφᾶπτ’· εὐμαρέως κεν ἀπ’ αὐτᾶς καὶ λύχνον ἇψας.<br>ἔστι Λύκος, Λύκος ἐστί, Λάβα τῶ γείτονος υἱός,<br>εὐμάκης ἁπαλός, πολλοῖς δοκέων καλὸς ἦμεν.<br>τούτω τὸν κλύμενον κατετάκετο τῆνον ἔρωτα.<br>χἁμῖν τοῦτο δι’ ὠτὸς ἔγεντό ποθ’ ἁσυχᾷ οὑτῶς·<br>οὐ μὰν ἐξήταξα μάταν εἰς ἄνδρα γενειῶν.<br>ἤδη δ’ ὦν πόσιος τοὶ τέσσαρες ἐν βάθει ἦμες,<br>χὡ Λαρισαῖος “τὸν ἐμὸν Λύκον” ᾆδεν ἀπ’ ἀρχᾶς,<br>Θεσσαλικόν τι μέλισμα, κακαὶ φρένες· ἁ δὲ Κυνίσκα<br>ἔκλαι’ ἐξαπίνας θαλερώτερον ἢ παρὰ ματρὶ<br>παρθένος ἑξαέτης κόλπω ἐπιθυμήσασα.<br>τᾶμος ἐγώ, τὸν ἴσαις τὺ Θυώνιχε, πὺξ ἐπὶ κόρρας<br>ἤλασα, κἄλλαν αὖθις. ἀνειρύσσασα δὲ πέπλως<br>ἔξω ἀπῴχετο θᾶσσον. “ἐμὸν κακόν, οὔ τοι ἀρέσκω;<br>ἄλλός τοι γλυκίων ὑποκόλπιος; ἄλλον ἰοῖσα<br>θάλπε φίλον. τήνῳ τὰ σὰ δάκρυα μᾶλα ῥέοντι.”<br>μάστακα δοῖσα τέκνοισιν ὑπωροφίοισι χελιδὼν<br>ἄψορρον ταχινὰ πέτεται βίον ἄλλον ἀγείρειν·<br>ὠκυτέρα μαλακᾶς ἀπὸ δίφρακος ἔδραμε τήνα<br>ἰθὺ δι’ ἀμφιθύρω καὶ δικλίδος, ᾇ πόδες ἆγον.<br>αἶνός θην λέγεταί τις· ἔβα τάχα ταῦρος ἀν’ ὕλαν.<br>εἴκατι· ταὶ δ’ ὀκτώ, ταὶ δ’ ἐννέα, ταὶ δὲ δέκ’ ἄλλαι,<br>σάμερον ἑνδεκάτα, ποτίθει δύο, καὶ δύο μῆνες,<br>ἐξ ὧ ἀπ’ ἀλλάλων. οὐδ’ εἰ Θρᾳκιστὶ κέκαρμαι,<br>οἶδε. Λύκος νῦν πάντα, Λύκῳ καὶ νυκτὸς ἀνῷκται.<br>ἄμμες δ’ οὔτε λόγω τινὸς ἄξιοι οὔτ’ ἀριθμητοί,<br>δύστηνοι Μεγαρῆες ἀτιμοτάτῃ ἐνὶ μοίρῃ.<br>κεἰ μὲν ἀποστέρξαιμι, τὰ πάντά κεν εἰς δέον ἕρποι.<br>νῦν δὲ πόθεν; μῦς, φαντὶ Θυώνιχε, γεύμεθα πίσσας.<br>χὥτι τὸ φάρμακόν ἐστιν ἀμηχανέοντος ἔρωτος,<br>οὐκ οἶδα. πλὰν Σῖμος ὁ τᾶς Ἐπιχάλκω ἐρασθεὶς<br>ἐκπλεύσας ὑγιὴς ἐπανῆλθ’, ἐμὸς ἁλικιώτας.<br>πλευσοῦμαι κἠγὼ διαπόντιος, οὔτε κάκιστος<br>οὔτε πρᾶτος ἴσως, ὁμαλὸς δέ τις ὁ στρατιώτας.", "st": "14"}, {"sp": "Θυώνιχος", "t": "ὤφελε μὰν χωρεῖν κατὰ νοῦν τεόν, ὧν ἐπεθύμεις<br>Αἰσχίνα. εἰ δ’ οὑτῶς ἄρα τοι δοκεῖ ὥστ’ ἀποδαμεῖν,<br>μισθοδότας Πτολεμαῖος ἐλευθέρῳ οἷος ἄριστος,", "st": "14"}, {"sp": "Αἰσχίνης", "t": "τἄλλα δ’ ἀνὴρ ποῖός τις ἐλευθέρῳ οἷος ἄριστος;", "st": "14"}, {"sp": "Θυώνιχος", "t": "εὐγνώμων, φιλόμουσος, ἐρωτικός, εἰς ἄκρον ἁδύς,<br>εἰδὼς τὸν φιλέοντα, τὸν οὐ φιλέοντ’ ἔτι μᾶλλον,<br>πολλοῖς πολλὰ διδούς, αἰτεύμενος οὐκ ἀνανεύων<br>οἷα χρὴ βασιλῆ’· αἰτεῖν δὲ δεῖ οὐκ ἐπὶ παντὶ<br>Αἰσχίνα. ὥστ’ εἴ τοι κατὰ δεξιὸν ὦμον ἀρέσκει<br>λῶπος ἄκρον περονᾶσθαι, ἐπ’ ἀμφοτέροις δὲ βεβακὼς<br>τολμασεῖς ἐπιόντα μένειν θρασὺν ἀσπιδιώταν,<br>ᾇ τάχος εἰς Αἴγυπτον. ἀπὸ κροτάφων πελόμεσθα<br>πάντες γηραλέοι, καὶ ἐπισχερὼ ἐς γένυν ἕρπει<br>λευκαίνων ὁ χρόνος· ποιεῖν τι δεῖ, ἇς γόνυ χλωρόν.", "st": "14"}, {"sp": "SEC", "t": "ΙΕʹ — Συρακούσιαι ἢ Ἀδωνιάζουσαι", "st": "15"}, {"sp": "Γοργώ", "t": "ἔνδοι Πραξινόα;", "st": "15"}, {"sp": "Πραξινόα", "t": "Γοργοῖ φίλα, ὡς χρόνῳ. ἔνδοι.<br>θαῦμ’ ὅτι καὶ νῦν ἦνθες. ὅρη δίφρον Εὐνόα αὐτῇ.<br>ἔμβαλε καὶ ποτίκρανον.", "st": "15"}, {"sp": "Γοργώ", "t": "ἔχει κάλλιστα.", "st": "15"}, {"sp": "Πραξινόα", "t": "καθίζευ.", "st": "15"}, {"sp": "Γοργώ", "t": "ὢ τᾶς ἀλεμάτω ψυχᾶς· μόλις ὔμμιν ἐσώθην<br>Πραξινόα πολλῶ μὲν ὄχλω, πολλῶν δὲ τεθρίππων.<br>παντᾷ κρηπῖδες, παντᾷ χλαμυδηφόροι ἄνδρες·<br>ἁ δ’ ὁδὸς ἄτρυτος· τὺ δ’ ἑκαστάτω ὅσσον ἀποικεῖς.", "st": "15"}, {"sp": "Πραξινόα", "t": "ταῦθ’ ὁ πάραρος τῆνος ἐπ’ ἔσχατα γᾶς ἔλαβ’ ἐνθὼν<br>ἰλεόν, οὐκ οἴκησιν, ὅπως μὴ γείτονες ὦμες<br>ἀλλάλαις, ποτ’ ἔριν, φθονερὸν κακόν, αἰὲν ὁμοῖος.", "st": "15"}, {"sp": "Γοργώ", "t": "μὴ λέγε τὸν τεὸν ἄνδρα φίλα Δίκωνα τοιαῦτα,<br>τῶ μικκῶ παρεόντος· ὅρη γύναι, ὡς ποθορῇ τυ.<br>θάρσει Ζωπυρίων, γλυκερὸν τέκος· οὐ λέγει ἀπφῦν.", "st": "15"}, {"sp": "Πραξινόα", "t": "αἰσθάνεται τὸ βρέφος, ναὶ τὰν πότνιαν.", "st": "15"}, {"sp": "Γοργώ", "t": "καλὸς ἀπφῦς.", "st": "15"}, {"sp": "Πραξινόα", "t": "ἀπφῦς μὰν τῆνος τὰ πρόαν (λέγομες δὲ πρόαν θην<br>πάντα) νίτρον καὶ φῦκος ἀπὸ σκανᾶς ἀγοράσδων<br>ἦνθε φέρων ἅλας ἄμμιν, ἀνὴρ τρισκαιδεκάπηχυς.", "st": "15"}, {"sp": "Γοργώ", "t": "χὡμὸς ταὐτᾷ ἔχει, φθόρος ἀργυρίω, Διοκλείδας·<br>ἑπταδράχμως κυνάδας, γραιᾶν ἀποτίλματα πηρᾶν,<br>πέντε πόκως ἔλαβ’ ἐχθές, ἅπαν ῥύπον, ἔργον ἐπ’ ἔργῳ.<br>ἀλλ’ ἴθι τὠμπέχονον καὶ τὰν περονατρίδα λάζευ.<br>βᾶμες τῶ βασιλῆος ἐς ἀφνειῶ Πτολεμαίω<br>θασόμεναι τὸν Ἄδωνιν· ἀκούω χρῆμα καλόν τι<br>κοσμεῖν τὰν βασίλισσαν.", "st": "15"}, {"sp": "Πραξινόα", "t": "ἐν ὀλβίω ὄλβια πάντα.", "st": "15"}, {"sp": "Γοργώ", "t": "ὧν ἴδες, ὧν εἶπες καὶ ἰδοῖσα τὺ τῷ μὴ ἰδόντι.<br>ἕρπειν ὥρα κ’ εἴη.", "st": "15"}, {"sp": "Πραξινόα", "t": "ἀεργοῖς αἰὲν ἑορτά.<br>Εὐνόα, αἶρε τὸ νῆμα καὶ ἐς μέσον αἰνόθρυπτε<br>θὲς πάλιν. αἱ γαλέαι μαλακῶς χρῄζοντι καθεύδειν·<br>κινεῦ δή, φέρε θᾶσσον ὕδωρ. ὕδατος πρότερον δεῖ.<br>ἁ δὲ σμᾶμα φέρει. δὸς ὅμως. μὴ δὴ πολὺ ἄπληστε.<br>ἔγχει ὕδωρ. δύστανε, τί μευ τὸ χιτώνιον ἄρδεις;<br>παῦε. ὁκοῖα θεοῖς ἐδόκει, τοιαῦτα νένιμμαι.<br>ἁ κλᾲξ τᾶς μεγάλας πᾷ λάρνακος; ὧδε φέρ’ αὐτάν.", "st": "15"}, {"sp": "Γοργώ", "t": "Πραξινόα, μάλα τοι τὸ καταπτυχὲς ἐμπερόναμα<br>τοῦτο πρέπει· λέγε μοι, πόσσω κατέβα τοι ἀφ’ ἱστῶ;", "st": "15"}, {"sp": "Πραξινόα", "t": "μὴ μνάσῃς Γοργοῖ· πλέον ἀργυρίω καθαρῶ μνᾶν<br>ἢ δύο· τοῖς δ’ ἔργοις καὶ τὰν ψυχὰν ποτέθηκα.", "st": "15"}, {"sp": "Γοργώ", "t": "ἀλλὰ κατὰ γνώμαν ἀπέβα τοι.", "st": "15"}, {"sp": "Πραξινόα", "t": "τοῦτο κάλ’ εἶπες.<br>τὠμπέχονον φέρε μοι καὶ τὰν θολίαν κατὰ κόσμον<br>ἀμφίθες. οὐκ ἀξῶ τυ τέκνον. μορμώ, δάκνει ἵππος.<br>δάκρυ’, ὅσσα θέλεις, χωλὸν δ’ οὐ δεῖ τυ γενέσθαι.<br>ἕρπωμες. Φρυγία, τὸν μικκὸν παῖσδε λαβοῖσα,<br>τὰν κύν’ ἔσω κάλεσον, τὰν αὐλείαν ἀπόκλᾳξον.—", "st": "15"}, {"sp": "Πραξινόα", "t": "ὦ θεοί, ὅσσος ὄχλος. πῶς καὶ πόκα τοῦτο περᾶσαι<br>χρὴ τὸ κακόν; μύρμακες ἀνάριθμοι καὶ ἄμετροι.<br>πολλά τοι ὦ Πτολεμαῖε πεποίηται καλὰ ἔργα,<br>ἐξ ὧ ἐν ἀθανάτοις ὁ τεκών· οὐδεὶς κακοεργὸς<br>δαλεῖται τὸν ἰόντα παρέρπων Αἰγυπτιστί,<br>οἷα πρὶν ἐξ ἀπάτας κεκροτημένοι ἄνδρες ἔπαισδον,<br>ἀλλάλοις ὁμαλοί, κακὰ παίγνια, πάντες ἐρειοί.<br>ἁδίστα Γοργοῖ, τί γενοίμεθα; τοὶ πολεμισταὶ<br>ἵπποι τῶ βασιλῆος. ἄνερ φίλε, μή με πατήσῃς.<br>ὀρθὸς ἀνέστα ὁ πυρρός· ἴδ’ ὡς ἄγριος. κυνοθαρσὴς<br>Εὐνόα, οὐ φευξῇ; διαχρησεῖται τὸν ἄγοντα.<br>ὠνάθην μεγάλως, ὅτι μοι τὸ βρέφος μένει ἔνδον.", "st": "15"}, {"sp": "Γοργώ", "t": "θάρσει Πραξινόα· καὶ δὴ γεγενήμεθ’ ὄπισθεν,<br>τοὶ δ’ ἔβαν ἐς χώραν.", "st": "15"}, {"sp": "Πραξινόα", "t": "καὐτὰ συναγείρομαι ἤδη.<br>ἵππον καὶ τὸν ψυχρὸν ὄφιν τὰ μάλιστα δεδοίκω<br>ἐκ παιδός. σπεύδωμες· ὄχλος πολὺς ἄμμιν ἐπιρρεῖ.", "st": "15"}, {"sp": "Γοργώ", "t": "ἐξ αὐλᾶς ὦ μᾶτερ;", "st": "15"}, {"sp": "Γραῦς", "t": "ἐγὼν ὦ τέκνα.", "st": "15"}, {"sp": "Γοργώ", "t": "παρενθεῖν<br>εὐμαρές;", "st": "15"}, {"sp": "Γραῦς", "t": "ἐς Τροίαν πειρώμενοι ἦνθον Ἀχαιοί,<br>καλλίστα παίδων· πείρᾳ θην πάντα τελεῖται.", "st": "15"}, {"sp": "Γοργώ", "t": "χρησμὼς ἁ πρεσβῦτις ἀπῴχετο θεσπίξασα.", "st": "15"}, {"sp": "Πραξινόα", "t": "πάντα γυναῖκες ἴσαντι, καὶ ὡς Ζεὺς ἠγάγεθ’ Ἥρην.", "st": "15"}, {"sp": "Γοργώ", "t": "θᾶσαι Πραξινόα, περὶ τὰς θύρας ὅσσος ὅμιλος.", "st": "15"}, {"sp": "Πραξινόα", "t": "θεσπέσιος. Γοργοῖ, δὸς τὰν χέρα μοι· λάβε καὶ τὺ<br>Εὐνόα Εὐτυχίδος· πότεχ’ αὐτᾷ, μή τι πλαναθῇς.<br>πᾶσαι ἅμ’ εἰσένθωμες· ἀπρὶξ ἔχευ Εὐνόα ἁμῶν.<br>οἴμοι δειλαία, δίχα μευ τὸ θερίστριον ἤδη<br>ἔσχισται Γοργοῖ. πὸτ τῶ Διός, εἴτι γένοιο<br>εὐδαίμων ὤνθρωπε, φυλάσσεο τὠμπέχονόν μευ.", "st": "15"}, {"sp": "Ξένος", "t": "οὐκ ἐπ’ ἐμὶν μέν, ὅμως δὲ φυλαξεῦμαι·", "st": "15"}, {"sp": "Πραξινόα", "t": "ὄχλος ἄθρως.<br>ὠθεῦνθ’ ὥσπερ ὕες.", "st": "15"}, {"sp": "Ξένος", "t": "θάρσει γύναι· ἐν καλῷ εἰμές.", "st": "15"}, {"sp": "Πραξινόα", "t": "κεἰς ὥρας κἤπειτα φίλ’ ἀνδρῶν ἐν καλῷ εἴης<br>ἄμμε περιστέλλων. χρηστῶ κᾠκτίρμονος ἀνδρός.<br>φλίβεται Εὐνόα ἇμιν· ἄγ’ ὦ δειλὰ τὺ βιάζευ.<br>κάλλιστ’· ἔνδοι πᾶσαι, ὁ τὰν νυὸν εἶπ’ ἀποκλᾴξας.", "st": "15"}, {"sp": "Γοργώ", "t": "Πραξινόα, πόταγ’ ὧδε. τὰ ποικίλα πρᾶτον ἄθρησον,<br>λεπτὰ καὶ ὡς χαρίεντα· θεῶν περονάματα φασεῖς.", "st": "15"}, {"sp": "Πραξινόα", "t": "πότνι’ Ἀθαναία, ποῖαί σφ’ ἐπόνασαν ἔριθοι,<br>ποῖοι ζῳογράφοι τἀκριβέα γράμματ’ ἔγραψαν.<br>ὡς ἔτυμ’ ἑστάκαντι, καὶ ὡς ἔτυμ’ ἐνδινεῦντι,<br>ἔμψυχ’, οὐκ ἐνυφαντά. σοφόν τοι χρῆμ’ ὥνθρωπος.<br>αὐτὸς δ’ ὡς θαητὸς ἐπ’ ἀργυρέας κατάκειται<br>κλισμῶ, πρᾶτον ἴουλον ἀπὸ κροτάφων καταβάλλων,<br>ὁ τριφίλητος Ἄδωνις, ὃ κἠν Ἀχέροντι φιλεῖται.", "st": "15"}, {"sp": "Ἕτερος Ξένος", "t": "παύσασθ’ ὦ δύστανοι, ἀνάνυτα κωτίλλοισαι<br>τρυγόνες. ἐκκναισεῦντι πλατειάσδοισαι ἅπαντα.", "st": "15"}, {"sp": "Γοργώ", "t": "μᾶ, πόθεν ὥνθρωπος; τί δὲ τίν, εἰ κωτίλαι εἰμές;<br>πασάμενος ἐπίτασσε. Συρακοσίαις ἐπιτάσσεις;<br>ὡς δ’ εἰδῇς καὶ τοῦτο· Κορίνθιαι εἰμὲς ἄνωθεν,<br>ὡς καὶ ὁ Βελλεροφῶν· Πελοποννασιστὶ λαλεῦμες·<br>δωρίσδεν δ’ ἔξεστι δοκῶ τοῖς Δωριέεσσι.", "st": "15"}, {"sp": "Πραξινόα", "t": "μὴ φύη Μελιτῶδες ὃς ἁμῶν καρτερὸς εἴη,<br>πλὰν ἑνός. οὐκ ἀλέγω. μή μοι κενεὰν ἀπομάξῃς.", "st": "15"}, {"sp": "Γοργώ", "t": "σίγη Πραξινόα· μέλλει τὸν Ἄδωνιν ἀείδειν<br>ἁ τᾶς Ἀργείας θυγάτηρ πολύιδρις ἀοιδός,<br>ἅτις καὶ πέρυσιν τὸν ἰάλεμον ἀρίστευσε.<br>φθεγξεῖταί τι σάφ’ οἶδα καλόν· διαθρύπτεται ἤδη.", "st": "15"}, {"sp": "Γυνὴ Ἀοιδός", "t": "Δέσποιν’, ἃ Γολγώς τε καὶ Ἰδάλιον ἐφίλασας<br>αἰπεινάν τ’ Ἐρύκαν, χρυσῷ παίζοισ’ Ἀφροδίτα·<br>οἷόν τοι τὸν Ἄδωνιν ἀπ’ ἀενάω Ἀχέροντος<br>μηνὶ δυωδεκάτῳ μαλακαὶ πόδας ἄγαγον Ὧραι.<br>βάρδισται μακάρων Ὧραι φίλαι, ἀλλὰ ποθειναὶ<br>ἔρχονται πάντεσσι βροτοῖς αἰεί τι φορεῦσαι.<br>Κύπρι Διωναία, τὺ μὲν ἀθανάταν ἀπὸ θνατᾶς,<br>ἀνθρώπων ὡς μῦθος, ἐποίησας Βερενίκαν,<br>ἀμβροσίαν ἐς στῆθος ἀποστάξασα γυναικός·<br>τὶν δὲ χαριζομένα, πολυώνυμε καὶ πολύναε,<br>ἁ Βερενικεία θυγάτηρ Ἑλένᾳ εἰκυῖα<br>Ἀρσινόα πάντεσσι καλοῖς ἀτιτάλλει Ἄδωνιν.<br>πὰρ μέν οἱ ὥρια κεῖται, ὅσα δρυὸς ἄκρα φέρονται,<br>πὰρ δ’ ἁπαλοὶ κᾶποι πεφυλαγμένοι ἐν ταλαρίσκοις<br>ἀργυρέοις, Συρίω δὲ μύρω χρύσει’ ἀλάβαστρα.<br>εἴδατα δ’ ὅσσα γυναῖκες ἐπὶ πλαθάνω πονέονται,<br>ἄνθεα μίσγοισαι λευκῷ παντοῖα μαλεύρῳ,<br>ὅσσά τ’ ἀπὸ γλυκερῶ μέλιτος τά τ’ ἐν ὑγρῷ ἐλαίῳ,<br>πάντ’ αὐτῷ πετεηνὰ καὶ ἑρπετὰ τεῖδε πάρεστι.<br>χλωραὶ δὲ σκιάδες μαλακῷ βρίθοντι ἀνήθῳ<br>δέδμανθ’· οἱ δέ τε κῶροι ὑπερπωτῶνται Ἔρωτες,<br>οἷοι ἀηδονιδῆες ἀεξομενᾶν ἐπὶ δένδρων<br>πωτῶνται πτερύγων πειρώμενοι ὄζον ἀπ’ ὄζω.<br>ὢ ἔβενος, ὢ χρυσός, ὢ ἐκ λευκῶ ἐλέφαντος<br>αἰετοὶ οἰνοχόον Κρονίδᾳ Διὶ παῖδα φέροντες.<br>πορφύρεοι δὲ τάπητες ἄνω μαλακώτεροι ὕπνω,<br>ἁ Μίλατος ἐρεῖ χὡ τὰν Σαμίαν κάτα βόσκων·<br>“ἔστρωται κλίνα τῷ Ἀδώνιδι τῷ καλῷ ἄλλα.”<br>τὰν μὲν Κύπρις ἔχει, τὰν δ’ ὁ ῥοδόπαχυς Ἄδωνις<br>ὀκτωκαιδεκέτης ἢ ἐννεακαίδεχ’ ὁ γαμβρός.<br>οὐ κεντεῖ τὸ φίλημ’, ἔτι οἱ περὶ χείλεα πυρρά.<br>νῦν μὰν Κύπρις ἔχοισα τὸν αὐτᾶς χαιρέτω ἄνδρα·<br>ἀῶθεν δ’ ἁμές νιν ἅμα δρόσῳ ἀθρόαι ἔξω<br>οἰσεῦμες ποτὶ κύματ’ ἐπ’ ἀιόνι πτύοντα,<br>λύσασαι δὲ κόμαν καὶ ἐπὶ σφυρὰ κόλπον ἀνεῖσαι<br>στήθεσι φαινομένοις λιγυρᾶς ἀρξώμεθ’ ἀοιδᾶς·<br>Ἕρπεις ὦ φίλ’ Ἄδωνι καὶ ἐνθάδε κεἰς Ἀχέροντα<br>ἡμιθέων, ὡς φαντί, μονώτατος. οὔτ’ Ἀγαμέμνων<br>τοῦτ’ ἔπαθ’, οὔτ’ Αἴας ὁ μέγας βαρυμάνιος ἥρως,<br>οὔθ’ Ἕκτωρ Ἑκάβας ὁ γεραίτερος εἴκατι παίδων,<br>οὐ Πατροκλῆς, οὐ Πύρρος ἀπὸ Τροίας ἐπανελθών,<br>οὔθ’ οἱ ἔτι πρότερον Λαπίθαι καὶ Δευκαλίωνες,<br>οὐ Πελοπηιάδαι τε καὶ Ἄργεος ἄκρα Πελασγοί·<br>ἵλαθι νῦν φίλ’ Ἄδωνι, καὶ ἐς νέωτ’ εὐθυμήσαις.<br>καὶ νῦν ἦνθες Ἄδωνι, καὶ ὅκκ’ ἀφίκῃ, φίλος ἡξεῖς.", "st": "15"}, {"sp": "Γοργώ", "t": "Πραξινόα, τὸ χρῆμα σοφώτερον ἁ θήλεια.<br>ὀλβία ὅσσα ἴσατι, πανολβία ὡς γλυκὺ φωνεῖ.<br>ὥρα ὅμως κεἰς οἶκον. ἀνάριστος Διοκλείδας.<br>χὡνὴρ ὄξος ἅπαν, πεινᾶντι δὲ μηδὲ ποτένθῃς.<br>χαῖρε Ἄδων ἀγαπητέ· καὶ ἐς χαίροντας ἀφίκευ.", "st": "15"}, {"sp": "SEC", "t": "ΙϚʹ — Χάριτες ἢ Ἱέρων", "st": "16"}, {"sp": "N", "t": "αἰεὶ τοῦτο Διὸς κούραις μέλει, αἰὲν ἀοιδοῖς,<br>ὑμνεῖν ἀθανάτους, ὑμνεῖν ἀγαθῶν κλέα ἀνδρῶν.<br>Μοῦσαι μὲν θεαὶ ἐντί, θεοὺς θεαὶ ἀείδοντι·<br>ἄμμες δὲ βροτοὶ οἵδε, βροτοὺς βροτοὶ ἀείδωμεν.<br>τίς γὰρ τῶν ὁπόσοι γλαυκὰν ναίουσιν ὑπ’ ἀῶ<br>ἡμετέρας Χάριτας πετάσας ὑποδέξεται οἴκῳ<br>ἀσπασίως, οὐδ’ αὖθις ἀδωρήτους ἀποπέμψει;<br>αἱ δὲ σκυζόμεναι γυμνοῖς ποσὶν οἴκαδ’ ἴασι,<br>πολλά με τωθάζοισαι, ὅ τ’ ἀλιθίαν ὁδὸν ἦνθον,<br>ὀκνηραὶ δὲ πάλιν κενεᾶς ἐν πυθμένι χηλοῦ<br>ψυχροῖς ἐν γονάτεσσι κάρη μίμνοντι βαλοῖσαι,<br>ἔνθ’ αἰεί σφισιν ἕδρα, ἐπὴν ἄπρηκτοι ἵκωνται.", "st": "16"}, {"sp": "N", "t": "τίς τῶν νῦν τοιόσδε; τίς εὖ εἰπόντα φιλήσει;<br>οὐκ οἶδ’· οὐ γὰρ ἔτ’ ἄνδρες ἐπ’ ἔργμασιν ὡς πάρος ἐσθλοῖς<br>αἰνεῖσθαι σπεύδοντι, νενίκηνται δ’ ὑπὸ κερδέων.<br>πᾶς δ’ ὑπὸ κόλπῳ χεῖρας ἔχων πόθεν οἴσεται ἀθρεῖ<br>ἄργυρον, οὐδέ κεν ἰὸν ἀποτρίψας τινὶ δοίη,<br>ἀλλ’ εὐθὺς μυθεῖται· “ἀπωτέρω ἢ γόνυ κνάμα·<br>αὐτῷ μοί τι γένοιτο· θεοὶ τιμῶσιν ἀοιδούς.<br>τίς δέ κεν ἄλλου ἀκούσαι; ἅλις πάντεσσιν Ὅμηρος.<br>οὗτος ἀοιδῶν λῷστος, ὃς ἐξ ἐμεῦ οἴσεται οὐδέν.”", "st": "16"}, {"sp": "N", "t": "δαιμόνιοι, τί δὲ κέρδος ὁ μυρίος ἔνδοθι χρυσὸς<br>κείμενος; οὐχ ἅδε πλούτου φρονέουσιν ὄνασις,<br>ἀλλὰ τὸ μὲν ψυχᾷ, τὸ δὲ καί τινι δοῦναι ἀοιδῶν·<br>πολλοὺς δ’ εὖ ἔρξαι παῶν, πολλοὺς δὲ καὶ ἄλλων<br>ἀνθρώπων, αἰεὶ δὲ θεοῖς ἐπιβώμια ῥέζειν,<br>μηδὲ ξεινοδόκον κακὸν ἔμμεναι, ἀλλὰ τραπέζῃ<br>μειλίξαντ’ ἀποπέμψαι, ἐπὴν ἐθέλωντι νέεσθαι,<br>Μουσάων δὲ μάλιστα τίειν ἱεροὺς ὑποφήτας,<br>ὄφρα καὶ εἰν Ἀίδαο κεκρυμμένος ἐσθλὸς ἀκούσῃς,<br>μηδ’ ἀκλεὴς μύρηαι ἐπὶ ψυχροῦ Ἀχέροντος,<br>ὡσεί τις μακέλᾳ τετυλωμένος ἔνδοθι χεῖρας<br>ἀχὴν ἐκ πατέρων πενίην ἀκτήμονα κλαίων.", "st": "16"}, {"sp": "N", "t": "πολλοὶ ἐν Ἀντιόχοιο δόμοις καὶ ἄνακτος Ἀλεύα<br>ἁρμαλιὴν ἔμμηνον ἐμετρήσαντο πενέσται·<br>πολλοὶ δὲ Σκοπάδῃσιν ἐλαυνόμενοι ποτὶ σακοὺς<br>μόσχοι σὺν κεραῇσιν ἐμυκήσαντο βόεσσι,<br>μυρία δ’ ἀμπεδίον Κραννώνιον ἐνδιάασκον<br>ποιμένες ἔκκριτα μῆλα φιλοξείνοισι Κρεώνδαις·<br>ἀλλ’ οὔ σφιν τῶν ἦδος, ἐπεὶ γλυκὺν ἐξεκένωσαν<br>θυμὸν ἐς εὐρεῖαν σχεδίαν στυγνοῦ Ἀχέροντος,<br>ἄμναστοι δὲ τὰ πολλὰ καὶ ὄλβια τῆνα λιπόντες<br>δειλοῖς ἐν νεκύεσσι μακροὺς αἰῶνας ἔκειντο,<br>εἰ μὴ κεῖνος ἀοιδὸς ὁ Κήιος αἰόλα φωνέων<br>βάρβιτον ἐς πολύχορδον ἐν ἀνδράσι θῆκ’ ὀνομαστοὺς<br>ὁπλοτέροις, τιμᾶς δὲ καὶ ὠκέες ἔλλαχον ἵπποι,<br>οἵ σφισιν ἐξ ἱερῶν στεφανηφόροι ἦλθον ἀγώνων.", "st": "16"}, {"sp": "N", "t": "τίς δ’ ἂν ἀριστῆας Λυκίων ποτέ, τίς κομόωντας<br>Πριαμίδας ἢ θῆλυν ἀπὸ χροιᾶς Κύκνον ἔγνω,<br>εἰ μὴ φυλόπιδας προτέρων ὕμνησαν ἀοιδοί;<br>οὐδ’ Ὀδυσεὺς ἑκατόν τε καὶ εἴκοσι μῆνας ἀλαθεὶς<br>πάντας ἐπ’ ἀνθρώπους, Ἀίδαν τ’ εἰς ἔσχατον ἐλθὼν<br>ζωός, καὶ σπήλυγγα φυγὼν ὀλοοῖο Κύκλωπος,<br>δηναιὸν κλέος ἔσχεν, ἐσιγάθη δ’ ἂν ὑφορβὸς<br>Εὔμαιος, καὶ βουσὶ Φιλοίτιος ἀμφ’ ἀγελαίαις<br>ἔργον ἔχων, αὐτός τε περίσπλαγχνος Λαέρτης,<br>εἰ μή σφεας ὤνασαν Ἰάονος ἀνδρὸς ἀοιδαί.", "st": "16"}, {"sp": "N", "t": "Ἐκ Μοισᾶν ἀγαθὸν κλέος ἔρχεται ἀνθρώποισι,<br>χρήματα δὲ ζώοντες ἀμαλδύνουσι θανόντων.<br>ἀλλ’ ἶσος γὰρ ὁ μόχθος ἐπ’ ᾀόνι κύματα μετρεῖν,<br>ὅσσ’ ἄνεμος χέρσονδε μετὰ γλαυκᾶς ἁλὸς ὠθεῖ,<br>ἢ ὕδατι νίζειν θολερὰν διαειδέι πλίνθον,<br>καὶ φιλοκερδείᾳ βεβλαμμένον ἄνδρα παρελθεῖν.<br>χαιρέτω ὃς τοιοῦτος, ἀνάριθμος δέ οἱ εἰη<br>ἄργυρος, αἰεὶ δὲ πλεόνων ἔχοι ἵμερος αὐτόν.<br>αὐτὰρ ἐγὼ τιμήν τε καὶ ἀνθρώπων φιλότητα<br>πολλῶν ἡμιόνων τε καὶ ἵππων πρόσθεν ἑλοίμαν.", "st": "16"}, {"sp": "N", "t": "δίζημαι δ’, ὅτινι θνατῶν κεχαρισμένος ἔνθω<br>σὺν Μοίσαις· χαλεπαὶ γὰρ ὁδοὶ τελέθουσιν ἀοιδοῖς<br>κουράων ἀπάνευθε Διὸς μέγα βουλεύοντος.<br>οὔπω μῆνας ἄγων ἔκαμ’ οὐρανὸς οὐδ’ ἐνιαυτούς·<br>πολλοὶ κινήσουσιν ἔτι τροχὸν ἅρματος ἵπποι·<br>ἔσσεται οὗτος ἀνήρ, ὃς ἐμεῦ κεχρήσετ’ ἀοιδοῦ,<br>ῥέξας ἢ Ἀχιλεὺς ὅσσον μέγας ἢ βαρὺς Αἴας<br>ἐν πεδίῳ Σιμόεντος, ὅθι Φρυγὸς ἠρίον Ἴλου.", "st": "16"}, {"sp": "N", "t": "ἤδη νῦν Φοίνικες ὑπ’ ἠελίῳ δύνοντι<br>οἰκεῦντες Λιβύας ἄκρον σφυρὸν ἐρρίγασιν.<br>ἤδη βαστάζουσι Συρακόσιοι μέσα δοῦρα<br>ἀχθόμενοι σακέεσσι βραχίονας ἰτεΐνοισιν·<br>ἐν δ’ αὐτοῖς Ἱέρων προτέροις ἴσος ἡρώεσσι<br>ζώννυται, ἵππειαι δὲ κόρυν σκεπάουσιν ἔθειραι.<br>αἰ γὰρ Ζεῦ κύδιστε πάτερ καὶ πότνι’ Ἀθάνα<br>κούρη θ’, ἣ σὺν ματρὶ πολυκλήρων Ἐφυραίων<br>εἴληχας μέγα ἄστυ παρ’ ὕδασι Λυσιμελείας,<br>ἐχθροὺς ἐκ νάσοιο κακὰ πέμψειεν ἀνάγκα<br>Σαρδόνιον κατὰ κῦμα, φίλων μόρον ἀγγέλλοντας<br>τέκνοις ἠδ’ ἀλόχοισιν, ἀριθμητοὺς ἀπὸ πολλῶν·<br>ἄστεά τε προτέροισι πάλιν ναίοιτο πολίταις,<br>δυσμενέων ὅσα χεῖρες ἐλωβήσαντο κατάκρας·<br>ἀγροὺς δ’ ἐργάζοιντο τεθαλότας· αἱ δ’ ἀνάριθμοι<br>μήλων χιλιάδες βοτάνᾳ διαπιανθεῖσαι<br>ἀμπεδίον βληχοῖντο, βόες δ’ ἀγελαδὸν ἐς αὖλιν<br>ἐρχόμεναι σκνιφαῖον ἐπισπεύδοιεν ὁδίταν·<br>νειοὶ δ’ ἐκπονέοιντο ποτὶ σπόρον, ἁνίκα τέττιξ<br>ποιμένας ἐνδίους πεφυλαγμένος ἔνδοθι δένδρων<br>ἀχεῖ ἐν ἀκρεμόνεσσιν· ἀράχνια δ’ εἰς ὅπλ’ ἀράχναι<br>λεπτὰ διαστήσαιντο, βοᾶς δ’ ἔτι μηδ’ ὄνομ’ εἴη.", "st": "16"}, {"sp": "N", "t": "ὑψηλὸν δ’ Ἱέρωνι κλέος φορέοιεν ἀοιδοὶ<br>καὶ πόντου Σκυθικοῖο πέραν καὶ ὅθι πλατὺ τεῖχος<br>ἀσφάλτῳ δήσασα Σεμίραμις ἐμβασίλευεν.<br>εἷς μὲν ἐγώ, πολλοὺς δὲ Διὸς φιλέοντι καὶ ἄλλους<br>θυγατέρες, τοῖς πᾶσι μέλοι Σικελὰν Ἀρέθοισαν<br>ὑμνεῖν σὺν λαοῖσι καὶ αἰχμητὰν Ἱέρωνα.<br>ὦ Ἐτεόκλειοι θύγατρες θεαί, ὦ Μινύειον<br>Ὀρχομενὸν φιλέοισαι ἀπεχθόμενόν ποτε Θήβαις,<br>ἄκλητος μὲν ἔγωγε μένοιμί κεν, ἐς δὲ καλεύντων<br>θαρσήσας Μοίσαισι σὺν ἁμετέραισιν ἱκοίμαν.<br>καλλείψω δ’ οὐδ’ ὔμμε· τί γὰρ Χαρίτων ἀγαπητὸν<br>ἀνθρώποις ἀπάνευθεν; ἀεὶ Χαρίτεσσιν ἅμ’ εἴην.", "st": "16"}, {"sp": "SEC", "t": "ΙΖʹ — Ἐγκώμιον εἰς Πτολεμαῖον", "st": "17"}, {"sp": "N", "t": "Ἐκ Διὸς ἀρχώμεσθα καὶ ἐς Δία λήγετε Μοῖσαι,<br>ἀθανάτων τὸν ἄριστον ἐπὴν αὐδῶμεν ἀοιδαῖς·<br>ἀνδρῶν δ’ αὖ Πτολεμαῖος ἐνὶ πρώτοισι λεγέσθω<br>καὶ πύματος καὶ μέσσος· ὁ γὰρ προφερέστατος ἄλλων.<br>ἥρωες, τοὶ πρόσθεν ἀφ’ ἡμιθέων ἐγένοντο,<br>ῥέξαντες καλὰ ἔργα σοφῶν ἐκύρησαν ἀοιδῶν·<br>αὐτὰρ ἐγὼ Πτολεμαῖον ἐπιστάμενος καλὰ εἰπεῖν<br>ὑμνήσαιμ’· ὕμνοι δὲ καὶ ἀθανάτων γέρας αὐτῶν.", "st": "17"}, {"sp": "N", "t": "Ἴδαν ἐς πολύδενδρον ἀνὴρ ὑλατόμος ἐλθὼν<br>παπταίνει, παρεόντος ἄδην, πόθεν ἄρξεται ἔργου.<br>τί πρῶτον καταλέξω; ἐπεὶ πάρα μυρία εἰπεῖν,<br>οἷσι θεοὶ τὸν ἄριστον ἐτίμησαν βασιλήων.", "st": "17"}, {"sp": "N", "t": "Ἐκ πατέρων οἷος μὲν ἔην τελέσαι μέγα ἔργον<br>Λαγείδας Πτολεμαῖος, ὅτε φρεσὶν ἐγκατάθοιτο<br>βουλάν, ἃν οὐκ ἄλλος ἀνὴρ οἷός τε νοῆσαι.<br>τῆνον καὶ μακάρεσσι πατὴρ ὁμότιμον ἔθηκεν<br>ἀθανάτοις, καί οἱ χρύσεος δόμος ἐν Διὸς οἴκῳ<br>δέδμηται· παρὰ δ’ αὐτὸν Ἀλέξανδρος φίλα εἰδὼς<br>ἑδριάει, Πέρσαισι βαρὺς θεὸς αἰολομίτρας.", "st": "17"}, {"sp": "N", "t": "ἀντία δ’ Ἡρακλῆος ἕδρα κενταυροφόνοιο<br>ἵδρυται στερεοῖο τετυγμένα ἐξ ἀδάμαντος·<br>ἔνθα σὺν ἄλλοισιν θαλίας ἔχει οὐρανίδαισι,<br>χαίρων υἱωνῶν περιώσιον υἱωνοῖσιν,<br>ὅττί σφεων Κρονίδης μελέων ἐξείλετο γῆρας,<br>ἀθάνατοι δὲ καλεῦνται ἑοὶ νέποδες γεγαῶτες.<br>ἄμφω γὰρ πρόγονός σφιν ὁ καρτερὸς Ἡρακλείδας,<br>ἀμφότεροι δ’ ἀριθμεῦνται ἐς ἔσχατον Ἡρακλῆα.", "st": "17"}, {"sp": "N", "t": "τῷ καὶ ἐπεὶ δαίτηθεν ἴοι κεκορημένος ἤδη<br>νέκταρος εὐόδμοιο φίλας ἐς δῶμ’ ἀλόχοιο,<br>τῷ μὲν τόξον ἔδωκεν ὑπωλένιόν τε φαρέτραν,<br>τῷ δὲ σιδάρειον σκύταλον κεχαραγμένον ὄζοις.<br>οἱ δ’ εἰς ἀμβρόσιον θάλαμον λευκοσφύρου Ἥβης<br>ὅπλα καὶ αὐτὸν ἄγουσι γενειήταν Διὸς υἱόν.", "st": "17"}, {"sp": "N", "t": "οἵα δ’ ἐν πινυταῖσι περικλειτὰ Βερενίκα<br>ἔπρεπε θηλυτέραις, ὄφελος μέγα γειναμένοισι.<br>τᾷ μὲν Κύπρον ἔχοισα Διώνας πότνια κούρα<br>κόλπον ἐς εὐώδη ῥαδινὰς ἐσεμάξατο χεῖρας.<br>τῷ οὔπω τινὰ φαντὶ ἁδεῖν τόσον ἀνδρὶ γυναικῶν,<br>ὅσσόν περ Πτολεμαῖος ἑὴν ἐφίλησεν ἄκοιτιν.<br>ἦ μὰν ἀντεφιλεῖτο πολὺ πλέον· ὧδέ κε παισὶ<br>θαρσήσας σφετέροισιν ἐπιτρέποι οἶκον ἅπαντα,<br>ὁππότε κεν φιλέων βαίνῃ λέχος ἐς φιλεούσης.<br>ἀστόργου δὲ γυναικὸς ἐπ’ ἀλλοτρίῳ νόος αἰεί,<br>ῥηίδιοι δὲ γοναί, τέκνα δ’ οὐ ποτεοικότα πατρί.", "st": "17"}, {"sp": "N", "t": "κάλλει ἀριστεύουσα θεάων πότν’ Ἀφροδίτα,<br>σοὶ τήνα μεμέλητο· σέθεν δ’ ἕνεκεν Βερενίκα<br>εὐειδὴς Ἀχέροντα πολύστονον οὐκ ἐπέρασεν,<br>ἀλλά μιν ἁρπάξασα, πάροιθ’ ἐπὶ νῆα κατελθεῖν<br>κυανέαν καὶ στυγνὸν ἀεὶ πορθμῆα καμόντων,<br>ἐς ναὸν κατέθηκας, ἑᾶς δ’ ἀπεδάσσαο τιμᾶς.<br>πᾶσιν δ’ ἤπιος ἥδε βροτοῖς μαλακοὺς μὲν ἔρωτας<br>προσπνείει, κούφας δὲ διδοῖ ποθέοντι μερίμνας.—", "st": "17"}, {"sp": "N", "t": "Ἀργεία κυάνοφρυ, σὺ λαοφόνον Διομήδεα<br>μισγομένα Τυδῆι τέκες, Καλυδώνιον ἄνδρα,<br>ἀλλὰ Θέτις βαθύκολπος ἀκοντιστὰν Ἀχιλῆα<br>Αἰακίδᾳ Πηλῆι, σὲ δ’ αἰχμητὰ Πτολεμαῖε<br>αἰχμητᾷ Πτολεμαίῳ ἀρίζηλος Βερενίκα.<br>καί σε Κόως ἀτίταλλε βρέφος νεογιλλὸν ἐόντα,<br>δεξαμένα παρὰ ματρός, ὅτε πρώταν ἴδες ἀῶ.<br>ἔνθα γὰρ Εἰλείθυιαν ἐβώσατο λυσίζωνον<br>Ἀντιγόνας θυγάτηρ βεβαρημένα ὠδίνεσσιν·<br>ἡ δέ οἱ εὐμενέοισα παρίστατο, κὰδ δ’ ἄρα πάντων<br>νωδυνίαν κατέχευε μελῶν· ὁ δὲ πατρὶ ἐοικὼς<br>παῖς ἀγαπητὸς ἔγεντο. Κόως δ’ ὀλόλυξεν ἰδοῖσα,<br>φᾶ δὲ καθαπτομένα βρέφεος χείρεσσι φίλῃσιν·", "st": "17"}, {"sp": "N", "t": "“Ὄλβιε κοῦρε γένοιο, τίοις δέ με τόσσον, ὅσον περ<br>Δᾶλον ἐτίμησεν κυανάμπυκα Φοῖβος Ἀπόλλων·<br>ἐν δὲ μιᾷ τιμᾷ Τρίοπον καταθεῖο κολώναν,<br>ἶσον Δωριέεσσι νέμων γέρας ἐγγὺς ἐοῦσιν.”<br>ἶσον καὶ Ῥήναιαν ἄναξ ἐφίλησεν Ἀπόλλων.", "st": "17"}, {"sp": "N", "t": "Ὣς ἄρα νᾶσος ἔειπεν· ὁ δ’ ὑψόθεν ἔκλαγε φωνᾷ<br>ἐς τρὶς ἀπὸ νεφέων μέγας αἰετὸς αἴσιος ὄρνις.<br>Ζηνός που τόδε σᾶμα. Διὶ Κρονίωνι μέλοντι<br>αἰδοῖοι βασιλῆες· ὁ δ’ ἔξοχος, ὅν κε φιλήσῃ<br>γεινόμενον τὰ πρῶτα· πολὺς δέ οἱ ὄλβος ὀπαδεῖ,<br>πολλᾶς δὲ κρατέει γαίας, πολλᾶς δὲ θαλάσσας.", "st": "17"}, {"sp": "N", "t": "μυρίαι ἄπειροί τε καὶ ἔθνεα μυρία φωτῶν<br>λήιον ἀλδήσκουσιν ὀφελλόμεναι Διὸς ὄμβρῳ·<br>ἀλλ’ οὔτις τόσα φύει, ὅσα χθαμαλὰ Αἴγυπτος,<br>Νεῖλος ἀναβλύζων διερὰν ὅτε βώλακα θρύπτει.<br>οὐδέ τις ἄστεα τόσσα βροτῶν ἔχει ἔργα δαέντων.<br>τρεῖς μέν οἱ πολίων ἑκατοντάδες ἐνδέδμηνται,<br>τρεῖς δ’ ἄρα χιλιάδες τρισσαῖς ἐπὶ μυριάδεσσι,<br>δοιαὶ δὲ τριάδες, μετὰ δέ σφισιν ἐννεάδες τρεῖς·<br>τῶν πάντων Πτολεμαῖος ἀγήνωρ ἐμβασιλεύει.", "st": "17"}, {"sp": "N", "t": "καὶ μὴν Φοινίκας ἀποτέμνεται Ἀρραβίας τε<br>καὶ Συρίας Λιβύας τε κελαινῶν τ’ Αἰθιοπήων.<br>Παμφύλοισί τε πᾶσι καὶ αἰχμηταῖς Κιλίκεσσι<br>σαμαίνει, Λυκίοις τε φιλοπτολέμοισί τε Καρσί,<br>καὶ νάσοις Κυκλάδεσσιν, ἐπεί οἱ νᾶες ἄρισται<br>πόντον ἐπιπλώοντι, θάλασσα δὲ πᾶσα καὶ αἶα<br>καὶ ποταμοὶ κελάδοντες ἀνάσσονται Πτολεμαίῳ.<br>πολλοὶ δ’ ἱππῆες, πολλοὶ δέ μιν ἀσπιδιῶται.<br>χαλκῷ μαρμαίροντι σεσαγμένοι ἀμφαγέρονται.<br>ὄλβῳ μὲν πάντάς κε καταβρίθοι βασιλῆας·<br>τόσσον ἐπ’ ἆμαρ ἕκαστον ἐς ἀφνεὸν ἔρχεται οἶκον<br>πάντοθε. λαοὶ δ’ ἔργα περιστέλλουσιν ἕκηλοι.<br>οὐ γάρ τις δηίων πολυκήτεα Νεῖλον ὑπερβὰς<br>πεζὸς ἐν ἀλλοτρίαισι βοὰν ἐστάσατο κώμαις,<br>οὐδέ τις αἰγιαλόνδε θοᾶς ἐξάλατο ναὸς<br>θωρηχθεὶς ἐπὶ βουσὶν ἀνάρσιος Αἰγυπτίῃσι·<br>τοῖος ἀνὴρ πλατέεσσιν ἐνίδρυται πεδίοισι<br>ξανθοκόμας Πτολεμαῖος, ἐπιστάμενος δόρυ πάλλειν,<br>ᾧ ἐπὶ πάγχυ μέλει πατρώια πάντα φυλάσσειν<br>οἷ’ ἀγαθῷ βασιλῆι, τὰ δὲ κτεατίζεται αὐτός.<br>οὐ μὰν ἀχρεῖός γε δόμῳ ἐνὶ πίονι χρυσὸς<br>μυρμάκων ἅτε πλοῦτος ἀεὶ κέχυται μογεόντων·<br>ἀλλὰ πολὺν μὲν ἔχοντι θεῶν ἐρικυδέες οἶκοι,<br>αἰὲν ἀπαρχομένοιο σὺν ἄλλοισιν γεράεσσι,<br>πολλὸν δ’ ἰφθίμοισι δεδώρηται βασιλεῦσι,<br>πολλὸν δὲ πτολίεσσι, πολὺν δ’ ἀγαθοῖσιν ἑταίροις.<br>οὐδὲ Διωνύσου τις ἀνὴρ ἱεροὺς κατ’ ἀγῶνας<br>ἵκετ’ ἐπιστάμενος λιγυρὰν ἀναμέλψαι ἀοιδάν,<br>ᾧ οὐ δωτίναν ἀντάξιον ὤπασε τέχνας.<br>Μουσάων δ’ ὑποφῆται ἀείδοντι Πτολεμαῖον<br>ἀντ’ εὐεργεσίας. τί δὲ κάλλιον ἀνδρί κεν εἴη<br>ὀλβίῳ ἢ κλέος ἐσθλὸν ἐν ἀνθρώποισιν ἀρέσθαι;", "st": "17"}, {"sp": "N", "t": "τοῦτο καὶ Ἀτρείδαισι μένει· τὰ δὲ μυρία τῆνα,<br>ὅσσα μέγαν Πριάμοιο δόμον κτεάτισσαν ἑλόντες,<br>ἀέρι πᾳ κέκρυπται, ὅθεν πάλιν οὐκέτι νόστος·", "st": "17"}, {"sp": "N", "t": "μοῦνος δὲ προτέρων τε καὶ ὧν ἔτι θερμὰ κονία<br>στειβομένα καθύπερθε ποδῶν ἐκμάσσεται ἴχνη,<br>ματρὶ φίλᾳ καὶ πατρὶ θυώδεας εἵσατο ναούς·<br>ἐν δ’ αὐτοὺς χρυσῷ περικαλλέας ἠδ’ ἐλέφαντι<br>ἵδρυται πάντεσσιν ἐπιχθονίοισιν ἀρωγούς.<br>πολλὰ δὲ πιανθέντα βοῶν ὅγε μηρία καίει<br>μησὶ περιπλομένοισιν ἐρευθομένων ἐπὶ βωμῶν,<br>αὐτός τ’ ἰφθίμα τ’ ἄλοχος, τᾶς οὔτις ἀρείων<br>νυμφίον ἐν μεγάροισι γυνὰ περιβάλλετ’ ἀγοστῷ,<br>ἐκ θυμοῦ στέργοισα κασίγνητόν τε πόσιν τε.<br>ὧδε καὶ ἀθανάτων ἱερὸς γάμος ἐξετελέσθη,<br>οὓς τέκετο κρείουσα Ῥέα βασιλῆας Ὀλύμπου·<br>ἓν δὲ λέχος στόρνυσιν ἰαύειν Ζηνὶ καὶ Ἥρῃ<br>χεῖρας φοιβήσασα μύροις ἔτι παρθένος Ἶρις.", "st": "17"}, {"sp": "N", "t": "χαῖρε ἄναξ Πτολεμαῖε· σέθεν δ’ ἐγὼ ἶσα καὶ ἄλλων<br>μνάσομαι ἡμιθέων, δοκέω δ’ ἔπος οὐκ ἀπόβλητον<br>φθέγξομαι ἐσσομένοις· ἀρετήν γε μὲν ἐκ Διὸς αἰτεῦ.", "st": "17"}, {"sp": "SEC", "t": "ΙΗʹ — Ἑλένης Ἐπιθάλαμιος", "st": "18"}, {"sp": "N", "t": "ἔν ποκ’ ἄρα Σπάρτᾳ ξανθότριχι πὰρ Μενελάῳ<br>παρθενικαὶ θάλλοντα κόμαις ὑάκινθον ἔχοισαι<br>πρόσθε νεογράπτω θαλάμω χορὸν ἐστάσαντο,<br>δώδεκα ταὶ πρᾶται πόλιος, μέγα χρῆμα Λακαινᾶν,<br>ἁνίκα Τυνδαριδᾶν κατεδέξατο τὰν ἀγαπητὰν<br>μναστεύσας Ἑλέναν ὁ νεώτερος Ἀτρέος υἱός.<br>ἄειδον δ’ ἄρα πᾶσαι ἐς ἓν μέλος ἐγκροτέοισαι<br>ποσσὶ περιπλέκτοις, ὑπὸ δ’ ἴαχε δῶμ’ ὑμεναίῳ.", "st": "18"}, {"sp": "N", "t": "οὕτω δὴ πρωιζὲ κατέδραθες ὦ φίλε γαμβρέ;<br>ἦ ῥά τις ἐσσὶ λίαν βαρυγούνατος; ἦ ῥα φίλυπνος;<br>ἦ ῥα πολύν τιν’ ἔπινες, ὅτ’ εἰς εὐνὰν κατεβάλλευ;<br>εὕδειν μὰν σπεύδοντα καθ’ ὥραν αὐτὸν ἐχρῆν τυ,<br>παῖδα δ’ ἐᾶν σὺν παισὶ φιλοστόργῳ παρὰ ματρὶ<br>παίσδειν ἐς βαθὺν ὄρθρον, ἐπεὶ καὶ ἔνας καὶ ἐς ἀῶ<br>κεἰς ἔτος ἐξ ἔτεος Μενέλαε τεὰ νυὸς ἅδε.", "st": "18"}, {"sp": "N", "t": "ὄλβιε γάμβρ’, ἀγαθός τις ἐπέπταρεν ἐρχομένῳ τοι<br>ἐς Σπάρταν, ἅπερ ὥλλοι ἀριστέες, ὡς ἀνύσαιο.<br>μοῦνος ἐν ἡμιθέοις Κρονίδαν Δία πενθερὸν ἑξεῖς.<br>Ζανός τοι θυγάτηρ ὑπὸ τὰν μίαν ἵκετο χλαῖναν,<br>οἵα Ἀχαιιάδων γαῖαν πατεῖ οὐδὲ μί’ ἄλλα.<br>ἦ μέγα κέν τι τέκοιτ’, εἰ ματέρι τίκτοι ὁμοῖον.", "st": "18"}, {"sp": "N", "t": "ἄμμες δ’ αἱ πᾶσαι συνομάλικες, αἷς δρόμος ωὑτός<br>χρισαμέναις ἀνδριστὶ παρ’ Εὐρώταο λοετροῖς,<br>τετράκις ἑξήκοντα κόραι, θῆλυς νεολαία,<br>τᾶν οὐδέν τις ἄμωμος, ἐπεί χ’ Ἑλένᾳ παρισωθῇ.", "st": "18"}, {"sp": "N", "t": "Ἀὼς ἀντέλλοισα καλὸν διέφανε πρόσωπον,<br>πότνια νὺξ τό τε λευκὸν ἔαρ χειμῶνος ἀνέντος·<br>ὧδε καὶ ἁ χρυσέα Ἑλένα διαφαίνετ’ ἐν ἁμῖν.<br>πιείρᾳ μέγα λᾷον ἀνέδραμε κόσμος ἀρούρᾳ<br>ἢ κάπῳ κυπάρισσος ἢ ἅρματι Θεσσαλὸς ἵππος·<br>ὧδε καὶ ἁ ῥοδόχρως Ἑλένα Λακεδαίμονι κόσμος.<br>οὔτέ τις ἐκ ταλάρω πανίσδεται ἔργα τοιαῦτα,<br>οὔτ’ ἐνὶ δαιδαλέῳ πυκινώτερον ἄτριον ἱστῷ<br>κερκίδι συμπλέξασα μακρῶν ἔταμ’ ἐκ κελεόντων.<br>οὐ μὰν οὐδὲ λύραν τις ἐπίσταται ὧδε κροτῆσαι<br>Ἄρτεμιν ἀείδοισα καὶ εὐρύστερνον Ἀθάναν,<br>ὡς Ἑλένα, τᾶς πάντες ἐπ’ ὄμμασιν ἵμεροι ἐντί.", "st": "18"}, {"sp": "N", "t": "ὦ καλὰ ὦ χαρίεσσα κόρα, τὺ μὲν οἰκέτις ἤδη,<br>ἄμμες δ’ ἐς δρόμον ἦρι καὶ ἐς λειμώνια φύλλα<br>ἑρψεῦμες στεφάνως δρεψεύμεναι ἁδὺ πνέοντας,<br>πολλὰ τεοῦς Ἑλένα μεμναμέναι ὡς γαλαθηναὶ<br>ἄρνες γειναμένας ὄιος μαστὸν ποθέοισαι.<br>πρᾶταί τοι στέφανον λωτῶ χαμαὶ αὐξομένοιο<br>πλέξασαι σκιερὰν καταθήσομεν ἐς πλατάνιστον,<br>πρᾶται δ’ ἀργυρέας ἐξ ὄλπιδος ὑγρὸν ἄλειφαρ<br>λαζύμεναι σταξεῦμες ὑπὸ σκιερὰν πλατάνιστον·<br>γράμματα δ’ ἐν φλοιῷ γεγράψεται, (ὡς παριών τις<br>ἀννείμῃ,) Δωριστί· σέβου μ’· Ἑλένας φυτὸν εἰμί.", "st": "18"}, {"sp": "N", "t": "χαίροις ὦ νύμφα, χαίροις εὐπένθερε γαμβρέ.<br>Λατὼ μὲν δοίη, Λατὼ κουροτρόφος ὔμμιν<br>εὐτεκνίαν, Κύπρις δέ, θεὰ Κύπρις ἶσον ἔρασθαι<br>ἀλλάλων, Ζεὺς δέ, Κρονίδας Ζεὺς ἄφθιτον ὄλβον,<br>ὡς ἐξ εὐπατριδᾶν εἰς εὐπατρίδας πάλιν ἔνθῃ.", "st": "18"}, {"sp": "N", "t": "εὕδετ’ ἐς ἀλλάλων στέρνον φιλότητα πνέοντες<br>καὶ πόθον, ἔγρεσθαι δὲ πρὸς ἀῶ μἠπιλάθησθε.<br>νεύμεθα κἄμμες ἐς ὄρθρον, ἐπεί κα πρᾶτος ἀοιδὸς<br>ἐξ εὐνᾶς κελαδήσῃ ἀνασχὼν εὔτριχα δειράν.", "st": "18"}, {"sp": "N", "t": "Ὑμὴν ὦ Ὑμέναιε, γάμῳ ἐπὶ τῷδε χαρείης.", "st": "18"}, {"sp": "SEC", "t": "ΙΘʹ — Κηριοκλέπτης", "st": "19"}, {"sp": "N", "t": "τὸν κλέπταν πότ’ Ἔρωτα κακὰ κέντασε μέλισσα<br>κηρίον ἐκ σίμβλων συλεύμενον, ἄκρα δὲ χειρῶν<br>δάκτυλα πάνθ’ ὑπένυξεν. ὁ δ’ ἄλγεε καὶ χέρ’ ἐφύση<br>καὶ τὰν γᾶν ἐπάταξε καὶ ἅλατο, τᾷ δ’ Ἀφροδίτᾳ<br>δεῖξεν τὰν ὀδύναν καὶ μέμφετο, ὅττί γε τυτθὸν<br>θηρίον ἐστὶ μέλισσα καὶ ἁλίκα τραύματα ποιεῖ.<br>χἁ μάτηρ γελάσασα· τί δ’; οὐκ ἴσος ἐσσὶ μελίσσαις;<br>ὡς τυτθὸς μὲν ἔφυς, τὰ δὲ τραύματα ταλίκα ποιεῖς.", "st": "19"}, {"sp": "SEC", "t": "Κʹ — Βουκολίσκος", "st": "20"}, {"sp": "N", "t": "Εὐνείκα μ’ ἐγέλαξε θέλοντά μιν ἁδὺ φιλῆσαι,<br>καί μ’ ἐπικερτομέοισα τάδ’ ἔννεπεν· “ἔρρ’ ἀπ’ ἐμεῖο.<br>βουκόλος ὢν ἐθέλεις με κύσαι τάλαν; οὐ μεμάθηκα<br>ἀγροίκως φιλέειν, ἀλλ’ ἀστικὰ χείλεα θλίβειν.<br>μή τύ γέ μευ κύσσῃς τὸ καλὸν στόμα μηδ’ ἐν ὀνείροις.<br>οἷα βλέπεις, ὁπποῖα λαλεῖς, ὡς ἄγρια παίσδεις,<br>ὡς τρυφέρ’ αἰκάλλεις, ὡς κωτίλα ῥήματα φράσδεις·<br>ὡς μαλακὸν τὸ γένειον ἔχεις, ὡς ἁδέα χαίταν.<br>χείλεά τοι νοσέοντι, χέρες δέ τοι ἐντὶ μέλαιναι,<br>καὶ κακὸν ἐξόσδεις. ἀπ’ ἐμεῦ φύγε, μή με μολύνῃς.”<br>τοιάδε μυθίζοισα τρὶς εἰς ἑὸν ἔπτυσε κόλπον,<br>καί μ’ ἀπὸ τᾶς κεφαλᾶς ποτὶ τὼ πόδε συνεχὲς εἶδε<br>χείλεσι μυχθίζοισα καὶ ὄμμασι λοξὰ βλέποισα,<br>καὶ πολὺ τᾷ μορφᾷ θηλύνετο, καί τι σεσαρὸς<br>καὶ σοβαρόν μ’ ἐγέλαξεν. ἐμοὶ δ’ ἄφαρ ἔζεσεν αἷμα,<br>καὶ χρόα φοινίχθην ὑπὸ τὤλγεος ὡς ῥόδον ἕρσᾳ.<br>χἁ μὲν ἔβα με λιποῖσα· φέρω δ’ ὑποκάρδιον ὀργάν,<br>ὅττί με τὸν χαρίεντα κακὰ μωμήσαθ’ ἑταίρα.", "st": "20"}, {"sp": "N", "t": "ποιμένες, εἴπατέ μοι τὸ κρήγυον· οὐ καλὸς ἐμμί;<br>ἆρά τις ἐξαπίνας με θεὸς βροτὸν ἄλλον ἔτευξε;<br>καὶ γὰρ ἐμοὶ τὸ πάροιθεν ἐπάνθεεν ἁδύ τι κάλλος<br>ὡς κισσὸς ποτὶ πρέμνον, ἐμὰν δ’ ἐπύκαζεν ὑπήναν,<br>χαῖται δ’ οἷα σέλινα περὶ κροτάφοισι κέχυντο,<br>καὶ λευκὸν τὸ μέτωπον ἐπ’ ὀφρύσι λάμπε μελαίναις·<br>ὄμματά μοι γλαυκᾶς χαροπώτερα πολλὸν Ἀθάνας,<br>καὶ στόμα δ’ αὖ πακτᾶς γλυκερώτερον, ἐκ στομάτων δὲ<br>ἔρρεέ μοι φωνὰ γλυκερωτέρα ἢ μέλι κηρῶ.<br>ἁδὺ δέ μοι τὸ μέλισμα, καὶ ἢν σύριγγι μελίσδω,<br>κἢν αὐλῷ δονέω, κἢν δώνακι, κἢν πλαγιαύλῳ.<br>καὶ πᾶσαι καλόν με κατ’ ὤρεα φαντὶ γυναῖκες,<br>καὶ πᾶσαί με φιλεῦντι· τὰ δ’ ἀστικά μ’ οὐκ ἐφίλασεν,<br>ἀλλ’ ὅτι βουκόλος ἐμμὶ παρέδραμε κοὔποτ’ ἀκούει,<br>ὡς ὁ καλὸς Διόνυσος ἐν ἄγκεσι πόρτιν ἔλαυνεν·<br>οὐκ ἔγνω δ’, ὅτι Κύπρις ἐπ’ ἀνέρι μήνατο βούτᾳ<br>καὶ Φρυγίοις ἐνόμευσεν ἐν ὤρεσι καὶ τὸν Ἄδωνιν<br>ἐν δρυμοῖσι φίλασε καὶ ἐν δρυμοῖσιν ἔκλαυσεν.<br>Ἐνδυμίων δὲ τίς ἦν; οὐ βουκόλος; ὅν γε Σελάνα<br>βουκολέοντα φίλασεν, ἀπ’ Οὐλύμπω δὲ μολοῖσα<br>λάθριον ἀν νάπος ἦλθε καὶ εἰς ἕνα παιδὶ κάθευδε.<br>καὶ τὺ Ῥέα κλαίεις τὸν βουκόλον. οὐχὶ δὲ καὶ τὺ", "st": "20"}, {"sp": "N", "t": "ὦ Κρονίδα διὰ παῖδα βοηνόμον ὄρνις ἐπλάγχθης;", "st": "20"}, {"sp": "N", "t": "Εὐνείκα δὲ μόνα τὸν βουκόλον οὐκ ἐφίλασεν,<br>ἁ Κυβέλας κρέσσων καὶ Κύπριδος ἠδὲ Σελάνας.", "st": "20"}, {"sp": "N", "t": "μηκέτι μηδὲ σὺ Κύπρι τὸν ἁδέα μήτε κατ’ ἄστυ<br>μήτ’ ἐν ὄρει φιλέοις, μούνη δ’ ἀνὰ νύκτα καθεύδοις.", "st": "20"}, {"sp": "SEC", "t": "ΚΑʹ — Ἁλιεῖς", "st": "21"}, {"sp": "N", "t": "Ἁ πενία Διόφαντε μόνα τὰς τέχνας ἐγείρει,<br>αὐτὰ τῶ μόχθοιο διδάσκαλος· οὐδὲ γὰρ εὕδειν<br>ἀνδράσιν ἐργατίναισι κακαὶ παρέχοντι μέριμναι.<br>κἂν ὀλίγον νυκτός τις ἐπιμύσσῃσι, τὸν ὕπνον<br>αἰφνίδιον θορυβεῦσιν ἐφιστάμεναι μελεδῶναι.", "st": "21"}, {"sp": "N", "t": "Ἰχθύος ἀγρευτῆρες ὅμως δύο κεῖντο γέροντες,<br>στρωσάμενοι βρύον αὖον ὑπὸ πλεκταῖς καλύβαισι,<br>κεκλιμένοι τοίχῳ τῷ φυλλίνῳ· ἐγγύθι δ’ αὐτοῖν<br>κεῖτο τὰ ταῖν χειροῖν ἀθλήματα, τοὶ καλαθίσκοι,<br>τοὶ κάλαμοι, τἄγκιστρα τὰ φυκιόεντα δέλητα<br>ὁρμιαὶ κύρτοι τε καὶ ἐκ σχοίνων λαβύρινθοι,<br>μήρινθοι κώπα τε γέρων τ’ ἐπ’ ἐρείσμασι λέμβος·<br>νέρθεν τᾶς κεφαλᾶς φορμὸς βραχύς, εἷμά τ’ ἐπί σφι<br>οὗτος τοῖς ἁλιεῦσιν ὁ πᾶς πόρος, οὗτος ὁ πλοῦτος.<br>οὐδεὶς δ’ αὖ σισύραν εἶχ’ οὐ λίνα· πάντα περισσά,<br>πάντ’ ἐδόκει τήνοις· ἁ γὰρ πενία σφας ἔτειρε<br>οὐδεὶς δ’ ἐν μέσσῳ γείτων· πενίᾳ δὲ παρ’ αὐτὰν<br>θλιβομέναν καλύβαν τρυφερὸν προσέναχε θάλασσα.", "st": "21"}, {"sp": "N", "t": "κοὔπω τὸν μέσατον δρόμον ἄνυεν ἅρμα Σελάνας,<br>τοὺς δ’ ἁλιεῖς ἤγειρε φίλος πόνος, ἐκ βλεφάρων δὲ<br>ὕπνον ἀπωσάμενοι σφετέραις φρεσὶν ἤρεθον αὐδάν.", "st": "21"}, {"sp": "Ἀσφαλίων", "t": "ψεύδοντ’ ὦ φίλε πάντες, ὅσοι τὰς νύκτας ἔφασκον<br>τῶ θέρεος μινύθειν, ὅτε τἄματα μακρὰ φέρει Ζεύς.<br>ἤδη μυρί’ ἐσεῖδον ὀνείρατα, κοὐδέπω ἀώς.<br>μὴ λαθόμην; τί τὸ χρῆμα; χρόνον δ’ αἱ νύκτες ἔχοντι.", "st": "21"}, {"sp": "Ἑταῖρος", "t": "Ἀσφαλίων, μέμφῃ τὸ καλὸν θέρος; οὐ γὰρ ὁ καιρὸς<br>αὐτομάτως παρέβα τὸν ἑὸν δρόμον· ἀλλὰ τὸν ὕπνον<br>ἁ φροντὶς κόπτοισα μακρὰν τὰν νύκτα ποιεῖ τοι.", "st": "21"}, {"sp": "Ἀσφαλίων", "t": "ἆρ’ ἔμαθες κρίνειν πόκ’ ἐνύπνια; χρηστὰ γὰρ εἶδον.<br>οὔ σε θέλω τὠμῶ φαντάσματος ἦμεν ἄμοιρον.<br>ὡς καὶ τὰν ἄγραν, τὠνείρατα πάντα μερίζευ.<br>ὃς γὰρ ἂν εἰκάξῃ κατὰ τὸν νόον οὗτος ἄριστος<br>ἐστὶν ὀνειροκρίτας, ὁ διδάσκαλός ἐστι παρ’ ᾧ νοῦς.<br>ἄλλως καὶ σχολά ἐστι· τί γὰρ ποιεῖν ἂν ἔχοι τις<br>κείμενος ἐν φύλλοις ποτὶ κύματι μηδὲ καθεύδων,<br>ἀλλ’ ὄνος ἐν ῥάμνῳ τό τε λύχνιον ἐν πρυτανείῳ·<br>φαντὶ γὰρ ἀγρυπνίαν τόδ’ ἔχειν.", "st": "21"}, {"sp": "Ἑταῖρος", "t": "λέγε μοί ποτε νυκτὸς<br>ὄψιν, ἐπεὶ τά τις οἶδε λέγει μανύεν ἑταίρῳ.", "st": "21"}, {"sp": "Ἀσφαλίων", "t": "δειλινὸν ὡς κατέδαρθον ἐν εἰναλίοισι πόνοισιν<br>(οὐ μὰν ἦν πολύσιτος, ἐπεὶ δειπνεῦντες ἐν ὥρᾳ,<br>εἰ μέμνῃ, τᾶς γαστρὸς ἐφειδόμεθ’), εἶδον ἐμαυτὸν<br>ἐν πέτρᾳ μεμαῶτα, καθεζόμενος δ’ ἐδόκευον<br>ἰχθύας, ἐκ καλάμων δὲ πλάνον κατέσειον ἐδωδάν.<br>καί τις τῶν τραφερῶν ὠρέξατο· καὶ γὰρ ἐν ὕπνοις<br>πᾶσα κύων ἄρκτον μαντεύεται, ἰχθύα κἠγών.<br>χὡ μὲν τὠγκίστρῳ ποτεφύετο, καὶ ῥέεν αἷμα,<br>τὸν κάλαμον δ’ ὑπὸ τῶ κινήματος ἀγκύλον εἶχον<br>τὼ χέρε τεινόμενον περικλώμενον, εὐρὺν ἀγῶνα,<br>πῶς νιν ἕλω μέγαν ἰχθὺν ἀφαυροτέροισι σιδάροις.<br>εἶθ’ ὑπομιμνάσκων τῶ τρώματος ἠρέμ’ ἔνυξα,<br>καὶ νύξας ἐχάλαξα, καὶ οὐ φεύγοντος ἔτεινα.<br>ἤνυσα δ’ ὦν τὸν ἄεθλον, ἀνείλκυσα χρύσεον ἰχθύν,<br>παντᾷ τοι χρυσῷ πεπυκασμένον· εἶχε δὲ δεῖμα,<br>μήτι Ποσειδάωνι πέλοι πεφιλημένος ἰχθὺς<br>ἢ τάχα τᾶς γλαυκᾶς κειμήλιον Ἀμφιτρίτης.<br>ἠρέμα δ’ αὐτὸν ἐγὼν ἐκ τὠγκίστρω ἀπέλυσα,<br>μή ποτε τῶ στόματος τἀγκίστρια χρυσὸν ἔχοιεν.<br>καὶ τὸν μὲν πίστευσα καλεῖν τὸν ἐπήρατον ἰχθύν,<br>ὤμοσα δ’ οὐκέτι λοιπὸν ὑπὲρ πελάγους πόδα θεῖναι,<br>ἀλλὰ μενεῖν ἐπὶ γᾶς καὶ τῷ χρυσῷ βασιλεύσειν.<br>ταῦτά με κἀξήγειρε, τὺ δ’ ὦ ξένε λοιπὸν ἔρειδε<br>τὰν γνώμαν· ὅρκον γὰρ ἐγὼ τὸν ἐπώμοσα ταρβῶ.", "st": "21"}, {"sp": "Ἑταῖρος", "t": "καὶ σύγε τί τρέσσεις; οὐκ ὤμοσας· οὐδὲ γὰρ ἰχθὺν<br>χρύσεον ὡς ἴδες εὗρες, ἴσα δ’ ἦν ψεύδεσιν ὄψις,<br>ἐλπὶς τῶν ὕπνων. ζάτει τὸν σάρκινον ἰχθύν,<br>εἰ γάρ πᾳ κνώσσων ἔτ’ ἐτώσια ταῦτα ματεύσεις,<br>μὴ σὺ θάνῃς λιμῷ καὶ τοῖς χρυσοῖσιν ὀνείροις.", "st": "21"}, {"sp": "SEC", "t": "ΚΒʹ — Διόσκουροι", "st": "22"}, {"sp": "N", "t": "Ὑμνέομεν Λήδας τε καὶ αἰγιόχου Διὸς υἱώ,<br>Κάστορα καὶ φοβερὸν Πολυδεύκεα πὺξ ἐρεθίζειν<br>χεῖρας ἐπιζεύξαντα μέσας βοέοισιν ἱμᾶσιν.<br>ὑμνέομεν καὶ δὶς καὶ τὸ τρίτον ἄρσενα τέκνα<br>κούρης Θεστιάδος, Λακεδαιμονίους δύ’ ἀδελφούς,<br>ἀνθρώπων σωτῆρας ἐπὶ ξυροῦ ἤδη ἐόντων,<br>ἵππων θ’ αἱματόεντα ταρασσομένων καθ’ ὅμιλον,<br>νηῶν θ’, αἳ δύνοντα καὶ οὐρανὸν ἐξανύοντα<br>ἄστρα βιαζόμεναι χαλεποῖς ἐνέκυρσαν ἀήταις.<br>οἱ δέ σφεων κατὰ πρύμναν ἀείραντες μέγα κῦμα,<br>ἠὲ καὶ ἐκ πρῴρηθεν, ἢ ὅππῃ θυμὸς ἑκάστου,<br>ἐς κοίλην ἔρριψαν, ἀνέρρηξαν δ’ ἄρα τοίχους<br>ἀμφοτέρους· κρέμαται δὲ σὺν ἱστίῳ ἄρμενα πάντα<br>εἰκῇ ἀποκλασθέντα· πολὺς δ’ ἐξ οὐρανοῦ ὄμβρος<br>νυκτὸς ἐφερπούσης· παταγεῖ δ’ εὐρεῖα θάλασσα,<br>κοπτομένη πνοιαῖς τε καὶ ἀρρήκτοισι χαλάζαις.", "st": "22"}, {"sp": "N", "t": "ἀλλ’ ἔμπης ὑμεῖς γε καὶ ἐκ βυθοῦ ἕλκετε νῆας<br>αὐτοῖσιν ναύτῃσιν ὀιομένοις θανέεσθαι·<br>αἶψα δ’ ἀπολήγοντ’ ἄνεμοι, λιπαρὴ δὲ γαλάνη<br>ἀμπέλαγος· νεφέλαι δὲ διέδραμον ἄλλυδις ἄλλαι·<br>ἐκ δ’ ἄρκτοι τ’ ἐφάνησαν, ὄνων τ’ ἀνὰ μέσσον ἀμαυρὴ<br>φάτνη σημαίνοισα τὰ πρὸς πλόον εὔδια πάντα.", "st": "22"}, {"sp": "N", "t": "ὦ ἄμφω θνητοῖσι βοηθόοι, ὦ φίλοι ἄμφω,<br>ἱππῆες κιθαρισταί, ἀεθλητῆρες ἀοιδοί·<br>Κάστορος ἢ πρώτου Πολυδεύκεος ἄρξομ’ ἀείδειν;<br>ἀμφοτέρους ὑμνέων Πολυδεύκεα πρῶτον ἀείσω.", "st": "22"}, {"sp": "N", "t": "Ἡ μὲν ἄρα προφυγοῦσα πέτρας εἰς ἓν ξυνιούσας<br>Ἀργὼ καὶ νιφόεντος ἀταρτηρὸν στόμα Πόντου<br>Βέβρυκας εἰσαφίκανε θεῶν φίλα τέκνα φέρουσα.<br>ἔνθα μιῆς πολλοὶ κατὰ κλίμακος ἀμφοτέρων ἒξ<br>τοίχων ἄνδρες ἔβαινον Ἰησονίης ἀπὸ νηός.<br>ἐκβάντες δ’ ἐπὶ θῖνα βαθὺν καὶ ὑπήνεμον ἀκτὴν<br>εὐνάς τ’ ἐστόρνυντο πυρεῖά τε χερσὶν ἐνώμων.", "st": "22"}, {"sp": "N", "t": "Κάστωρ δ’ αἰολόπωλος ὅ τ’ οἰνωπὸς Πολυδεύκης<br>ἄμφω ἐρημάζεσκον ἀποπλαγχθέντες ἑταίρων,<br>παντοίην ἐν ὄρει θηεύμενοι ἄγριον ὕλην.<br>εὗρον δ’ ἀέναον κρήνην ὑπὸ λισσάδι πέτρῃ<br>ὕδατι πεπληθυῖαν ἀκηράτῳ· αἱ δ’ ὑπένερθεν<br>λάλλαι κρυστάλλῳ ἠδ’ ἀργύρῳ ἰνδάλλοντο<br>ἐκ βυθοῦ· ὑψηλαὶ δὲ πεφύκεσαν ἀγχόθι πεῦκαι<br>λεῦκαί τε πλάτανοί τε καὶ ἀκρόκομοι κυπάρισσοι,<br>ἄνθεά τ’ εὐώδη, λασίαις φίλα ἔργα μελίσσαις,<br>ὅσσ’ ἔαρος λήγοντος ἐπιβρύει ἀν λειμῶνας.<br>ἔνθα δ’ ἀνὴρ ὑπέροπλος ἐνήμενος ἐνδιάασκε,<br>δεινὸς ἰδεῖν, σκληραῖσι τεθλασμένος οὔατα πυγμαῖς·<br>στήθεα δ’ ἐσφαίρωτο πελώρια καὶ πλατὺ νῶτον<br>σαρκὶ σιδηρείῃ, σφυρήλατος οἷα κολοσσός.<br>ἐν δὲ μύες στερεοῖσι βραχίοσιν ἄκρον ὑπ’ ὦμον<br>ἕστασαν ἠύτε πέτροι ὁλοίτροχοι, οὕστε κυλίνδων<br>χειμάρρους ποταμὸς μεγάλαις περιέξεσε δίναις·<br>αὐτὰρ ὑπὲρ νώτοιο καὶ αὐχένος ᾐωρεῖτο<br>ἄκρων δέρμα λέοντος ἀφημμένον ἐκ ποδεώνων.<br>τὸν πρότερος προσέειπεν ἀεθλοφόρος Πολυδεύκης.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "χαῖρε ξεῖν’, ὅτις ἐσσί. τίνες βροτοί, ὧν ὅδε χῶρος;", "st": "22"}, {"sp": "Ἄμυκος", "t": "χαίρω πῶς, ὅτε τ’ ἄνδρας ὁρῶ, τοὺς μὴ πρὶν ὄπωπα;", "st": "22"}, {"sp": "Πολυδεύκης", "t": "θάρσει. μήτ’ ἀδίκους μήτ’ ἐξ ἀδίκων φάθι λεύσσειν.", "st": "22"}, {"sp": "Ἄμυκος", "t": "θαρσέω, κοὐκ ἐκ σεῦ με διδάσκεσθαι τόδ’ ἔοικεν.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "ἄγριος εἶ, πρὸς πάντα παλίγκοτος, ἢ ὑπερόπτης;", "st": "22"}, {"sp": "Ἄμυκος", "t": "τοιόσδ’ οἷον ὁρᾷς· τῆς σῆς γε μὲν οὐκ ἐπιβαίνω.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "ἔλθοις, καὶ ξενίων γε τυχὼν πάλιν οἴκαδ’ ἱκάνοις.", "st": "22"}, {"sp": "Ἄμυκος", "t": "μήτε σύ με ξείνιζε, τά τ’ ἐξ ἐμεῦ οὐκ ἐν ἑτοίμῳ.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "δαιμόνι’, οὐδ’ ἂν τοῦδε πιεῖν ὕδατος σύγε δοίης;", "st": "22"}, {"sp": "Ἄμυκος", "t": "γνώσεαι, εἴ σευ δῖψος ἀνειμένα χείλεα τέρσει.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "ἄργυρος ἢ τίς ὁ μισθός, ἐρεῖς, ᾧ κέν σε πίθοιμεν;", "st": "22"}, {"sp": "Ἄμυκος", "t": "εἷς ἑνὶ χεῖρας ἄειρον ἐναντίος ἀνδρὶ καταστάς.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "πυγμάχος, ἢ καὶ ποσσὶ θενὼν σκέλος;", "st": "22"}, {"sp": "Ἄμυκος", "t": "…ὄμματά γ’ ὀρθὸς<br>πὺξ διατεινάμενος σφετέρης μὴ φείδεο τέχνης.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "τίς γάρ, ὅτῳ χεῖρας καὶ ἐμοὺς συνερείσω ἱμάντας;", "st": "22"}, {"sp": "Ἄμυκος", "t": "ἐγγὺς ὁρᾷς· οὐ γύννις ἐὼν κεκλήσεθ’ ὁ πύκτης.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "ἦ καὶ ἄεθλον ἑτοῖμον, ἐφ’ ᾧ δηρισόμεθ’ ἄμφω", "st": "22"}, {"sp": "Ἄμυκος", "t": "σὸς μὲν ἐγώ, σὺ δ’ ἐμὸς κεκλήσεαι, αἴκε κρατήσω.", "st": "22"}, {"sp": "Πολυδεύκης", "t": "ὀρνίθων φοινικολόφων τοιοίδε κυδοιμοί.", "st": "22"}, {"sp": "Ἄμυκος", "t": "εἴτ’ οὖν ὀρνίθεσσιν ἐοικότες εἴτε λέουσι<br>γινόμεθ’, οὐκ ἄλλῳ γε μαχεσσαίμεσθ’ ἐπ’ ἀέθλῳ.", "st": "22"}, {"sp": "N", "t": "Ἦ ῥ’ Ἄμυκος, καὶ κόχλον ἑλὼν μυκήσατο κοίλην.<br>οἱ δὲ θοῶς συνάγερθεν ὑπὸ σκιερὰς πλατανίστους<br>κόχλου φυσηθέντος ἀεὶ Βέβρυκες κομόωντες.<br>ὣς δ’ αὔτως ἥρωας ἰὼν ἐκαλέσσατο πάντας<br>Μαγνήσσης ἀπὸ νηὸς ὑπείροχος ἐν δαῒ Κάστωρ.<br>οἱ δ’ ἐπεὶ οὖν σπείρῃσιν ἐκαρτύναντο βοείαις<br>χεῖρας καὶ περὶ γυῖα μακροὺς εἵλιξαν ἱμάντας,<br>ἐς μέσσον σύναγον φόνον ἀλλήλοισι πνέοντες.<br>ἔνθα πολύς σφισι μόχθος ἐπειγομένοισιν ἐτύχθη,<br>ὁππότερος κατὰ νῶτα λάβοι φάος ἠελίοιο·<br>ἰδρείῃ μέγαν ἄνδρα παρήλυθες ὦ Πολύδευκες,<br>βάλλετο δ’ ἀκτίνεσσιν ἅπαν Ἀμύκοιο πρόσωπον.<br>αὐτὰρ ὅγ’ ἐν θυμῷ κεχολωμένος ἵετο πρόσσω,<br>χερσὶ τιτυσκόμενος. τοῦ δ’ ἄκρον τύψε γένειον<br>Τυνδαρίδης ἐπιόντος· ὀρίνθη δὲ πλέον ἢ πρίν,<br>σὺν δὲ μάχην ἐτάραξε, πολὺς δ’ ἐπέκειτο νενευκὼς<br>ἐς γαῖαν. Βέβρυκες δ’ ἐπαΰτεον, οἱ δ’ ἑτέρωθεν<br>ἥρωες κρατερὸν Πολυδεύκεα θαρσύνεσκον,<br>δειδιότες μή πώς μιν ἐπιβρίσας δαμάσειε<br>χώρῳ ἐνὶ στεινῷ Τιτυῷ ἐναλίγκιος ἀνήρ.<br>ἤτοι ὅγ’ ἔνθα καὶ ἔνθα παριστάμενος Διὸς υἱὸς<br>ἀμφοτέρῃσιν ἄμυσσεν ἀμοιβαδίς, ἔσχεθε δ’ ὁρμῆς<br>παῖδα Ποσειδάωνος ὑπερφίαλόν περ ἐόντα.<br>ἔστη δὲ πληγαῖς μεθύων, ἐκ δ’ ἔπτυσεν αἷμα<br>φοίνιον· οἱ δ’ ἅμα πάντες ἀριστῆες κελάδησαν,<br>ὡς ἴδον ἕλκεα λυγρὰ περὶ στόμα τε γναθμούς τε·<br>ὄμματα δ’ οἰδήσαντος ἀπεστείνωτο προσώπου.<br>τὸν μὲν ἄναξ ἐτάρασσεν ἐτώσια χερσὶ προδεικνὺς<br>πάντοθεν· ἀλλ’ ὅτε δή μιν ἀμηχανέοντ’ ἐνόησε,<br>μέσσης ῥινὸς ὕπερθε κατ’ ὀφρύος ἤλασε πυγμῇ,<br>πᾶν δ’ ἀπέσυρε μέτωπον ἐς ὀστέον. αὐτὰρ ὁ πληγεὶς<br>ὕπτιος ἐν φύλλοισι τεθηλόσιν ἐξετανύσθη.<br>ἔνθα μάχη δριμεῖα πάλιν γένετ’ ὀρθωθέντος·<br>ἀλλήλους δ’ ὄλεκον στερεοῖς θείνοντες ἱμᾶσιν.<br>ἀλλ’ ὁ μὲν ἐς στῆθός τε καὶ ἔξω χεῖρας ἐνώμα<br>αὐχένος ἀρχηγὸς Βεβρύκων· ὁ δ’ ἀεικέσι πληγαῖς<br>πᾶν συνέφυρε πρόσωπον ἀνίκητος Πολυδεύκης.<br>σάρκες δ’ αἱ μὲν ἱδρῶτι συνίζανον, ἐκ μεγάλου δὲ<br>αἶψ’ ὀλίγος γένετ’ ἀνδρός· ὁ δ’ αἰεὶ πάσσονα γυῖα<br>ἁπτομένου φορέεσκε πόνου καὶ χροιῇ ἀμείνων.", "st": "22"}, {"sp": "N", "t": "πῶς γὰρ δὴ Διὸς υἱὸς ἀδηφάγον ἄνδρα καθεῖλεν;<br>εἰπὲ θεά, σὺ γὰρ οἶσθα· ἐγὼ δ’ ἑτέρων ὑποφήτης<br>φθέγξομαι, ὡς ἐθέλεις σύ, καὶ ὅππως τοι φίλον αὐτῇ.", "st": "22"}, {"sp": "N", "t": "Ἤτοι ὅγε ῥέξαί τι λιλαιόμενος μέγα ἔργον<br>σκαιῇ μὲν σκαιὴν Πολυδεύκεος ἔλλαβε χεῖρα,<br>δοχμὸς ἀπὸ προβολῆς κλινθείς, ἑτέρῃ δ’ ἐπιβαίνων<br>δεξιτερῆς ἤνεγκεν ἀπὸ λαγόνος πλατὺ γυῖον.<br>καί κε τυχὼν ἔβλαψεν Ἀμυκλαίων βασιλῆα.<br>ἀλλ’ ὅγ’ ὑπεξανέδυ κεφαλῇ, στιβαρῇ δ’ ἅμα χειρὶ<br>πλῆξεν ὑπὸ σκαιὸν κρόταφον καὶ ἐπέμπεσεν ὤμῳ·<br>ἐκ δ’ ἐχύθη μέλαν αἷμα θοῶς κροτάφοιο χανόντος·<br>λαιῇ δὲ στόμα κόψε, πυκνοὶ δ’ ἀράβησαν ὀδόντες·<br>αἰεὶ δ’ ὀξυτέρῳ πιτύλῳ δηλεῖτο πρόσωπον,<br>μέχρι συνηλοίησε παρήια. πᾶς δ’ ἐπὶ γαίῃ<br>κεῖτ’ ἀλλοφρονέων, καὶ ἀνέσχεθε νεῖκος ἀπαυδῶν<br>ἀμφοτέρας ἅμα χεῖρας, ἐπεὶ θανάτου σχεδὸν ἦεν.", "st": "22"}, {"sp": "N", "t": "τὸν μὲν ἄρα κρατέων περ ἀτάσθαλον οὐδὲν ἔρεξας,<br>ὦ πύκτη Πολύδευκες· ὄμοσσε δέ τοι μέγαν ὅρκον,<br>ὃν πατέρ’ ἐκ πόντοιο Ποσειδάωνα κικλήσκων,<br>μήποτ’ ἔτι ξείνοισιν ἑκὼν ἀνιηρὸς ἔσεσθαι.", "st": "22"}, {"sp": "N", "t": "καὶ σὺ μὲν ὕμνησαί μοι ἄναξ. σὲ δὲ Κάστορ ἀείσω,<br>Τυνδαρίδη ταχύπωλε δορυσσόε χαλκεοθώρηξ.", "st": "22"}, {"sp": "N", "t": "τὼ μὲν ἀναρπάξαντε δύω φερέτην Διὸς υἱὼ<br>δοιὰς Λευκίπποιο κόρας· δοιὼ δ’ ἄρα τώγε<br>ἐσσυμένως ἐδίωκον ἀδελφεὼ υἷ’ Ἀφαρῆος,<br>γαμβρὼ μελλογάμω, Λυγκεὺς καὶ ὁ καρτερὸς Ἴδας.<br>ἀλλ’ ὅτε τύμβον ἵκανον ἀποφθιμένου Ἀφαρῆος,<br>ἐκ δίφρων ἅμα πάντες ἐπ’ ἀλλήλοισιν ὄρουσαν,<br>ἔγχεσι καὶ κοίλοισι βαρυνόμενοι σακέεσσι.<br>Λυγκεὺς δ’ αὖ μετέειπεν ὑπὲκ κόρυθος μέγ’ ἀύσας·", "st": "22"}, {"sp": "N", "t": "δαιμόνιοι, τί μάχης ἱμείρετε; πῶς δ’ ἐπὶ νύμφαις<br>ἀλλοτρίαις χαλεποί, γυμναὶ δ’ ἐν χερσὶ μάχαιραι;<br>ἡμῖν τοι Λεύκιππος ἑὰς ἕδνωσε θύγατρας<br>τάσδε πολὺ προτέροις, ἡμῖν γάμος οὗτος ἐν ὅρκῳ·<br>ὑμεῖς δ’ οὐ κατὰ κόσμον ἐπ’ ἀλλοτρίοις λεχέεσσιν<br>βουσὶ καὶ ἡμιόνοισι καὶ ἄλλοισι κτεάτεσσιν<br>ἄνδρα παρετρέψασθε, γάμον δ’ ἐκλέπτετε δώροις.<br>ἦ μὰν πολλάκις ὔμμιν ἐνώπιον ἀμφοτέροισιν<br>αὐτὸς ἐγὼ τάδ’ ἔειπα καὶ οὐ πολύμυθος ἐών περ·<br>“οὐχ οὕτω φίλοι ἄνδρες ἀριστήεσσιν ἔοικε<br>μνηστεύειν ἀλόχους, αἷς νυμφίοι ἤδη ἑτοῖμοι.<br>πολλή τοι Σπάρτη, πολλὴ δ’ ἱππήλατος Ἦλις,<br>Ἀρκαδίη τ’ εὔμηλος Ἀχαιῶν τε πτολίεθρα,<br>Μεσσήνη τε καὶ Ἄργος ἅπασά τε Σισυφὶς ἀκτή·<br>ἔνθα κόραι τοκέεσσιν ὑπὸ σφετέροισι τρέφονται<br>μυρίαι οὔτε φυῆς ἐπιδευέες οὔτε νόοιο.<br>τάων εὐμαρὲς ὔμμιν ὀπυίειν ἅς κ’ ἐθέλητε·<br>ὡς ἀγαθοῖς πολέες βούλοιντό κε πενθεροὶ εἶναι·<br>ὑμεῖς δ’ ἐν πάντεσσι διάκριτοι ἡρώεσσι,<br>καὶ πατέρες καὶ ἄνωθεν ἅπαν πατρώιον αἷμα.<br>ἀλλὰ φίλοι τοῦτον μὲν ἐάσατε πρὸς τέλος ἐλθεῖν<br>ἄμμι γάμον· σφῷν δ’ ἄλλον ἐπιφραζώμεθα πάντες.”", "st": "22"}, {"sp": "N", "t": "ἴσκον τοιάδε πολλά, τὰ δ’ εἰς ὑγρὸν ᾤχετο κῦμα<br>πνοιὴ ἔχουσ’ ἀνέμοιο, χάρις δ’ οὐχ ἕσπετο μύθοις.<br>σφὼ γὰρ ἀκηλήτω καὶ ἀπηνέες. ἀλλ’ ἔτι καὶ νῦν<br>πείθεσθ’· ἄμφω δ’ ἄμμιν ἀνεψιὼ ἐκ πατρὸς ἐστόν.<br>εἰ δ’ ὑμῖν κραδίη πόλεμον ποθεῖ, αἵματι δὲ χρὴ<br>νεῖκος ἀναρρήξαντας ὁμοίιον ἔγχεα λοῦσαι,<br>Ἴδας μὲν καὶ ὅμαιμος ἐμός, κρατερὸς Πολυδεύκης,<br>χεῖρας ἐρωήσουσιν ἀπεχθομένης ὑσμίνης,<br>νῶι δ’, ἐγὼ Κάστωρ τε, διακρινώμεθ’ ἄρηι<br>ὁπλοτέρω γεγαῶτε. γονεῦσι δὲ μὴ πολὺ πένθος<br>ἡμετέροισι λίπωμεν. ἅλις νέκυς ἐξ ἑνὸς οἴκου<br>εἷς· ἀτὰρ ὥλλοι πάντες ἐυφρανέουσιν ἑταίρους<br>νυμφίοι ἀντὶ νεκρῶν, ὑμεναιώσουσι δὲ κούρας<br>τάσδ’· ὀλίγῳ τοι ἔοικε κακῷ μέγα νεῖκος ἀναιρεῖν.", "st": "22"}, {"sp": "N", "t": "εἶπε, τὰ δ’ οὐκ ἄρ’ ἔμελλε θεὸς μεταμώνια θήσειν.<br>τὼ μὲν γὰρ ποτὶ γαῖαν ἀπ’ ὤμων τεύχε’ ἔθεντο,<br>ὣ γενεῇ προφέρεσκον· ὁ δ’ ἐς μέσον ἤλυθε Λυγκεύς,<br>σείων καρτερὸν ἔγχος ὑπ’ ἀσπίδος ἄντυγα πρώτην·<br>ὣς δ’ αὔτως ἄκρας ἐτινάξατο δούρατος ἀκμὰς<br>Κάστωρ· ἀμφοτέροις δὲ λόφων ἐπένευον ἔθειραι.<br>ἔγχεσι μὲν πρώτιστα τιτυσκόμενοι πόνον εἶχον<br>ἀλλήλων, εἴ πού τι χροὸς γυμνωθὲν ἴδοιεν.<br>ἀλλ’ ἤτοι τὰ μὲν ἄκρα πάρος τινὰ δηλήσασθαι<br>δοῦρ’ ἐάγη, σακέεσσιν ἐνὶ δεινοῖσι παγέντα.<br>τὼ δ’ ἄορ ἐκ κολεοῖο ἐρυσσαμένω φόνον αὖτις<br>τεῦχον ἐπ’ ἀλλήλοισι· μάχης δ’ οὐ γίνετ’ ἐρωή.<br>πολλὰ μὲν ἐς σάκος εὐρὺ καὶ ἱππόκομον τρυφάλειαν<br>Κάστωρ, πολλὰ δ’ ἔνυξεν ἀκριβὴς ὄμμασι Λυγκεὺς<br>τοῖο σάκος, φοίνικα δ’ ὅσον λόφον ἵκετ’ ἀκωκή.<br>τοῦ μὲν ἄκρην ἐκόλουσεν ἐπὶ σκαιὸν γόνυ χεῖρα<br>φάσγανον ὀξὺ φέροντος ὑπεξαναβὰς ποδὶ Κάστωρ<br>σκαιῷ· ὁ δὲ πληγεὶς ξίφος ἔκβαλεν, αἶψα δὲ φεύγειν<br>ὡρμήθη ποτὶ σῆμα πατρός, τόθι καρτερὸς Ἴδας<br>κεκλιμένος θηεῖτο μάχην ἐμφύλιον ἀνδρῶν.<br>ἀλλὰ μεταΐξας πλατὺ φάσγανον ὦσε διαπρὸ<br>Τυνδαρίδης λαγόνος τε καὶ ὀμφαλοῦ· ἔγκατα δ’ εἴσω<br>χαλκὸς ἄφαρ διέχευεν· ὁ δ’ ἐς στόμα κεῖτο νενευκὼς<br>Λυγκεύς, κὰδ δ’ ἄρα οἱ βλεφάρων βαρὺς ἔδραμεν ὕπνος.", "st": "22"}, {"sp": "N", "t": "οὐ μὰν οὐδὲ τὸν ἄλλον ἐφ’ ἑστίῃ εἶδε πατρῴῃ<br>παίδων Λαοκόωσσα φίλον γάμον ἐκτελέσαντα.<br>ἦ γὰρ ὅγε στήλην Ἀφαρηίου ἐξανέχουσαν<br>τύμβου ἀναρρήξας ταχέως Μεσσήνιος Ἴδας<br>μέλλε κασιγνήτοιο βαλεῖν σφετέροιο φονῆα·<br>ἀλλὰ Ζεὺς ἐπάμυνε, χερῶν δέ οἱ ἔκβαλε τυκτὴν<br>μάρμαρον, αὐτὸν δὲ φλογέῳ συνέφλεξε κεραυνῷ.", "st": "22"}, {"sp": "N", "t": "οὕτως Τυνδαρίδαις πολεμιζέμεν οὐκ ἐν ἐλαφρῷ.<br>αὐτοί τε κρατέοντε καὶ ἐκ κρατέοντος ἔφυσαν.", "st": "22"}, {"sp": "N", "t": "χαίρετε Λήδας τέκνα, καὶ ἡμετέροις κλέος ὕμνοις<br>ἐσθλὸν ἀεὶ πέμποιτε· φίλοι δέ τε πάντες ἀοιδοὶ<br>Τυνδαρίδαις Ἑλένῃ τε καὶ ἄλλοις ἡρώεσσιν,<br>Ἴλιον οἳ διέπερσαν ἀρήγοντες Μενελάῳ.", "st": "22"}, {"sp": "N", "t": "ὑμῖν κῦδος ἄνακτες ἐμήσατο Χῖος ἀοιδός,<br>ὑμνήσας Πριάμοιο πόλιν καὶ νῆας Ἀχαιῶν<br>Ἰλιάδας τε μάχας Ἀχιλῆά τε πύργον ἀυτῆς·<br>ὑμῖν αὖ καὶ ἐγὼ λιγεῶν μειλίγματα Μουσέων,<br>οἷ’ αὐταὶ παρέχουσι καὶ ὡς ἐμὸς οἶκος ὑπάρχει,<br>τοῖα φέρω. γεράων δὲ θεοῖς κάλλιστον ἀοιδαί.", "st": "22"}, {"sp": "SEC", "t": "ΚΓʹ — Ἐραστής", "st": "23"}, {"sp": "N", "t": "Ἀνήρ τις πολύφιλτρος ἀπηνέος ἤρατ’ ἐφάβω,<br>τὰν μορφὰν ἀγαθῶ, τὸν δὲ τρόπον οὐκέθ’ ὁμοίω.<br>μίσει τὸν φιλέοντα καὶ οὐδὲ ἓν ἅμερον εἶχε,<br>κοὐκ ᾔδει τὸν Ἔρωτα, τίς ἦν θεός, ἡλίκα τόξα<br>χερσὶ κρατεῖ, πῶς πικρὰ βέλη ποτικάρδια βάλλει·<br>πάντα δὲ κἠν μύθοισι καὶ ἐν προσόδοισιν ἀτειρής.<br>οὐδέ τι τῶν πυρσῶν παραμύθιον, οὐκ ἀμάρυγμα<br>χείλεος, οὐκ ὄσσων λιπαρὸν σέλας, οὐ ῥόδα μάλων,<br>οὐ λόγος, οὐχὶ φίλαμα, τὸ κουφίζει τὸν ἔρωτα.<br>οἷα δὲ θὴρ ὑλαῖος ὑποπτεύῃσι κυναγώς,<br>οὕτως πάντ’ ἐποίει ποτὶ τὸν φίλον· ἄγρια δ’ αὐτῷ<br>χείλεα καὶ κῶραι δεινὸν βλέπος· εἶχε γὰρ ὄγκον·<br>τᾷ δὲ χολᾷ τὸ πρόσωπον ἀμείβετο, φεῦγε δ’ ἀπὸ χρὼς<br>ὕβριν τᾶς ὀργᾶς περικείμενος. ἀλλὰ καὶ οὕτως<br>ἦν καλός· ἐξ ὀργᾶς ἐρεθίζετο μᾶλλον ἐραστάς.<br>λοίσθιον οὐκ ἤνεικε τόσαν φλόγα τᾶς Κυθερείας,<br>ἀλλ’ ἐλθὼν ἔκλαιε ποτὶ στυγνοῖσι μελάθροις,<br>καὶ κύσε τὰν φλιάν, οὕτω δ’ ἀνενείκατο φωνάν·", "st": "23"}, {"sp": "N", "t": "“Ἄγριε παῖ καὶ στυγνέ, κακᾶς ἀνάθρεμμα λεαίνας,<br>λάινε παῖ καὶ ἔρωτος ἀνάξιε, δῶρά τοι ἦλθον<br>λοίσθια ταῦτα φέρων, τὸν ἐμὸν βρόχον· οὐκέτι πὰρ σὲ<br>κῶρ’ ἐθέλω λύπης κεχολωμένος, ἀλλὰ βαδίζω,<br>ἔνθα τύ μευ κατέκρινας, ὅπῃ λόγος ἦμεν ἀταρπὸν<br>ξυνάν, τοῖσιν ἐρῶσι τὸ φάρμακον ἔνθα τὸ λᾶθος.<br>ἀλλὰ καὶ ἢν ὅλον αὐτὸ λαβὼν ποτὶ χεῖλος ἀμέλξω,<br>οὐδ’ οὕτως σβέσσω τὸν ἐμὸν χόλον. ἄρτι δὲ χαίρειν<br>τοῖσι τεοῖς προθύροις ἐπιτέλλομαι. οἶδα τὸ μέλλον.", "st": "23"}, {"sp": "N", "t": "καὶ τὸ ῥόδον καλόν ἐστι, καὶ ὁ χρόνος αὐτὸ μαραίνει·<br>καὶ τὸ ἴον καλόν ἐστιν ἐν εἴαρι, καὶ ταχὺ γηρᾷ·<br>λευκὸν τὸ κρίνον ἐστί, μαραίνεται ἁνίκα πίπτῃ·<br>ἁ δὲ χιὼν λευκά, καὶ τάκεται ἁνίκα πασθῇ.<br>καὶ κάλλος καλόν ἐστι τὸ παιδικόν, ἀλλ’ ὀλίγον ζῇ.", "st": "23"}, {"sp": "N", "t": "ἥξει καιρὸς ἐκεῖνος, ὁπανίκα καὶ τὺ φιλάσεις,<br>ἁνίκα τὰν κραδίαν ὀπτεύμενος ἁλμυρὰ κλαύσῃ.", "st": "23"}, {"sp": "N", "t": "ἀλλὰ τὺ παῖ καὶ τοῦτο πανύστατον ἁδύ τι ῥέξον·<br>ὁππόταν ἐξενθὼν ἠρτημένον ἐν προθύροισι<br>τοῖσι τεοῖσιν ἴδῃς τὸν τλάμονα, μή με παρένθῃς,<br>στᾶθι δὲ καὶ βραχὺ κλαῦσον, ἐπισπείσας δὲ τὸ δάκρυ<br>λῦσον τῶ σχοίνω με καὶ ἀμφίθες ἐκ ῥεθέων σῶν<br>εἵματα καὶ κρύψόν με, τὸ δ’ αὖ πύματόν με φίλασον,<br>κἂν νεκρῷ χάρισαι τὰ σὰ χείλεα. μή με φοβαθῇς·", "st": "23"}, {"sp": "N", "t": "οὐ δύναμαι λυπεῖν σε, διαλλάξεις με φιλάσας.<br>χῶμα δέ μοι χῶσόν τι ὅ μευ κρύψει τὸν ἔρωτα.<br>κἂν ἀπίῃς, τόδε μοι τρὶς ἐπαίασον· ὦ φίλε κεῖσαι.", "st": "23"}, {"sp": "N", "t": "ἢν δὲ θέλῃς, καὶ τοῦτο· καλὸς δέ μοι ὤλεθ’ ἑταῖρος.", "st": "23"}, {"sp": "N", "t": "γράψον καὶ τόδε γράμμα, τὸ σοῖς τοίχοισι χαράξω·<br>‘τοῦτον ἔρως ἔκτεινεν. ὁδοιπόρε, μὴ παροδεύσῃς,<br>ἀλλὰ στὰς τόδε λέξον· ἀπηνέα εἶχεν ἑταῖρον.’”", "st": "23"}, {"sp": "N", "t": "Ὧδ’ εἰπὼν λίθον εἷλκεν, ἐρεισάμενος δ’ ἐπὶ τοίχω<br>ἄχρι μέσων οὐδῶν φοβερὸν λίθον ἅπτετ’ ἀπ’ αὐτῶν,<br>τὰν λεπτὰν σχοινῖδα, βρόχον δ’ ἐνέβαλλε τραχήλῳ,<br>τὰν ἕδραν δ’ ἐκύλισεν ὑπὲκ ποδός, ἠδ’ ἐκρεμάσθη", "st": "23"}, {"sp": "N", "t": "νεκρός. ὁ δ’ αὖτ’ ὤιξε θύρας καὶ τὸν νεκρὸν εἶδεν<br>αὐλᾶς ἐξ ἰδίας ἠρτημένον, οὐδ’ ἐλυγίχθη<br>τὰν ψυχάν, οὐ κλαῦσε νέον φόνον, ἀλλ’ ἐπὶ νεκρῷ<br>εἵματα πάντ’ ἐμίανεν, ἐφαβικὰ βαῖνε δ’ ἐς ἄθλα<br>γυμναστῶν, καὶ τῆλε φίλων ἐπεμαίετο λουτρῶν,<br>καὶ ποτὶ τὸν θεὸν ἦλθε, τὸν ὕβρισε· λαϊνέας δὲ<br>ἵστατ’ ἀπὸ κρηπῖδος ἐς ὕδατα· τῷ δ’ ἐφύπερθεν<br>ἅλατο καὶ τὤγαλμα, κακὸν δ’ ἔκτεινεν ἔφαβον·<br>νᾶμα δ’ ἐφοινίχθη· παιδὸς δ’ ἐπενάχετο σῶμα.", "st": "23"}, {"sp": "N", "t": "χαίρετε τοὶ φιλέοντες· ὁ γὰρ μισῶν ἐφονεύθη.<br>στέργετε δ’ οἱ μισεῦντες· ὁ γὰρ θεὸς οἶδε δικάζειν.", "st": "23"}, {"sp": "SEC", "t": "ΚΔʹ — Ἡρακλίσκος", "st": "24"}, {"sp": "N", "t": "Ἡρακλέα δεκάμηνον ἐόντα πόχ’ ἁ Μιδεᾶτις<br>Ἀλκμήνα καὶ νυκτὶ νεώτερον Ἰφικλῆα,<br>ἀμφοτέρους λούσασα καὶ ἐμπλήσασα γάλακτος,<br>χαλκείαν κατέθηκεν ἐς ἀσπίδα, τὰν Πτερελάου<br>Ἀμφιτρύων καλὸν ὅπλον ἀπεσκύλευσε πεσόντος.<br>ἁπτομένα δὲ γυνὰ κεφαλᾶς μυθήσατο παίδων·", "st": "24"}, {"sp": "N", "t": "“εὕδετ’ ἐμὰ βρέφεα γλυκερὸν καὶ ἐγέρσιμον ὕπνον,<br>εὕδετ’ ἐμὰ ψυχά, δύ’ ἀδελφεώ, εὔσοα τέκνα·<br>ὄλβιοι εὐνάζοισθε καὶ ὄλβιοι ἀῶ ἵκοισθε.”", "st": "24"}, {"sp": "N", "t": "Ὣς φαμένα δίνασε σάκος μέγα· τοὺς δ’ ἔλαβ’ ὕπνος.", "st": "24"}, {"sp": "N", "t": "ἆμος δὲ στρέφεται μεσονύκτιον ἐς δύσιν ἄρκτος<br>Ὠρίωνα κατ’ αὐτόν, ὁ δ’ ἀμφαίνει μέγαν ὦμον,<br>τᾶμος ἄρ’ αἰνὰ πέλωρα δύω πολυμήχανος Ἥρη<br>κυανέαις φρίσσοντας ὑπὸ σπείραισι δράκοντας<br>ὦρσεν ἐπὶ πλατὺν οὐδόν, ὅθι σταθμὰ κοῖλα θυράων<br>εἶκεν, ἀπειλήσασα φαγεῖν βρέφος Ἡρακλῆα.<br>τὼ δ’ ἐξειληθέντες ἐπὶ χθονὶ γαστέρας ἄμφω<br>αἱμοβόρους ἐκύλιον· ἀπ’ ὀφθαλμῶν δὲ κακὸν πῦρ<br>ἐρχομένοις λάμπεσκε, βαρὺν δ’ ἐξέπτυον ἰόν.<br>ἀλλ’ ὅτε δὴ παίδων λιχμώμενοι ἐγγύθεν ἦνθον,<br>καὶ τότ’ ἄρ’ ἐξέγροντο, Διὸς νοέοντος ἅπαντα,<br>Ἀλκμήνας φίλα τέκνα, φάος δ’ ἀνὰ οἶκον ἐτύχθη.<br>ἤτοι ὅγ’ εὐθὺς ἄυσεν, ὅπως κακὰ θηρί’ ἀνέγνω<br>κοίλου ὑπὲρ σάκεος καὶ ἀναιδέας εἶδεν ὀδόντας,<br>Ἰφικλέης, οὔλαν δὲ ποσὶν διελάκτισε χλαῖναν,<br>φευγέμεν ὁρμαίνων· ὁ δ’ ἐναντίος εἴχετο χερσὶν<br>Ἡρακλέης, ἄμφω δὲ βαρεῖ ἐνεδήσατο δεσμῷ,<br>δραξάμενος φάρυγος, τόθι φάρμακα λυγρὰ κέκρυπται<br>οὐλομένοις ὀφίεσσιν, ἃ καὶ θεοὶ ἐχθαίροντι.<br>τὼ δ’ αὖτε σπείραισιν ἑλισσέσθην περὶ παῖδα<br>ὀψίγονον γαλαθηνόν, ὑπὸ τροφῷ αἰὲν ἄδακρυν·<br>ἂψ δὲ πάλιν διέλυον ἐπεὶ μογέοιεν ἀκάνθας,<br>δεσμοῦ ἀναγκαίου πειρώμενοι ἔκλυσιν εὑρεῖν.", "st": "24"}, {"sp": "N", "t": "Ἀλκμήνα δ’ ἐσάκουσε βοᾶς καὶ ἐπέγρετο πράτα·", "st": "24"}, {"sp": "N", "t": "“Ἄνσταθ’ Ἀμφιτρύων· ἐμὲ γὰρ δέος ἴσχει ὀκνηρόν·<br>ἄνστα, μηδὲ πόδεσσιν ἑοῖς ὑπὸ σάνδαλα θείῃς.<br>οὐκ ἀίεις, παίδων ὁ νεώτερος ὅσσον ἀυτεῖ;<br>ἢ οὐ νοέεις, ὅτι νυκτὸς ἀωρί που, οἱ δέ τε τοῖχοι<br>πάντες ἀριφραδέες, καθαρᾶς ἅπερ ἠριγενείας;<br>ἔστί τί μοι κατὰ δῶμα νεώτερον, ἔστι φίλ’ ἀνδρῶν.”", "st": "24"}, {"sp": "N", "t": "Ὣς φάθ’. ὁ δ’ ἐξ εὐνᾶς ἀλόχῳ κατέβαινε πιθήσας·<br>δαιδάλεον δ’ ὥρμασε μετὰ ξίφος, ὅ οἱ ὕπερθεν<br>κλιντῆρος κεδρίνου περὶ πασσάλῳ αἰὲν ἄωρτο.<br>ἤτοι ὅγ’ ὠριγνᾶτο νεοκλώστου τελαμῶνος,<br>κουφίζων ἑτέρᾳ κολεὸν μέγα, λώτινον ἔργον.<br>ἀμφιλαφὴς δ’ ἄρα παστὰς ἐνεπλήσθη πάλιν ὄρφνας·<br>δμῶας δὴ τότ’ ἄυσεν ὕπνον βαρὺν ἐκφυσῶντας·", "st": "24"}, {"sp": "N", "t": "“οἴσετε πῦρ ὅτι θᾶσσον ἀπ’ ἐσχαρεῶνος ἑλόντες,<br>δμῶες ἐμοί, στιβαροὺς δὲ θυρᾶν ἀνακόψατ’ ὀχῆας.”<br>“ἄνστατε δμῶες ταλασίφρονες. αὐτὸς ἀυτεῖ.”", "st": "24"}, {"sp": "N", "t": "Ἦ ῥα γυνὰ Φοίνισσα μύλαις ἔπι κοῖτον ἔχουσα.<br>οἱ δ’ αἶψα προγένοντο λύχνοις ἅμα δαιομένοισι<br>δμῶες· ἐνεπλήσθη δὲ δόμος σπεύδοντος ἑκάστου.<br>ἤτοι ἄρ’ ὡς εἴδοντ’ ἐπιτίτθιον Ἡρακλῆα<br>θῆρε δύω χείρεσσιν ἀπρὶξ ἁπαλαῖσιν ἔχοντα,<br>συμπλήγδην ἰάχησαν· ὁ δ’ ἐς πατέρ’ Ἀμφιτρύωνα<br>ἑρπετὰ δεικανάασκεν, ἐπάλλετο δ’ ὑψόθι χαίρων<br>κουροσύνᾳ, γελάσας δὲ πάρος κατέθηκε ποδοῖιν<br>πατρὸς ἑοῦ θανάτῳ κεκαρωμένα δεινὰ πέλωρα.<br>Ἀλκμήνα μὲν ἔπειτα ποτὶ σφέτερον βάλε κόλπον<br>ξηρὸν ὑπαὶ δείους ἀκρόχλοον Ἰφικλῆα·<br>Ἀμφιτρύων δὲ τὸν ἄλλον ὑπ’ ἀμνείαν θέτο χλαῖναν<br>παῖδα, πάλιν δ’ ἐς λέκτρον ἰὼν ἐμνάσατο κοίτου.", "st": "24"}, {"sp": "N", "t": "ὄρνιθες τρίτον ἄρτι τὸν ἔσχατον ὄρθρον ἄειδον·<br>Τειρεσίαν τόκα μάντιν ἀλαθέα πάντα λέγοντα<br>Ἀλκμήνα καλέσασα τέρας κατέλεξε νεοχμόν,<br>καί νιν ὑποκρίνεσθαι, ὅπως τελέεσθαι ἔμελλεν,", "st": "24"}, {"sp": "N", "t": "ἠνώγει. “μηδ’ εἴ τι θεοὶ νοέοντι πονηρόν,<br>αἰδόμενος σύ με κρύπτε· καὶ ὣς οὐκ ἔστιν ἀλύξαι<br>ἀνθρώποις ὅ τι Μοῖρα κατὰ κλωστῆρος ἐπείγει.<br>ἀλλ’ Εὐηρείδα μάλα σε φρονέοντα διδάσκω.”", "st": "24"}, {"sp": "N", "t": "τόσσ’ ἔλεγεν βασίλεια· ὁ δ’ ἀνταμείβετο τοίως·", "st": "24"}, {"sp": "N", "t": "“θάρσει ἀριστοτόκεια γύναι, Περσήιον αἷμα.<br>θάρσει· μελλόντων δὲ τὸ λώιον ἐν φρεσὶ θέσθαι.<br>ναὶ γὰρ ἐμὸν γλυκὺ φέγγος ἀποιχόμενον πάλαι ὄσσων,<br>πολλαὶ Ἀχαιιάδων μαλακὸν περὶ γούνατι νῆμα<br>χειρὶ κατατρίψοντι ἀκρέσπερον ἀείδοισαι<br>Ἀλκμήναν ὀνομαστί, σέβας δ’ ἔσῃ Ἀργείαισι.<br>τοῖος ἀνὴρ ὅδε μέλλει ἐς οὐρανὸν ἄστρα φέροντα<br>ἀμβαίνειν τεὸς υἱός, ἀπὸ στέρνων πλατὺς ἥρως,<br>οὗ καὶ θηρία πάντα καὶ ἀνέρες ἥσσονες ἄλλοι.<br>δώδεκά οἱ τελέσαντι πεπρωμένον ἐν Διὸς οἰκεῖν<br>μόχθους, θνητὰ δὲ πάντα πυρὰ Τραχίνιος ἑξεῖ.", "st": "24"}, {"sp": "N", "t": "γαμβρὸς δ’ ἀθανάτων κεκλήσεται, οἳ τάδ’ ἐπῶρσαν<br>κνώδαλα φωλεύοντα βρέφος διαδηλήσασθαι.<br>ἔσται δὴ τοῦτ’ ἆμαρ, ὁπηνίκα νεβρὸν ἐν εὐνᾷ<br>καρχαρόδων σίνεσθαι ἰδὼν λύκος οὐκ ἐθελήσει.", "st": "24"}, {"sp": "N", "t": "ἀλλὰ γύναι πῦρ μέν τοι ὑπὸ σποδῷ εὔτυκον ἔστω,<br>κάγκανα δ’ ἀσπαλάθου ξύλ’ ἑτοιμάσατ’ ἢ παλιούρου<br>ἢ βάτου ἢ ἀνέμῳ δεδονημένον αὖον ἄχερδον·<br>καῖε δὲ τώδ’ ἀγρίαισιν ἐπὶ σχίζαισι δράκοντε<br>νυκτὶ μέσᾳ, ὅκα παῖδα κανεῖν τεὸν ἤθελον αὐτοί.<br>ἦρι δὲ συλλέξασα κόνιν πυρὸς ἀμφιπόλων τις<br>ῥιψάτω εὖ μάλα πᾶσαν ὑπὲρ ποταμοῖο φέρουσα<br>ῥωγάδας ἐς πέτρας ὑπερούριον, ἂψ δὲ νέεσθαι<br>ἄστρεπτος· καθαρῷ δὲ πυρώσατε δῶμα θεείῳ<br>πρᾶτον, ἔπειτα δ’ ἅλεσσι μεμιγμένον, ὡς νενόμισται,<br>θαλλῷ ἐπιρραίνειν ἐστεμμένῳ ἀβλαβὲς ὕδωρ·<br>Ζηνὶ δ’ ἐπιρρέξαι καθυπερτέρῳ ἄρσενα χοῖρον,<br>δυσμενέων αἰεὶ καθυπέρτεροι ὡς τελέθοιτε.”", "st": "24"}, {"sp": "N", "t": "φᾶ, καὶ ἐρωήσας ἐλεφάντινον ᾤχετο δίφρον<br>Τειρεσίας πολλοῖσι βαρύς περ ἐὼν ἐνιαυτοῖς.", "st": "24"}, {"sp": "N", "t": "Ἡρακλέης δ’ ὑπὸ ματρὶ νέον φυτὸν ὣς ἐν ἀλωᾷ<br>ἐτρέφετ’ Ἀργείου κεκλημένος Ἀμφιτρύωνος.<br>γράμματα μὲν τὸν παῖδα γέρων Λίνος ἐξεδίδαξεν,<br>υἱὸς Ἀπόλλωνος μελεδωνεὺς ἄγρυπνος ἥρως,<br>τόξον δ’ ἐντανύσαι καὶ ἐπίσκοπον εἶναι ὀϊστῶν<br>Εὔρυτος ἐκ πατέρων μεγάλαις ἀφνειὸς ἀρούραις.<br>αὐτὰρ ἀοιδὸν ἔθηκε καὶ ἄμφω χεῖρας ἔπλασσε<br>πυξίνᾳ ἐν φόρμιγγι Φιλαμμονίδας εὔμολπος.<br>ὅσσα δ’ ἀπὸ σκελέων ἑδροστρόφοι Ἀργόθεν ἄνδρες<br>ἀλλάλους σφάλλοντι παλαίσμασιν, ὅσσά τε πύκται<br>δεινοὶ ἐν ἱμάντεσσιν, ἅ τ’ ἐς γαῖαν προπεσόντες<br>πάμμαχοι ἐξεύροντο σοφίσματα σύμφορα τέχνᾳ,<br>πάντ’ ἔμαθ’ Ἑρμείαο διδασκόμενος παρὰ παιδὶ<br>Ἁρπαλύκῳ Φανοτῆι, τὸν οὐδ’ ἂν τηλόθι λεύσσων<br>θαρσαλέως τις ἔμεινεν ἀεθλεύοντ’ ἐν ἀγῶνι·<br>τοῖον ἐπισκύνιον βλοσυρῷ ἐπέκειτο προσώπῳ.<br>ἵππους δ’ ἐξελάσασθαι ὑφ’ ἅρματι, καὶ περὶ νύσσαν<br>ἀσφαλέως κάμπτοντα τροχῷ σύριγγα φυλάξαι,<br>Ἀμφιτρύων ὃν παῖδα φίλα φρονέων ἐδίδαξεν<br>αὐτός, ἐπεὶ μάλα πολλὰ θοῶν ἐξήρατ’ ἀγώνων<br>Ἄργει ἐν ἱπποβότῳ κειμήλια, καί οἱ ἀαγεῖς<br>δίφροι, ἐφ’ ὧν ἐπέβαινε, χρόνῳ διέλυσαν ἱμάντας.", "st": "24"}, {"sp": "N", "t": "δούρατι δὲ προβολαίῳ ὑπ’ ἀσπίδι ὦμον ἔχοντα<br>ἀνδρὸς ὀρέξασθαι ξιφέων τ’ ἀνέχεσθαι ἀμυχμόν,<br>κοσμῆσαί τε φάλαγγα λόχον τ’ ἀναμετρήσασθαι<br>δυσμενέων ἐπιόντα καὶ ἱππήεσσι κελεῦσαι<br>Κάστωρ Ἱππαλίδας δέδαεν, φυγὰς Ἄργεος ἐνθών,<br>ὁππόκα κλᾶρον ἅπαντα καὶ οἰνόπεδον μέγα Τυδεὺς<br>ναῖε παρ’ Ἀδρήστοιο λαβὼν ἱππήλατον Ἄργος.<br>Κάστορι δ’ οὔτις ὁμοῖος ἐν ἡμιθέοις πολεμιστὴς<br>ἄλλος ἔην πρὶν γῆρας ἀποτρῖψαι νεότητα.", "st": "24"}, {"sp": "N", "t": "Ὧδε μὲν Ἡρακλῆα φίλα παιδεύσατο μάτηρ.<br>εὐνὰ δ’ ἦς τῷ παιδὶ τετυγμένα ἀγχόθι πατρὸς<br>δέρμα λεόντειον μάλα οἱ κεχαρισμένον αὐτῷ,<br>δεῖπνον δὲ κρέα τ’ ὀπτὰ καὶ ἐν κανέῳ μέγας ἄρτος<br>Δωρικός· ἀσφαλέως κε φυτοσκάφον ἄνδρα κορέσσαι.<br>αὐτὰρ ἐπ’ ἄματι τυννὸν ἄνευ πυρὸς αἴνυτο δόρπον.<br>εἵματα δ’ οὐκ ἀσκητὰ μέσας ὑπὲρ ἕννυτο κνάμας.", "st": "24"}, {"sp": "SEC", "t": "ΚΕʹ — Ἡρακλῆς Λεοντοφόνος", "st": "25"}, {"sp": "N", "t": "τὸν δ’ ὁ γέρων προσέειπε φυτῶν ἐπίουρος ἀροτρεὺς<br>παυσάμενος ἔργοιο, τό οἱ μετὰ χερσὶν ἔκειτο·<br>“ἔκ τοι ξεῖνε πρόφρων μυθήσομαι ὅσσ’ ἐρεείνεις,<br>Ἑρμέω ἁζόμενος δεινὴν ὄπιν εἰνοδίοιο·<br>τὸν γάρ φασι μέγιστον ἐπουρανίων κεχολῶσθαι,<br>εἴ κεν ὁδοῦ ζαχρεῖον ἀνήνηταί τις ὁδίτην.", "st": "25"}, {"sp": "N", "t": "ποῖμναι μὲν βασιλῆος εὔτριχες Αὐγείαο<br>οὐ πᾶσαι βόσκονται ἴαν βόσιν οὐδ’ ἕνα χῶρον·<br>ἀλλ’ αἱ μέν ῥα νάοντος ἐπ’ ὄχθαις ἀμφ’ Ἐλισοῦντος,<br>αἱ δ’ ἱερὸν θείοιο παρὰ ῥόον Ἀλφειοῖο,<br>αἱ δ’ ἐπὶ Βουπρασίου πολυβότρυος, αἱ δὲ καὶ ὧδε.<br>χωρὶς δὴ σηκοί σφι τετυγμένοι εἰσὶν ἑκάσταις.<br>αὐτὰρ βουκολίοισι περιπλήθουσί περ ἔμπης<br>πάντεσσιν νομοὶ ὧδε τεθηλότες αἰὲν ἔασι,<br>Μηνίου ἀμμέγα τῖφος, ἐπεὶ πολυειδέα ποίην<br>λειμῶνες θαλέθουσιν ὑπόδροσοι εἰαμεναί τε<br>εἰς ἅλις, ἥ ῥα βόεσσι μένος κεραῇσιν ἀέξει.<br>αὖλις δέ σφισιν ἥδε τεῆς ἐπὶ δεξιὰ χειρὸς<br>φαίνεται εὖ μάλα πᾶσα πέρην ποταμοῖο ῥέοντος,<br>κείνῃ, ὅθι πλατάνιστοι ἐπηεταναὶ πεφύασι<br>χλωρή τ’ ἀγριέλαιος, Ἀπόλλωνος νομίοιο<br>ἱερὸν ἁγνόν, ξεῖνε, τελειοτάτοιο θεοῖο.<br>εὐθὺς δὲ σταθμοὶ περιμήκεες ἀγροιώταις<br>δέδμηνθ’, οἳ βασιλῆι πολὺν καὶ ἀθέσφατον ὄλβον<br>ῥυόμεθ’ ἐνδυκέως, τριπόλοις σπόρον ἐν νειοῖσιν<br>ἔσθ’ ὅτε βάλλοντες καὶ τετραπόλοισιν ὁμοίως.<br>οὔρους μὴν ἴσασι φυτοσκάφοι οἱ πολύεργοι,<br>ἐς ληνοὺς δ’ ἱκνεῦνται, ἐπὴν θέρος ὥριον ἔλθῃ.<br>πᾶν γὰρ δὴ πεδίον τόδ’ ἐπίφρονος Αὐγείαο,<br>πυροφόροι τε γύαι καὶ ἀλωαὶ δενδρήεσσαι,<br>μέχρις ἐπ’ ἐσχατιὰς πολυπίδακος ἀκρωρείης,<br>ἃς ἡμεῖς ἔργοισιν ἐποιχόμεθα πρόπαν ἦμαρ,<br>ἣ δίκη οἰκήων, οἷσιν βίος ἔπλετ’ ἐπ’ ἀγροῦ.", "st": "25"}, {"sp": "N", "t": "ἀλλὰ σύ πέρ μοι ἔνισπε, τό τοι καὶ κέρδιον αὐτῷ<br>ἔσσεται, οὗτινος ὧδε κεχρημένος εἰλήλουθας,<br>ἠὲ σύγ’ Αὐγείην ἢ καὶ δμώων τινὰ κείνου<br>δίζεαι, οἵ οἱ ἔασιν. ἐγὼ δέ κέ τοι σάφα εἰδὼς<br>ἀτρεκέως εἴποιμ’, ἐπεὶ οὐ σέγε φημὶ κακῶν ἒξ<br>ἔμμεναι οὐδὲ κακοῖσιν ἐοικότα φύμεναι αὐτόν,<br>οἷόν τοι μέγα εἶδος ἐπιπρέπει. ἦ ῥά νυ παῖδες<br>ἀθανάτων τοιοίδε μετὰ θνητοῖσιν ἔασι.”<br>τὸν δ’ ἀπαμειβόμενος προσέφη Διὸς ἄλκιμος υἱός.", "st": "25"}, {"sp": "N", "t": "“Ναὶ γέρον Αὐγείην ἐθέλοιμί κεν ἀρχὸν Ἐπειῶν<br>εἰσιδέειν· τοῦ γάρ με καὶ ἤγαγεν ἐνθάδε χρειώ.<br>εἰ δ’ ὁ μὲν ἂρ κατὰ ἄστυ μένει παρὰ οἷσι πολίταις<br>δήμου κηδόμενος, διὰ δὲ κρίνουσι θέμιστας,<br>δμώων δή τινα πρέσβυ σύ μοι φράσον ἡγεμονεύσας,<br>ὅστις ἐπ’ ἀγρῶν τῶνδε γεραίτερος αἰσυμνήτης,<br>ᾧ κε τὸ μὲν εἴποιμι, τὸ δ’ ἐκ φαμένοιο πυθοίμην.<br>ἄλλου δ’ ἄλλον ἔθηκε θεὸς ἐπιδευέα φωτῶν.”", "st": "25"}, {"sp": "N", "t": "τὸν δ’ ὁ γέρων ἐξαῦτις ἀμείβετο δῖος ἀροτρεύς·", "st": "25"}, {"sp": "N", "t": "“Ἀθανάτων ὦ ξεῖνε φραδῇ τινος ἐνθάδ’ ἱκάνεις,<br>ὥς τοι πᾶν ὃ θέλεις αἶψα χρέος ἐκτετέλεσται.<br>ὧδε γὰρ Αὐγείης, υἱὸς φίλος Ἠελίοιο,<br>σφωιτέρῳ σὺν παιδί, βίῃ Φυλῆος ἀγαυοῦ,<br>χθιζός γ’ εἰλήλουθεν ἀπ’ ἄστεος, ἤμασι πολλοῖς<br>κτῆσιν ἐποψόμενος, ἥ οἱ νήριθμος ἐπ’ ἀγρῶν·<br>ὥς που καὶ βασιλεῦσιν ἐείδεται ἐν φρεσὶν ᾗσιν<br>αὐτοῖς κηδομένοισι σαώτερος ἔμμεναι οἶκος.<br>ἀλλ’ ἴομεν μάλα πρός μιν· ἐγὼ δέ τοι ἡγεμονεύσω<br>αὖλιν ἐφ’ ἡμετέρην, ἵνα κεν τέτμοιμεν ἄνακτα.”", "st": "25"}, {"sp": "N", "t": "Ὣς εἰπὼν ἡγεῖτο, νόῳ δ’ ἔτι πόλλ’ ἐμενοίνα,<br>δέρμά τε θηρὸς ὁρῶν χειροπληθῆ τε κορύνην,<br>ὁππόθεν ὁ ξεῖνος· μέμονεν δέ μιν αἰὲν ἔρεσθαι·<br>ἂψ δ’ ὄκνῳ ποτὶ χεῖλος ἐλάμβανε μῦθον ἰόντα,<br>μή τί οἱ οὐ κατὰ καιρὸν ἔπος προτιμυθήσαιτο,<br>σπερχομένου· χαλεπὸν δ’ ἑτέρου νόον ἴδμεναι ἀνδρός.", "st": "25"}, {"sp": "N", "t": "τοὺς δὲ κύνες προσιόντας ἀπόπροθεν αἶψ’ ἐνόησαν,<br>ἀμφότερον ὀσμῇ τε χροὸς δούπῳ τε ποδοῖιν.<br>θεσπέσιον δ’ ὑλάοντες ἐπέδραμον ἄλλοθεν ἄλλος<br>Ἀμφιτρυωνιάδῃ Ἡρακλέι· τὸν δὲ γέροντα<br>ἀχρεῖον κλάζοντε περίσσαινον ἑτέρωθεν.<br>τοὺς μὲν ὅγε λάεσσιν ἀπὸ χθόνος ὅσσον ἀείρων<br>φευγέμεν ἂψ ὀπίσω δειδίσσετο, τρηχὺ δὲ φωνῇ<br>ἠπείλει μάλα πᾶσιν, ἐρητύσασκε δ’ ὑλαγμοῦ,<br>χαίρων ἐν φρεσὶν ᾗσιν, ὁθούνεκεν αὖλιν ἔρυντο<br>αὐτοῦ γ’ οὐ παρεόντος· ἔπος δ’ ὅγε τοῖον ἔειπεν·", "st": "25"}, {"sp": "N", "t": "“Ὢ πόποι, οἷον τοῦτο θεοὶ ποίησαν ἄνακτες<br>θηρίον ἀνθρώποισι μετέμμεναι, ὡς ἐπιμηθές.<br>εἴ οἱ καὶ φρένες ὧδε νοήμονες ἔνδοθεν ἦσαν,<br>ᾔδει δ’, ᾧ τε χρὴ χαλεπαινέμεν ᾧ τε καὶ οὐκί,<br>οὐκ ἄν οἱ θηρῶν τις ἐδήρισεν περὶ τιμῆς·<br>νῦν δὲ λίην ζάκοτόν τε καὶ ἀρρηνὲς γένετ’ αὔτως.”", "st": "25"}, {"sp": "N", "t": "Ἦ ῥα, καὶ ἐσσυμένως ποτὶ ταὐλίον ἷξον ἰόντες.", "st": "25"}, {"sp": "N", "t": "Ἠέλιος μὲν ἔπειτα ποτὶ ζόφον ἔτραπεν ἵππους<br>δείελον ἦμαρ ἄγων· τὰ δ’ ἐπήλυθε πίονα μῆλα<br>ἐκ βοτάνης ἀνιόντα μετ’ αὐλία τε σηκούς τε.<br>αὐτὰρ ἔπειτα βόες μάλα μυρίαι ἄλλαι ἐπ’ ἄλλαις<br>ἐρχόμεναι φαίνονθ’ ὡσεὶ νέφη ὑδατόεντα,<br>ἅσσά τ’ ἐν οὐρανῷ εἶσιν ἐλαυνόμενα προτέρωσε<br>ἠὲ νότοιο βίῃ ἠὲ Θρῃκὸς βορέαο·<br>τῶν μέν τ’ οὔτις ἀριθμὸς ἐν ἠέρι γίνετ’ ἰόντων,<br>οὐδ’ ἄνυσις· τόσα γάρ τε μετὰ προτέροισι κυλίνδει<br>ἲς ἀνέμου, τὰ δέ τ’ ἄλλα κορύσσεται αὖτις ἐπ’ ἄλλοις·<br>τόσσ’ αἰεὶ μετόπισθε βοῶν ἐπὶ βουκόλι’ ᾔει.<br>πᾶν δ’ ἄρ’ ἐνεπλήσθη πεδίον, πᾶσαι δὲ κέλευθοι<br>ληίδος ἐρχομένης (στείνοντο δὲ πίονες ἀγροί),<br>μυκηθμῷ· σηκοὶ δὲ βοῶν ῥεῖα πλήσθησαν<br>εἰλιπόδων, ὄιες δὲ κατ’ αὐλὰς ηὐλίζοντο.", "st": "25"}, {"sp": "N", "t": "ἔνθα μὲν οὔτις ἕκηλος ἀπειρεσίων περ ἐόντων<br>εἱστήκει παρὰ βουσὶν ἀνὴρ κεχρημένος ἔργου·<br>ἀλλ’ ὁ μὲν ἀμφὶ πόδεσσιν ἐυτμήτοισιν ἱμᾶσι<br>κωλοπέδας ἀράρισκε περισταδὸν ἐγγὺς ἀμέλγειν·<br>ἄλλος δ’ αὖ φίλα τέκνα φίλαις ὑπὸ μητράσιν ἵει<br>πινέμεναι λιαροῖο μεμαότα πάγχυ γάλακτος,<br>ἄλλος ἀμόλγιον εἶχ’, ἄλλος τρέφε πίονα τυρόν,<br>ἄλλος ἐσῆγεν ἔσω ταύρους δίχα θηλειάων.<br>Αὐγείης δ’ ἐπὶ πάντας ἰὼν θηεῖτο βοαύλους<br>ἥντινά οἱ κτεάνων κομιδὴν ἐτίθεντο νομῆες,<br>σὺν δ’ υἱός τε βίη τε βαρύφρονος Ἡρακλῆος<br>ὡμάρτευν βασιλῆι διερχομένῳ μέγαν ὄλβον.<br>ἔνθα καὶ ἄρρηκτόν περ ἔχων ἐν στήθεσι θυμὸν<br>Ἀμφιτρυωνιάδης καὶ ἀρηρότα νωλεμὲς αἰεὶ<br>ἐκπάγλως θαύμαζε θεῶν τόγε μυρίον ἕδνον<br>εἰσορόων. οὐ γάρ κεν ἔφασκέ τις οὐδὲ ἐώλπει<br>ἀνδρὸς ληίδ’ ἑνὸς τόσσην ἔμεν οὐδὲ δέκ’ ἄλλων,<br>οἵτε πολύρρηνες πάντων ἔσαν ἐκ βασιλήων.<br>Ἠέλιος δ’ ᾧ παιδὶ τόγ’ ἔξοχον ὤπασε δῶρον,<br>ἀφνειὸν μήλοις περὶ πάντων ἔμμεναι ἀνδρῶν,<br>καί ῥά οἱ αὐτὸς ὄφελλε διαμπερέως βοτὰ πάντα<br>ἐς τέλος· οὐ μὲν γάρ τις ἐπήλυθε νοῦσος ἐκείνου<br>βουκολίοις, αἵτ’ ἔργα καταφθείρουσι νομήων,<br>αἰεὶ δὲ πλέονες κερααὶ βόες, αἰὲν ἀμείνους<br>ἐξ ἔτεος γίνοντο μάλ’ εἰς ἔτος· ἦ γὰρ ἅπασαι<br>ζωοτόκοι τ’ ἦσαν περιώσια θηλυτόκοι τε.", "st": "25"}, {"sp": "N", "t": "ταῖς δὲ τριηκόσιοι ταῦροι συνάμ’ ἐστιχόωντο<br>κνήμαργοί θ’ ἕλικές τε, διηκόσιοί γε μὲν ἄλλοι<br>φοίνικες· πάντες δ’ ἐπιβήτορες οἵγ’ ἔσαν ἤδη.<br>ἄλλοι δ’ αὖ μετὰ τοῖσι δυώδεκα βουκολέοντο<br>ἱεροὶ Ἠελίοιο· χρόην δ’ ἔσαν ἠύτε κύκνοι<br>ἀργησταί, πᾶσιν δὲ μετέπρεπον εἰλιπόδεσσιν<br>οἳ καὶ ἀτιμαγέλαι βόσκοντ’ ἐριθηλέα ποίην<br>ἐν νομῷ· ὧδ’ ἔκπαγλον ἐπὶ σφίσι γαυριόωντο.<br>καί ῥ’ ὁπότ’ ἐκ λασίοιο θοοὶ προγενοίατο θῆρες<br>ἐς πεδίον δρυμοῖο βοῶν ἕνεκ’ ἀγροτεράων,<br>πρῶτοι τοίγε μάχηνδε κατὰ χροὸς ᾔεσαν ὀσμήν,<br>δεινὸν δ’ ἐβρυχῶντο φόνον λεύσσοντε προσώπῳ.", "st": "25"}, {"sp": "N", "t": "τῶν μέν τε προφέρεσκε βίηφί τε καὶ σθένεϊ ᾧ<br>ἠδ’ ὑπεροπλίῃ Φαέθων μέγας, ὅν ῥα βοτῆρες<br>ἀστέρι πάντες ἔισκον, ὁθούνεκα πολλὸν ἐν ἄλλοις<br>βουσὶν ἰὼν λάμπεσκεν, ἀρίζηλος δ’ ἐτέτυκτο.<br>ὃς δή τοι σκύλος αὖον ἰδὼν χαροποῖο λέοντος<br>αὐτῷ ἔπειτ’ ἐπόρουσεν ἐυσκόπῳ Ἡρακλῆι<br>χρίμψασθαι ποτὶ πλευρὰ κάρη στιβαρόν τε μέτωπον.<br>τοῦ μὲν ἄναξ προσιόντος ἐδράξατο χειρὶ παχείῃ<br>σκαιοῦ ἄφαρ κέραος, κατὰ δ’ αὐχένα νέρθ’ ἐπὶ γαίης<br>κλάσσε βαρύν περ ἐόντα, πάλιν δέ μιν ὦσεν ὀπίσσω<br>ὤμῳ ἐπιβρίσας· ὁ δέ οἱ περὶ νεῦρα τανυσθεὶς<br>μυὼν ἐξ ὑπάτοιο βραχίονος ὀρθὸς ἀνέστη.<br>θαύμαζεν δ’ αὐτός τε ἄναξ υἱός τε δαΐφρων<br>Φυλεὺς οἵ τ’ ἐπὶ βουσὶ κορωνίσι βουκόλοι ἄνδρες,<br>Ἀμφιτρυωνιάδαο βίην ὑπέροπλον ἰδόντες.", "st": "25"}, {"sp": "N", "t": "τὼ δ’ εἰς ἄστυ λιπόντε καταυτόθι πίονας ἀγροὺς<br>ἐστιχέτην, Φυλεύς τε βίη θ’ Ἡρακληείη.<br>λαοφόρου δ’ ἐπέβησαν ὅθι πρώτιστα κελεύθου,<br>λεπτὴν καρπαλίμοισι τρίβον ποσὶν ἐξανύσαντες,<br>ἥ ῥα δι’ ἀμπελεῶνος ἀπὸ σταθμῶν τετάνυστο<br>οὔτι λίην ἀρίσημος ἐν ὕλῃ χλωρὰ θέουσα,<br>τῇ μιν ἄρα προσέειπε Διὸς γόνον ὑψίστοιο<br>Αὐγείω φίλος υἱὸς ἕθεν μετόπισθεν ἰόντα,<br>ἦκα παρακλίνας κεφαλὴν κατὰ δεξιὸν ὦμον·", "st": "25"}, {"sp": "N", "t": "“ξεῖνε, πάλαι τινὰ πάγχυ σέθεν πέρι μῦθον ἀκούσας<br>ὡσεί περ σφετέρῃσιν ἐνὶ φρεσὶ βάλλομαι ἄρτι.<br>ἤλυθε γὰρ στείχων τις ἀπ’ Ἄργεος ὡς μέσος ἀκμῆς<br>ἐνθάδ’ Ἀχαιὸς ἀνὴρ Ἑλίκης ἐξ ἀγχιάλοιο·<br>ὃς δή τοι μυθεῖτο καὶ ἐν πλεόνεσσιν Ἐπειῶν,<br>οὕνεκεν Ἀργείων τις ἕθεν παρεόντος ὄλεσσε<br>θηρίον, αἰνολέοντα, κακὸν τέρας ἀγροιώταις,<br>κοίλην αὖλιν ἔχοντα Διὸς Νεμέοιο παρ’ ἄλσος,<br>οὐκ οἶδ’ ἀτρεκέως ἢ Ἄργεος ἐξ ἱεροῖο<br>αὐτόθεν ἢ Τίρυνθα νέμων πόλιν ἠὲ Μυκήνην.<br>ὣς κεῖνος ἀγόρευε· γένος δέ μιν εἶναι ἔφασκεν,<br>εἰ ἐτεόν περ ἐγὼ μιμνήσκομαι, ἐκ Περσῆος.<br>ἔλπομαι οὐχ ἕτερον τόδε τλήμεναι Αἰγιαλήων<br>ἠὲ σέ· δέρμα δὲ θηρὸς ἀριφραδέως ἀγορεύει<br>χειρῶν καρτερὸν ἔργον, ὅ τοι περὶ πλευρὰ καλύπτει.<br>εἴπ’ ἄγε νῦν μοι πρῶτον, ἵνα γνώω κατὰ θυμόν,<br>ἥρως, εἴτ’ ἐτύμως μαντεύομαι εἴτε καὶ οὐκί,<br>εἰ σύγ’ ἐκεῖνος, ὃν ἧμιν ἀκουόντεσσιν ἔειπεν<br>οὑξ Ἑλίκηθεν Ἀχαιός, ἐγὼ δέ σε φράζομαι ὀρθῶς.<br>εἰπὲ δ’ ὅπως ὀλοὸν τόδε θηρίον αὐτὸς ἔπεφνες,<br>ὅππως τ’ εὔυδρον Νεμέης εἰσήλυθε χῶρον·<br>οὐ μὲν γάρ κε τοσόνδε κατ’ Ἀπίδα κνώδαλον εὕροις<br>ἱμείρων ἰδέειν, ἐπεὶ οὐ μάλα τηλίκα βόσκει,<br>ἀλλ’ ἄρκτους τε σύας τε λύκων τ’ ὀλοφώιον ἔρνος.<br>τῷ καὶ θαυμάζεσκον ἀκούοντες τότε μῦθον·<br>οἱ δέ νυ καὶ ψεύδεσθαι ὁδοιπόρον ἀνέρ’ ἔφαντο<br>γλώσσης μαψιδίοιο χαριζόμενον παρεοῦσιν.”", "st": "25"}, {"sp": "N", "t": "Ὣς εἰπὼν μέσσης ἐξηρώησε κελεύθου<br>Φυλεύς, ὄφρα κιοῦσιν ἅμα σφίσιν ἄρκιος εἴη,<br>καί ῥά τε ῥηίτερον φαμένου κλύοι Ἡρακλῆος,<br>ὅς μιν ὁμαρτήσας τοίῳ προσελέξατο μύθῳ·", "st": "25"}, {"sp": "N", "t": "“Ὦ Αὐγηιάδη, τὸ μὲν ὅττί με πρῶτον ἀνήρευ,<br>αὐτὸς καὶ μάλα ῥεῖα κατὰ στάθμην ἐνόησας.<br>ἀμφὶ δέ σοι τὰ ἕκαστα λέγοιμί κε τοῦδε πελώρου<br>ὅππως ἐκράανθεν, ἐπεὶ λελίησαι ἀκούειν,<br>νόσφίν γ’ ἢ ὅθεν ἦλθε· τὸ γὰρ πολέων περ ἐόντων<br>Ἀργείων οὐδείς κεν ἔχοι σάφα μυθήσασθαι·<br>οἶον δ’ ἀθανάτων τίν’ ἐίσκομεν ἀνδράσι πῆμα<br>ἱρῶν μηνίσαντα Φορωνείδῃσιν ἐφεῖναι.<br>πάντας γὰρ πισῆας ἐπικλύζων ποταμὸς ὣς<br>λῖς ἄμοτον κεράιζε, μάλιστα δὲ Βεμβιναίους,<br>οἵ ἑθεν ἀγχόμοροι ναῖον πασχόντες ἄτλητα.", "st": "25"}, {"sp": "N", "t": "τὸν μὲν ἐμοὶ πρώτιστα τελεῖν ἐπέταξεν ἄεθλον<br>Εὐρυσθεύς, κτεῖναι δέ μ’ ἐφίετο θηρίον αἰνόν.<br>αὐτὰρ ἐγὼ κέρας ὑγρὸν ἑλὼν κοίλην τε φαρέτρην<br>ἰῶν ἐμπλείην νεόμην, ἑτέρηφι δὲ βάκτρον<br>εὐπαγὲς αὐτόφλοιον ἐπηρεφέος κοτίνοιο<br>ἔμμητρον, τὸ μὲν αὐτὸς ὑπὸ ζαθέῳ Ἑλικῶνι<br>εὑρὼν σὺν πυκινῇσιν ὁλοσχερὲς ἔσπασα ῥίζαις.<br>αὐτὰρ ἐπεὶ τὸν χῶρον, ὅθι λῖς ἦεν, ἵκανον,<br>δὴ τότε τόξον ἑλὼν στρεπτὴν ἐπέλασσα κορώνῃ<br>νευρειήν, περὶ δ’ ἰὸν ἐχέστονον εἶθαρ ἔβησα.<br>πάντῃ δ’ ὄσσε φέρων ὀλοὸν τέρας ἐσκοπίαζον,<br>εἴ μιν ἐσαθρήσαιμι, πάρος γ’ ἐμὲ κεῖνον ἰδέσθαι.<br>ἤματος ἦν τὸ μεσηγύ, καὶ οὐδέ πῃ ἴχνια τοῖο<br>φρασθῆναι δυνάμην οὐδ’ ὠρυγμοῖο πυθέσθαι.<br>οὐδὲ μὲν ἀνθρώπων τις ἔην ἐπὶ βουσὶ καὶ ἔργοις<br>φαινόμενος σπορίμοιο δι’ αὔλακος, ὅντιν’ ἐροίμην·<br>ἀλλὰ κατὰ σταθμοὺς χλωρὸν δέος εἶχεν ἕκαστον.<br>οὐ μὴν πρὶν πόδας ἔσχον ὄρος τανύφυλλον ἐρευνῶν,<br>πρὶν ἰδέειν ἀλκῆς τε παραυτίκα πειρηθῆναι.<br>ἤτοι ὁ μὲν σήραγγα προδείελος ἔστιχεν εἰς ἥν,<br>βεβρωκὼς κρειῶν τε καὶ αἵματος, ἀμφὶ δὲ χαίτας<br>αὐχμηρὰς πεπάλακτο φόνῳ χαροπόν τε πρόσωπον<br>στήθεά τε, γλώσσῃ δὲ περιλιχμᾶτο γένειον.<br>αὐτὰρ ἐγὼ θάμνοισιν ἄφαρ σκιεροῖσιν ἐκρύφθην<br>ἐν ῥίῳ ὑλήεντι δεδεγμένος ὁππόθ’ ἵκοιτο,<br>καὶ βάλον ἆσσον ἰόντος ἀριστερὸν ἐς κενεῶνα<br>τηϋσίως· οὐ γάρ τι βέλος διὰ σαρκὸς ὄλισθεν<br>ὀκριόεν, χλωρῇ δὲ παλίσσυτον ἔμπεσε ποίῃ.<br>αὐτὰρ ὁ κρᾶτα δαφοινὸν ἀπὸ χθονὸς ὦκ’ ἐπάειρε<br>θαμβήσας, πάντῃ δὲ διέδρακεν ὀφθαλμοῖσι<br>σκεπτόμενος, λαμυροὺς δὲ χανὼν ὑπ’ ὀδόντας ἔφηνε.<br>τῷ δ’ ἐγὼ ἄλλον ὀιστὸν ἀπὸ νευρῆς προΐαλλον<br>ἀσχαλόων, ὅ μοι ὁ πρὶν ἐτώσιος ἔκφυγε χειρός·<br>μεσσηγὺς δ’ ἔβαλον στηθέων, ὅθι πνεύμονος ἕδρη.<br>ἀλλ’ οὐδ’ ὣς ὑπὸ βύρσαν ἔδυ πολυώδυνος ἰός,<br>ἀλλ’ ἔπεσε προπάροιθε ποδῶν ἀνεμώλιος αὔτως.<br>τὸ τρίτον αὖ μέλλεσκον ἀσώμενος ἐν φρεσὶν αἰνῶς<br>αὐερύειν· ὁ δέ μ’ εἶδε περιγληνώμενος ὄσσοις<br>θὴρ ἄμοτος, μακρὴν δὲ περ’ ἰγνύῃσιν ἕλιξε<br>κέρκον, ἄφαρ δὲ μάχης ἐμνήσατο· πᾶς δέ οἱ αὐχὴν<br>θυμοῦ ἐνεπλήσθη, πυρσαὶ δ’ ἔφριξαν ἔθειραι<br>σκυζομένῳ, κυρτὴ δὲ ῥάχις γένετ’ ἠύτε τόξον,<br>πάντοθεν εἰληθέντος ὑπὸ λαγόνας τε καὶ ἰξύν.<br>ὡς δ’ ὅτ’ ἂν ἁρματοπηγὸς ἀνὴρ πολέων ἴδρις ἔργων<br>ὄρπηκας κάμπτῃσιν ἐρινεοῦ εὐκεάτοιο,<br>θάλψας ἐν πυρὶ πρῶτον, ἐπαξονίῳ κύκλα δίφρῳ·<br>τοῦ μὲν ὑπὲκ χειρῶν ἔφυγεν τανύφλοιος ἐρινεὸς<br>καμπτόμενος, τηλοῦ δὲ μιῇ πήδησε σὺν ὁρμῇ·<br>ὣς ἐπ’ ἐμοὶ λῖς αἰνὸς ἀπόπροθεν ἀθρόος ἆλτο<br>μαιμώων χροὸς ἆσαι· ἐγὼ δ’ ἑτέρηφι βέλεμνα<br>χειρὶ προεσχεθόμην καὶ ἀπ’ ὤμων δίπλακα λώπην,<br>τῇ δ’ ἑτέρῃ ῥόπαλον κόρσης ὕπερ αὖον ἀείρας<br>ἤλασα κὰκ κεφαλῆς, διὰ δ’ ἄνδιχα τρηχὺν ἔαξα<br>αὐτοῦ ἐπὶ λασίοιο καρήατος ἀγριέλαιον<br>θηρὸς ἀμαιμακέτοιο· πέσεν δ’ ὅγε πρὶν ἔμ’ ἱκέσθαι<br>ὑψόθεν ἐν γαίῃ, καὶ ἐπὶ τρομεροῖς ποσὶν ἔστη<br>νευστάζων κεφαλῇ· περὶ γὰρ σκότος ὄσσέ οἱ ἄμφω<br>ἦλθε, βίῃ σεισθέντος ἐν ὀστέῳ ἐγκεφάλοιο.<br>τὸν μὲν ἐγὼν ὀδύνῃσι παραφρονέοντα βαρείαις<br>νωσάμενος, πρὶν αὖτις ὑπότροπον ἀμπνυνθῆναι,<br>αὐχένος ἀρρήκτοιο παρ’ ἰνίον ἤλασα προφθάς,<br>ῥίψας τόξον ἔραζε πολύρραπτόν τε φαρέτρην·<br>ἦγχον δ’ ἐγκρατέως στιβαρὰς σὺν χεῖρας ἐρείσας<br>ἐξόπιθεν, μὴ σάρκας ὑποδρύψῃ ὀνύχεσσι,<br>πρὸς δ’ οὖδας πτέρνῃσι πόδας στερεῶς ἐπίεζον<br>οὐραίους ἐπιβάς, μηροῖσί τε πλεύρ’ ἐφύλασσον,<br>μέχρί οἱ ἐξετάνυσσα βραχίονας ὀρθὸν ἀείρας<br>ἄπνευστον, ψυχὴν δὲ πελώριος ἔλλαχεν Ἅιδης.", "st": "25"}, {"sp": "N", "t": "καὶ τότε δὴ βούλευον, ὅπως λασιαύχενα βύρσαν<br>θηρὸς τεθνειῶτος ἀπὸ μελέων ἐρυσαίμην,<br>ἀργαλέον μάλα μόχθον, ἐπεὶ οὐκ ἔσκε σιδήρῳ<br>τμητὴ οὐδὲ λίθοις πειρωμένῳ, οὐδὲ μὲν ἄλλῃ<br>ἔνθά μοι ἀθανάτων τις ἐπὶ φρεσὶ θῆκε νοῆσαι<br>αὐτοῖς δέρμα λέοντος ἀνασχίζειν ὀνύχεσσι.<br>τοῖσι θοῶς ἀπέδειρα, καὶ ἀμφεθέμην μελέεσσιν<br>ἕρκος ἐνυαλίου ταμεσίχροος ἰωχμοῖο.", "st": "25"}, {"sp": "N", "t": "οὗτός τοι Νεμέου γένετ’ ὦ φίλε θηρὸς ὄλεθρος,<br>πολλὰ πάρος μήλοις τε καὶ ἀνδράσι κήδεα θέντος.”", "st": "25"}, {"sp": "SEC", "t": "ΚϚʹ — Λῆναι ἢ Βάκχαι", "st": "26"}, {"sp": "N", "t": "Ἰνὼ καὐτονόα χἁ μαλοπάραυος Ἀγαύα<br>τρεῖς θιάσως ἐς ὄρος τρεῖς ἄγαγον αὐταὶ ἐοῖσαι.<br>χαἱ μὲν ἀμερξάμεναι λασίας δρυὸς ἄγρια φύλλα<br>κισσόν τε ζώοντα καὶ ἀσφόδελον τὸν ὑπὲρ γᾶς<br>ἐν καθαρῷ λειμῶνι κάμον δυοκαίδεκα βωμούς,<br>τὼς τρεῖς τᾷ Σεμέλᾳ, τὼς ἐννέα τῷ Διονύσῳ.<br>ἱερὰ δ’ ἐκ κίστας ποπανεύματα χερσὶν ἑλοῖσαι<br>εὐφάμως κατέθεντο νεοδρέπτων ἐπὶ βωμῶν,<br>ὡς ἐδίδασχ’, ὡς αὐτὸς ἐθυμάρει Διόνυσος.", "st": "26"}, {"sp": "N", "t": "Πενθεὺς δ’ ἀλιβάτου πέτρας ἄπο πάντ’ ἐθεώρει,<br>σχῖνον ἐς ἀρχαίαν καταδύς, ἐπιχώριον ἔρνος.<br>Αὐτονόα πράτα νιν ἀνέκραγε δεινὸν ἰδοῖσα,<br>σὺν δ’ ἐτάραξε ποσὶν μανιώδεος ὄργια Βάκχου,<br>ἐξαπίνας ἐπιοῖσα, τὰ δ’ οὐχ ὁρέοντι βέβηλοι.<br>μαίνετο μέν θ’ αὕτα, μαίνοντο δ’ ἄρ’ εὐθὺ καὶ ἄλλαι.<br>Πενθεὺς μὲν φεῦγεν πεφοβημένος, αἱ δ’ ἐδίωκον,<br>πέπλως ἐκ ζωστῆρος ἐπ’ ἰγνύαν ἐρύσαισαι.", "st": "26"}, {"sp": "N", "t": "Πενθεὺς μὲν τόδ’ ἔειπε· “τίνος κέχρησθε γυναῖκες;”<br>Αὐτονόα τόδ’ ἔειπε “τάχα γνώσῃ πρὶν ἀκοῦσαι.”", "st": "26"}, {"sp": "N", "t": "μάτηρ μὲν κεφαλὰν μυκήσατο παιδὸς ἑλοῖσα,<br>ὅσσόν περ τοκάδος τελέθει μύκημα λεαίνας·<br>Ἰνὼ δ’ ἐξέρρηξε σὺν ὠμοπλάτᾳ μέγαν ὦμον<br>λὰξ ἐπὶ γαστέρα βᾶσα, καὶ Αὐτονόας ῥυθμὸς ωὑτός·<br>αἱ δ’ ἄλλαι τὰ περισσὰ κρεανομέοντο γυναῖκες.<br>ἐς Θήβας δ’ ἀφίκοντο πεφυρμέναι αἵματι πᾶσαι,<br>ἐξ ὄρεος πένθημα καὶ οὐ Πενθῆα φέροισαι.", "st": "26"}, {"sp": "N", "t": "οὐκ ἀλέγω· μηδ’ ἄλλος ἀπεχθομένω Διονύσῳ<br>φροντίζοι, μηδ’ εἰ χαλεπώτερα τῶνδ’ ἐμόγησεν,<br>εἴη δ’ ἐνναέτης ἢ καὶ δεκάτω ἐπιβαίνοι·<br>αὐτὸς δ’ εὐαγέοιμι καὶ εὐαγέεσσιν ἅδοιμι.", "st": "26"}, {"sp": "N", "t": "ἐκ Διὸς αἰγιόχω τιμὰν ἔχει αἰετὸς οὗτος.<br>εὐσεβέων παίδεσσι τὰ λώια, δυσσεβέων δ’ οὔ.", "st": "26"}, {"sp": "N", "t": "χαίροι μὲν Διόνυσος, ὃν ἐν Δρακάνῳ νιφόεντι<br>Ζεὺς ὕπατος μεγάλαν ἐπιγουνίδα κάτθετο λύσας·<br>χαίροι δ’ εὐειδὴς Σεμέλα καὶ ἀδελφεαὶ αὐτᾶς<br>Καδμεῖαι πολλαῖς μεμελημέναι ἡρωίναις,<br>αἳ τόδε ἔργον ἔρεξαν ὀρίναντος Διονύσου<br>οὐκ ἐπιμωματόν. μηδεὶς τὰ θεῶν ὀνόσαιτο.", "st": "26"}, {"sp": "SEC", "t": "ΚΖʹ — Ὀαριστύς", "st": "27"}, {"sp": "Κόρη", "t": "τὰν πινυτὰν Ἑλέναν Πάρις ἥρπασε βουκόλος ἄλλος.", "st": "27"}, {"sp": "Δάφνις", "t": "μᾶλλον ἑκοῖσ’ Ἑλένα τὸν βουκόλον ἔσχε φιλεῦσα.", "st": "27"}, {"sp": "Κόρη", "t": "μὴ καυχῶ σατυρίσκε· κενὸν τὸ φίλαμα λέγουσιν.", "st": "27"}, {"sp": "Δάφνις", "t": "ἔστι καὶ ἐν κενεοῖσι φιλάμασιν ἁδέα τέρψις.", "st": "27"}, {"sp": "Κόρη", "t": "τὸ στόμα μευ πλύνω καὶ ἀποπτύω τὸ φίλαμα.", "st": "27"}, {"sp": "Δάφνις", "t": "πλύνεις χείλεα σεῖο; δίδου πάλιν ὄφρα φιλάσω.", "st": "27"}, {"sp": "Κόρη", "t": "καλόν σοι δαμάλας φιλέειν, οὐκ ἄζυγα κώραν.", "st": "27"}, {"sp": "Δάφνις", "t": "μὴ καυχῶ· τάχα γάρ σε παρέρχεται ὡς ὄναρ ἥβη.", "st": "27"}, {"sp": "Κόρη", "t": "ἢν δέ τι γηράσκω, τόδε που μέλι καὶ γάλα πίνω.", "st": "27"}, {"sp": "Δάφνις", "t": "…", "st": "27"}, {"sp": "Κόρη", "t": "ἁ σταφυλὶς σταφίς ἐστι καὶ οὐ ῥόδον αὖον ὀλεῖται.", "st": "27"}, {"sp": "Δάφνις", "t": "δεῦρ’ ὑπὸ τὰς κοτίνους, ἵνα σοί τινα μῦθον ἐνίψω.", "st": "27"}, {"sp": "Κόρη", "t": "οὐκ ἐθέλω· καὶ πρίν με παρήπαφες ἁδέι μύθῳ.", "st": "27"}, {"sp": "Δάφνις", "t": "δεῦρ’ ὑπὸ τὰς πτελέας, ἵν’ ἐμᾶς σύριγγος ἀκούσῃς.", "st": "27"}, {"sp": "Κόρη", "t": "τὴν σαυτοῦ φρένα τέρψον· ὀιζύον οὐδὲν ἀρέσκει.", "st": "27"}, {"sp": "Δάφνις", "t": "φεῦ φεῦ τᾶς Παφίας χόλον ἅζεο καὶ σύγε κώρα.", "st": "27"}, {"sp": "Κόρη", "t": "χαιρέτω ἁ Παφία· μόνον ἵλαος Ἄρτεμις εἴη.", "st": "27"}, {"sp": "Δάφνις", "t": "μὴ λέγε, μὴ βάλλῃ σε καὶ ἐς λίνον ἄκριτον ἔνθῃς.", "st": "27"}, {"sp": "Κόρη", "t": "βαλλέτω ὡς ἐθέλει· πάλιν Ἄρτεμις ἄμμιν ἀρήγει.<br>[μἠπιβάλῃς τὰν χεῖρα, καὶ εἰσέτι χεῖλος ἀμύξω.]", "st": "27"}, {"sp": "Δάφνις", "t": "οὐ φεύγεις τὸν Ἔρωτα, τὸν οὐ φύγε παρθένος ἄλλη.", "st": "27"}, {"sp": "Κόρη", "t": "φεύγω ναὶ τὸν Πᾶνα· σὺ δὲ ζυγὸν αἰὲν ἀείρεις.", "st": "27"}, {"sp": "Δάφνις", "t": "δειμαίνω, μὴ δή σε κακωτέρῳ ἀνέρι δώσει.", "st": "27"}, {"sp": "Κόρη", "t": "πολλοί μ’ ἐμνώοντο, νόμον δ’ ἐμὸν οὔτις ἀείδει.", "st": "27"}, {"sp": "Δάφνις", "t": "εἷς καὶ ἐγὼ πολλῶν μνηστὴρ τεὸς ἐνθάδ’ ἱκάνω.", "st": "27"}, {"sp": "Κόρη", "t": "καὶ τί φίλος ῥέξαιμι; γάμοι πλήθουσιν ἀνίας.", "st": "27"}, {"sp": "Δάφνις", "t": "οὐκ ὀδύνην, οὐκ ἄλγος ἔχει γάμος, ἀλλὰ χορείην.", "st": "27"}, {"sp": "Κόρη", "t": "ναὶ μάν φασι γυναῖκας ἑοὺς τρομέειν παρακοίτας.", "st": "27"}, {"sp": "Δάφνις", "t": "μᾶλλον ἀεὶ κρατέουσι· τίνα τρομέουσι γυναῖκες;", "st": "27"}, {"sp": "Κόρη", "t": "ὠδίνειν τρομέω· χαλεπὸν βέλος Εἰλειθυίης.", "st": "27"}, {"sp": "Δάφνις", "t": "ἀλλὰ τεὴ βασίλεια μογοστόκος Ἄρτεμίς ἐστιν.", "st": "27"}, {"sp": "Κόρη", "t": "ἀλλὰ τεκεῖν τρομέω, μὴ καὶ χρόα καλὸν ὀλέσσω.", "st": "27"}, {"sp": "Δάφνις", "t": "ἢν δὲ τέκῃς φίλα τέκνα, νέον φάος ὄψεαι υἷας.", "st": "27"}, {"sp": "Κόρη", "t": "καὶ τί μοι ἕδνον ἄγεις γάμου ἄξιον, ἢν ἐπινεύσω;", "st": "27"}, {"sp": "Δάφνις", "t": "πᾶσαν τὰν ἀγέλαν, πάντ’ ἄλσεα καὶ νομὸν ἕξεις.", "st": "27"}, {"sp": "Κόρη", "t": "ὄμνυε μὴ μετὰ λέκτρα λιπὼν ἀέκουσαν ἀπενθεῖν.", "st": "27"}, {"sp": "Δάφνις", "t": "οὐκ αὐτὸν τὸν Πᾶνα, καὶ ἢν ἐθέλῃς με διῶξαι.", "st": "27"}, {"sp": "Κόρη", "t": "τεύχεις μοι θαλάμους, τεύχεις καὶ δῶμα καὶ αὐλάς;", "st": "27"}, {"sp": "Δάφνις", "t": "τεύχω σοι θαλάμους· τὰ δὲ πώεα καλὰ νομεύω.", "st": "27"}, {"sp": "Κόρη", "t": "πατρὶ δὲ γηραλέῳ τίνα μάν, τίνα μῦθον ἐνίψω;", "st": "27"}, {"sp": "Δάφνις", "t": "αἰνήσει σέο λέκτρον, ἐπὴν ἐμὸν οὔνομ’ ἀκούσῃ.", "st": "27"}, {"sp": "Κόρη", "t": "οὔνομα σὸν λέγε τῆνο· καὶ οὔνομα πολλάκι τέρπει.", "st": "27"}, {"sp": "Δάφνις", "t": "Δάφνις ἐγώ, Λυκίδας τε πατήρ, μήτηρ δὲ Νομαία.", "st": "27"}, {"sp": "Κόρη", "t": "ἐξ εὐηγενέων· ἀλλ’ οὐ σέθεν εἰμὶ χερείων.", "st": "27"}, {"sp": "Δάφνις", "t": "οἶδ’, ἄκρα τιμίη ἐσσί· πατὴρ δέ τοί ἐστι Μενάλκας.", "st": "27"}, {"sp": "N", "t": "…", "st": "27"}, {"sp": "SEC", "t": "ΚΗʹ — Ἠλακάτη", "st": "28"}, {"sp": "N", "t": "Γλαύκας ὦ φιλέριθ’ ἀλακάτα δῶρον Ἀθανάας<br>γύναιξιν, νόος οἰκωφελίας αἷσιν ἐπάβολος,<br>θέρσεισ’ ἄμμιν ὑμάρτη πόλιν ἐς Νείλεος ἀγλάαν,<br>ὅπᾳ Κύπριδος ἶρον καλάμω χλῶρον ὑπαπάλω.<br>τυῖδε γὰρ πλόον εὐάνεμον αἰτήμεθα πὰρ Δίος,<br>ὅπως ξέννον ἔμον τέρψομ’ ἴδων κἀντιφιλήσομεν,<br>Νικίαν, Χαρίτων ἰμεροφώνων ἴερον φύτον,<br>καὶ σὲ τὰν ἐλέφαντος πολυμόχθω γεγενημέναν<br>δῶρον Νικιάας εἰς ὀλόχω χέρρας ὀπάσσομεν,<br>σὺν τᾷ πόλλα μὲν ἔργ’ ἐκτελέσεις ἀνδρεΐοις πέπλοις,<br>πόλλα δ’ οἷα γύναικες φορέοισ’ ὐδάτινα βράκη.<br>δὶς γὰρ μάτερες ἄρνων μαλάκοις ἐν βοτάνᾳ πόκοις<br>πέξαιντ’ αὐτοένει, Θευγένιδός γ’ ἔνεκ’ ἐυσφύρω·<br>οὕτως ἀνυσίεργος, φιλέει δ’ ὅσσα σαόφρονες.", "st": "28"}, {"sp": "N", "t": "οὐ γὰρ εἰς ἀκίρας οὐδ’ ἐς ἀέργω κεν ἐβολλόμαν<br>ὀπάσσαι σε δόμοις ἀμμετέρας ἔσσαν ἀπὺ χθόνος.<br>καὶ γάρ τοι πάτρις, ἃν ὡξ Ἐφύρας κτίσσέ ποτ’ Ἀρχίας<br>νάσω Τρινακρίας μύελον, ἄνδρων δοκίμων πόλιν.<br>νῦν μὰν οἶκον ἔχοισ’ ἄνερος, ὃς πόλλ’ ἐδάη σόφα<br>ἀνθρώποισι νόσοις φάρμακα λύγραις ἀπαλαλκέμεν,<br>οἰκήσεις κατὰ Μίλλατον ἐράνναν πεδ’Ἰαόνων,<br>ὡς εὐαλάκατος Θεύγενις ἐν δαμότισιν πέλῃ,<br>καί οἱ μνᾶστιν ἄει τῶ φιλαοίδω παρέχῃς ξένω.", "st": "28"}, {"sp": "N", "t": "κῆνο γάρ τις ἔρει τὤπος ἴδων σ’· ἦ μεγάλα χάρις<br>δώρῳ σὺν ὀλίγῳ· πάντα δὲ τίματα τὰ πὰρ φίλων.", "st": "28"}, {"sp": "SEC", "t": "ΚΘʹ — Εἰδύλλιον Ἐρῶντος", "st": "29"}, {"sp": "N", "t": "οἶνος ὦ φίλε παῖ λέγεται καὶ ἀλάθεα·<br>κἄμμε χρὴ μεθύοντας ἀλαθέας ἔμμεναι.<br>κἤγω μὲν τὰ φρενῶν ἐρέω κέατ’ ἐν μυχῷ.<br>οὐκ ὄλας φιλέειν μ’ ἐθέλησθ’ ἀπὸ καρδίας.<br>γινώσκω· τὸ γὰρ ἅμισυ τᾶς ζοΐας ἔχω<br>ζὰ τὰν σὰν ἰδέαν, τὸ δὲ λοιπὸν ἀπώλετο.<br>χὥτα μὲν σὺ θέλῃς, μακάρεσσιν ἴσαν ἄγω<br>ἁμέραν· ὅτα δ’ οὐκ ἐθέλῃς τύ, μάλ’ ἐν σκότῳ.<br>πῶς ταῦτ’ ἄρμενα, τὸν φιλέοντ’ ἀνίαις δίδων;<br>ἀλλ’ εἴ μοί τι πίθοιο νέος προγενεστέρῳ,<br>τῷ κε λώιον αὔτος ἔχων ἔμ’ ἐπαινέσαις,<br>ποίησαι καλίαν μίαν εἰν ἑνὶ δενδρίῳ,<br>ὅππῃ μηδὲν ἀπίξεται ἄγριον ὄρπετον.<br>νῦν δὲ τῶδε μὲν ἄματος ἄλλον ἔχης κλάδον,<br>ἄλλον δ’ αὔριον, ἐξ ἑτέρω δ’ ἕτερον μάτης·<br>καἰ μέν σευ τὸ κάλον τις ἴδων ῥέθος αἰνέσαι,<br>τῷ δ’ εὖθυς πλέον ἢ τριέτης ἐγένευ φίλος,<br>τὸν πρῶτον δὲ φιλεῦντα τρίταιον ἐθήκαο.<br>ἄνδρων τῶν ὑπερανορέων δοκίμοις πνέειν.<br>φίλη δ’, ἇς κ’ ἔτ’ ἔῃς, τὸν ὕμοιον ἔχην ἄει.<br>αἰ γὰρ ὧδε πόῃς, ἄγαθος μὲν ἀκούσεαι<br>ἐξ ἄστων· ὁ δέ τοί κ’ Ἔρος οὐ χαλέπως ἔχοι,<br>ὃς ἄνδρων φρένας εὐμαρέως ὑποδάμναται,<br>κἤμε μάλθακον ἐξ ἐπόησε σιδαρίω.<br>ἀλλὰ πὲρ ἀπάλω στύματός σε πεδέρχομαι<br>ὀμνάσθην, ὅτι πέρυσιν ἦσθα νεώτερος,<br>χὥτι γηραλέοι πέλομες πρὶν ἀποπτύσαι<br>καὶ ῥύσοι, νεότατα δ’ ἔχην παλινάγρετον<br>οὐκ ἔστι· πτέρυγας γὰρ ἐπομμαδίαις φόρη,<br>κἄμμες βαρδύτεροι τὰ ποτήμενα συλλάβην.", "st": "29"}, {"sp": "N", "t": "ταῦτα χρὴ νοέοντα πέλην ποτιμώτερον,<br>καί μοι τὠραμένῳ συνέραν ἀδόλως σέθεν,<br>ὅπως, ἁνίκα τὰν γένυν ἀνδρεΐαν ἔχῃς,<br>ἀλλάλοισι πελώμεθ’ Ἀχιλλέϊοι φίλοι.", "st": "29"}, {"sp": "N", "t": "αἰ δὲ ταῦτα φέρην ἀνέμοισιν ἐπιτρόπῃς,<br>ἐν θύμῳ δὲ λέγῃς “τί με δαιμόνι’ ἐνόχλης;”<br>νῦν μὲν κἠπὶ τὰ χρύσεα μᾶλ’ ἔνεκεν σέθεν<br>βαίην καὶ φύλακον νεκύων πεδὰ Κέρβερον,<br>τότα δ’ οὐδὲ καλεῦντος ἐπ’ αὐλεΐαις θύραις<br>προμόλοιμί κε παυσάμενος χαλέπω πόθω.", "st": "29"}, {"sp": "SEC", "t": "Ἐκ τῆς Βερενίκης", "st": "Berenice"}, {"sp": "N", "t": "Καἴ τις ἀνὴρ αἰτεῖται ἐπαγροσύνην τε καὶ ὄλβον,<br>ἐξ ἁλὸς ᾧ ζωή, τὰ δὲ δίκτυα κείνῳ ἄροτρα,<br>σφάζων ἀκρόνυχος ταύτῃ θεῷ ἱερὸν ἰχθύν,<br>ὃν λεῦκον καλέουσιν, ὁ γὰρ φιερώτατος ἄλλων,<br>καί κε λίνα στήσαιτο καὶ ἐξερύσαιτο θαλάσσης<br>ἔμπλεα.", "st": "Berenice"}, {"sp": "SEC", "t": "Ἐπιγράμματα"}, {"sp": "N", "t": "τὰ ῥόδα τὰ δροσόεντα καὶ ἁ κατάπυκνος ἐκείνα<br>ἕρπυλλος κεῖται ταῖς Ἑλικωνιάσι,<br>ταὶ δὲ μελάμφυλλοι δάφναι τὶν Πύθιε Παιάν,<br>Δελφὶς ἐπεὶ πέτρα τοῦτό τοι ἀγλάισε.<br>βωμὸν δ’ αἱμαξεῖ κεραὸς τράγος οὗτος ὁ μαλός,<br>τερμίνθου τρώγων ἔσχατον ἀκρεμόνα.", "st": "E.1"}, {"sp": "N", "t": "Δάφνις ὁ λευκόχρως, ὁ καλᾷ σύριγγι μελίσδων<br>βουκολικοὺς ὕμνους, ἄνθετο Πανὶ τάδε,<br>τοὺς τρητοὺς δόνακας, τὸ λαγωβόλον, ὀξὺν ἄκοντα,<br>νεβρίδα, τὰν πήραν, ᾇ ποκ’ ἐμαλοφόρει.", "st": "E.2"}, {"sp": "N", "t": "εὕδεις φυλλοστρῶτι πέδῳ Δάφνι σῶμα κεκμακὸς<br>ἀμπαύων· στάλικες δ’ ἀρτιπαγεῖς ἀν’ ὄρη.<br>ἀγρεύει δέ τυ Πὰν καὶ ὁ τὸν κροκόεντα Πρίηπος<br>κισσὸν ἐφ’ ἱμερτῷ κρατὶ καθαπτόμενος,<br>ἄντρον ἔσω στείχοντες ὁμόρροθοι. ἀλλὰ τὺ φεῦγε,<br>φεῦγε μεθεὶς ὕπνου κῶμα καταγρόμενον.", "st": "E.3"}, {"sp": "N", "t": "τήναν τὰν λαύραν τάς τε δρύας αἰπόλε κάμψας<br>σύκινον εὑρήσεις ἀρτιγλυφὲς ξόανον,<br>τρισκελὲς αὐτόφλοιον ἀνούατον, ἀλλὰ φάλητι<br>παιδογόνῳ δυνατὸν Κύπριδος ἔργα τελεῖν.<br>σακός οἱ ἱερὸς περιδέδρομεν, ἀέναον δὲ<br>ῥεῖθρον ἀπὸ σπιλάδων πάντοσε τηλεθάει<br>δάφναις καὶ μύρτοισι καὶ εὐώδει κυπαρίσσῳ.<br>ἔνθα πέριξ κέχυται βοτρυόπαις ἕλικι<br>ἄμπελος, εἰαρινοὶ δὲ λιγυφθόγγοισιν ἀοιδαῖς<br>κόσσυφοι ἀχεῦσιν ποικιλότραυλα μέλη.<br>ξουθαὶ δ’ ἀδονίδες μινυρίσμασιν ἀνταχεῦσι<br>μέλπουσαι στόμασιν τὰν μελίγαρυν ὄπα.<br>ἕζεο δὴ τηνεῖ καὶ τῷ χαρίεντι Πριήπῳ<br>εὔχε’ ἀποστέρξαι τοὺς Δάφνιδός με πόθους,<br>κεὐθὺς ἐπιρρέξειν χίμαρον καλόν. ἢν δ’ ἀνανεύσῃ,<br>τοῦδε τυχὼν ἐθέλω τρισσὰ θύη τελέσαι·<br>ῥέξω γὰρ δαμάλαν, λάσιον τράγον, ἄρνα τὸν ἴσχω<br>σακίταν. ἀίοι δ’ εὐμενέως ὁ θεός.", "st": "E.4"}, {"sp": "N", "t": "λῇς ποτὶ τᾶν Νυμφᾶν διδύμοις αὐλοῖσιν ἀεῖσαι<br>ἁδύ τί μοι; κἠγὼ πακτίδ’ ἀειράμενος<br>ἀρξεῦμαί τι κρέκειν, ὁ δὲ βουκόλος ἄμμιγα θελξεῖ<br>Δάφνις, κηροδέτῳ πνεύματι μελπόμενος.<br>ἐγγὺς δὲ στάντες λασίας δρυὸς ἄντρου ὄπισθεν<br>Πᾶνα τὸν αἰγιβάταν ὀρφανίσωμες ὕπνου.", "st": "E.5"}, {"sp": "N", "t": "Ἆ δειλαῖε τὺ Θύρσι, τί τὸ πλέον, εἰ καταταξεῖς<br>δάκρυσι διγλήνους ὦπας ὀδυρόμενος;<br>οἴχεται ἁ χίμαρος, τὸ καλὸν τέκος, οἴχετ’ ἐς Ἅιδαν·<br>τραχὺς γὰρ χαλαῖς ἀμφεπίαξε λύκος.<br>αἱ δὲ κύνες κλαγγεῦντι· τί τὸ πλέον, ἁνίκα τήνας<br>ὀστίον οὐδὲ τέφρα λείπεται οἰχομένας;", "st": "E.6"}, {"sp": "N", "t": "νήπιον υἱὸν ἔλειπες, ἐν ἁλικίᾳ δὲ καὶ αὐτός,<br>Εὐρύμεδον τύμβου τοῦδε θανὼν ἔτυχες.<br>σοὶ μὲν ἕδρα θείοισι μετ’ ἀνδράσι· τὸν δὲ πολῖται<br>τιμασεῦντι, πατρὸς μνώμενοι ὡς ἀγαθοῦ.", "st": "E.7"}, {"sp": "N", "t": "Ἦλθε καὶ ἐς Μίλητον ὁ τοῦ Παιήονος υἱός,<br>ἰητῆρι νόσων ἀνδρὶ συνοισόμενος<br>Νικίᾳ, ὅς μιν ἐπ’ ἦμαρ ἀεὶ θυέεσσιν ἱκνεῖται,<br>καὶ τόδ’ ἀπ’ εὐώδους γλύψατ’ ἄγαλμα κέδρου,<br>Ἠετίωνι χάριν γλαφυρᾶς χερὸς ἄκρον ὑποστὰς<br>μισθόν· ὁ δ’ εἰς ἔργον πᾶσαν ἀφῆκε τέχνην.", "st": "E.8"}, {"sp": "N", "t": "ξεῖνε, Συρακόσιός τοι ἀνὴρ τόδ’ ἐφίεται Ὄρθων·<br>χειμερίας μεθύων μηδαμὰ νυκτὸς ἴοις.<br>καὶ γὰρ ἐγὼ τοιοῦτον ἔχω πότμον· ἀντὶ δὲ πολλᾶς<br>πατρίδος ὀθνείαν κεῖμαι ἐφεσσάμενος.", "st": "E.9"}, {"sp": "N", "t": "Ὑμῖν τοῦτο θεαὶ κεχαρισμένον ἐννέα πάσαις<br>τὤγαλμα Ξενοκλῆς θῆκε τὸ μαρμάρινον,<br>μουσικός· οὐχ ἑτέρως τις ἐρεῖ. σοφίῃ δ’ ἐπὶ τῇδε<br>αἶνον ἔχων Μουσέων οὐκ ἐπιλανθάνεται.", "st": "E.10"}, {"sp": "N", "t": "Εὐσθένεος τὸ μνῆμα· φυσιγνώμων ὁ σοφιστής,<br>δεινὸς ἀπ’ ὀφθαλμοῦ καὶ τὸ νόημα μαθεῖν.<br>εὖ μιν ἔθαψαν ἑταῖροι ἐπὶ ξείνης ξένον ὄντα·<br>χὑμνοθέτης αὐτοῖς δαιμονίως φίλος ἦν.<br>πάντων ὧν ἐπέοικεν ἔχειν τεθνεὼς ὁ σοφιστὴς<br>καίπερ ἄκικυς ἐὼν εἶχ’ ἄρα κηδεμόνας.", "st": "E.11"}, {"sp": "N", "t": "Δημομέλης ὁ χορηγός, ὁ τὸν τρίποδ’ ὦ Διόνυσε<br>καὶ σὲ τὸν ἥδιστον θεῶν μακάρων ἀναθείς,<br>μέτριος ἦν ἐν πᾶσι, χορῷ δ’ ἐκτήσατο νίκην<br>ἀνδρῶν, καὶ τὸ καλὸν καὶ τὸ προσῆκον ὁρῶν.", "st": "E.12"}, {"sp": "N", "t": "Ἡ Κύπρις οὐ πάνδημος. ἱλάσκεο τὴν θεὸν εἰπὼν<br>οὐρανίην, ἁγνῆς ἄνθεμα Χρυσογόνης<br>οἴκῳ ἐν Ἀμφικλέους, ᾧ καὶ τέκνα καὶ βίον εἶχε<br>ξυνόν. ἀεὶ δέ σφιν λώιον εἰς ἔτος ἦν<br>ἐκ σέθεν ἀρχομένοις ὦ πότνια· κηδόμενοι γὰρ<br>ἀθανάτων αὐτοὶ πλεῖον ἔχουσι βροτοί.", "st": "E.13"}, {"sp": "N", "t": "Ἀστοῖς καὶ ξείνοισιν ἴσον νέμει ἥδε τράπεζα·<br>θεὶς ἀνελοῦ ψήφου πρὸς λόγον ἐρχομένης.<br>ἄλλός τις πρόφασιν λεγέτω· τὰ δ’ ὀθνεῖα Κάικος<br>χρήματα καὶ νυκτὸς βουλομένοις ἀριθμεῖ.", "st": "E.14"}, {"sp": "N", "t": "γνώσομαι, εἴ τι νέμεις ἀγαθοῖς πλέον, ἢ καὶ ὁ δειλὸς<br>ἐκ σέθεν ὡσαύτως ἶσον ὁδοιπόρ’ ἔχει.<br>“χαιρέτω οὗτος ὁ τύμβος” ἐρεῖς “ἐπεὶ Εὐρυμέδοντος<br>κεῖται τῆς ἱερῆς κοῦφος ὑπὲρ κεφαλῆς.”", "st": "E.15"}, {"sp": "N", "t": "θᾶσαι τὸν ἀνδριάντα τοῦτον ὦ ξένε<br>σπουδᾷ, καὶ λέγ’ ἐπὴν ἐς οἶκον ἔνθῃς·<br>“Ἀνακρέοντος εἰκόν’ εἶδον ἐν Τέῳ<br>τῶν πρόσθ’ εἴ τι περισσὸν ᾠδοποιοῦ.”<br>προσθεὶς δὲ χὥτι τοῖς νέοισιν ἅδετο,<br>ἐρεῖς ἀτρεκέως ὅλον τὸν ἄνδρα.", "st": "E.17"}, {"sp": "N", "t": "Ἅ τε φωνὰ Δώριος χὡνὴρ ὁ τὰν κωμῳδίαν<br>εὑρὼν Ἐπίχαρμος.<br>ὦ Βάκχε, χάλκεόν νιν ἀντ’ ἀλαθινοῦ<br>τὶν ὧδ’ ἀνέθηκαν<br>τοὶ Συρακόσσαις ἐνίδρυνται πεδωρισταὶ πόλει,<br>οἷ’ ἀνδρὶ πολίτᾳ·<br>σωρὸν γὰρ εἶχε ῥημάτων μεμναμένοις<br>τελεῖν ἐπίχειρα.<br>πολλὰ γὰρ πὸτ τὰν ζόαν τοῖς πᾶσιν εἶπε χρήσιμα.<br>μεγάλα χάρις αὐτῷ.", "st": "E.18"}, {"sp": "N", "t": "Ὁ μουσοποιὸς ἐνθάδ’ Ἱππῶναξ κεῖται.<br>εἰ μὲν πονηρός, μὴ ποτέρχευ τῷ τύμβῳ·<br>εἰ δ’ ἐσσὶ κρήγυός τε καὶ παρὰ χρηστῶν,<br>θαρσέων καθίζευ, κἢν θέλῃς ἀπόβριξον.", "st": "E.19"}, {"sp": "N", "t": "Ὁ μικκὸς τόδ’ ἔτευξε τᾷ Θραΐσσᾳ<br>Μήδειος τὸ μνᾶμ’ ἐπὶ τᾷ ὁδῷ κἠπέγραψε Κλείτας.<br>ἑξεῖ τὰν χάριν ἁ γυνὰ ἀντὶ τήνων,<br>ὧν τὸν κοῦρον ἔθρεψε. τί μάν; ἔτι χρησίμα καλεῖται.", "st": "E.20"}, {"sp": "N", "t": "Ἀρχίλοχον καὶ στᾶθι καὶ εἴσιδε τὸν πάλαι ποιητὰν<br>τὸν τῶν ἰάμβων, οὗ τὸ μυρίον κλέος<br>διῆλθε κἠπὶ νύκτα καὶ πρὸς ἀῶ.<br>ἦ ῥά νιν αἱ Μοῖσαι καὶ ὁ Δάλιος ἠγάπευν Ἀπόλλων,<br>ὡς ἐμμελής τ’ ἔγεντο κἠπιδέξιος<br>ἔπεά τε ποιεῖν πρὸς λύραν τ’ ἀείδειν.", "st": "E.21"}, {"sp": "N", "t": "τὸν τοῦ Ζανὸς ὅδ’ ὗμιν υἱὸν ὡνὴρ<br>τὸν λεοντομάχαν, τὸν ὀξύχειρα,<br>πρᾶτος τῶν ἐπάνωθε μουσοποιῶν<br>Πείσανδρος συνέγραψεν ὡκ Καμίρου<br>χὥσους ἐξεπόνασεν εἶπ’ ἀέθλους.<br>τοῦτον δ’ αὐτὸν ὁ δᾶμος, ὡς σάφ’ εἰδῇς,<br>ἔστασ’ ἐνθάδε χάλκεον ποιήσας<br>πολλοῖς μησὶν ὄπισθε κἠνιαυτοῖς.", "st": "E.22"}], []);})();
